// Yazılım Terim Defteri: içerik dosyası.
// Kural: her sorunun ilk şıkkı doğru cevaptır; uygulama şıkları karıştırarak gösterir.
var MODULES = [];
function add(m, name, terms) {
  var x = MODULES.find(function (y) { return y.no === m; });
  if (!x) { x = { no: m, name: name, terms: [] }; MODULES.push(x); }
  x.terms.push.apply(x.terms, terms);
}

add(1,`Temeller`,[
{no:1,tr:`Yazılım`,en:`Software`,
def:`Yazılım, bilgisayara bir işi nasıl yapacağını adım adım söyleyen talimatlar bütünüdür.`,
an:`Donanım piyano ise yazılım notadır. Piyano tek başına çalmaz; nota değişince aynı piyano başka şarkı çalar.`,
fi:`Basit bir giriş ekranının arkasındaki talimatlar:`,
code:[`START`,
`  GET şifre FROM kullanıcı            // girdi: dışarıdan bilgi alır`,
`  IF şifre == kayıtlı_şifre THEN      // karar: talimata göre kontrol eder`,
`      SHOW "Giriş başarılı"           // çıktı: sonucu gösterir`,
`  ELSE`,
`      SHOW "Hatalı şifre"             // çıktı: alternatif sonuç`,
`  END IF`,
`END`],
note:`Bilgisayar bu satırları kendi kafasına göre değil, yazıldığı sırayla ve yazıldığı gibi uygular. Yazılım tam olarak budur.`,
qs:[
{t:`Aşağıdakilerden hangisi yazılımdır?`,o:[`Telefonun kamera uygulaması`,`Laptop'un şarj aleti`,`Telefonun kamera lensi`,`Router cihazı`],e:`Lens fiziksel parça, yani donanım. Uygulama ise lense ne zaman fotoğraf çekeceğini söyleyen talimatlar, yani yazılım.`},
{t:`Aynı bilgisayarda hem Chrome hem Excel çalışabiliyor. Bu ne anlama gelir?`,o:[`Aynı donanım, farklı talimatlarla farklı işler yapabilir`,`Chrome ve Excel aslında aynı yazılımdır`,`Her yazılım için ayrı bir bilgisayar gerekir`,`Yazılım fabrikada donanımın içine sabitlenir`],e:`Piyano aynı, nota farklı. Bilgisayar değişmiyor, ona verilen talimatlar değişiyor.`},
{t:`Teknik bilgisi olmayan birine yazılımı en doğru hangi cümle anlatır?`,o:[`Bilgisayara ne yapacağını adım adım söyleyen talimatlardır`,`Bilgisayarın içindeki elektronik parçalardır`,`İnternete bağlanmayı sağlayan sistemdir`,`Ekranda gördüğümüz renkli görüntülerdir`],e:`Parçalar donanımdır, internet bir bağlantı ortamıdır, ekran görüntüsü ise sadece çıktıdır. Yazılım talimatın kendisidir.`}
]},
{no:2,tr:`Donanım`,en:`Hardware`,
def:`Donanım, yazılımın talimatlarını fiziksel olarak yerine getiren, elle dokunulabilen parçaların bütünüdür.`,
an:`Tekme atabiliyorsan donanımdır; sadece sinirlenebiliyorsan yazılımdır. Masa benzetmesi: işlemci masada çalışan kişi, RAM çalışma masası, disk ise dolap.`,
fi:`Giriş ekranındaki talimatlar, bu sefer her satırın arkasındaki donanımla:`,
code:[`START`,
`  GET şifre FROM klavye                // girdi cihazı: klavye`,
`  LOAD kayıtlı_şifre FROM disk         // kalıcı hafıza: disk`,
`  STORE şifre IN RAM                   // geçici hafıza: RAM`,
`  IF şifre == kayıtlı_şifre THEN       // karşılaştırmayı işlemci yapar`,
`      SHOW "Giriş başarılı" ON ekran   // çıktı cihazı: ekran`,
`  ELSE`,
`      SHOW "Hatalı şifre" ON ekran`,
`  END IF`,
`END`],
note:`Yazılım tek başına hiçbir şey yapamaz, donanım da öyle. Biri talimatı verir, diğeri uygular. RAM'deki bilgi elektrik kesilince silinir; diskteki bilgi kalır.`,
qs:[
{t:`Aşağıdakilerden hangisi donanım değildir?`,o:[`Windows`,`RAM`,`Klavye`,`Ekran kartı`],e:`Windows bir işletim sistemi, yani yazılım. Ona tekme atamazsın; RAM'e, klavyeye ve ekran kartına atabilirsin.`},
{t:`Bilgisayar aniden kapandı ve kaydetmediğin Word belgesi kayboldu. Belge o an hangi donanımda duruyordu?`,o:[`RAM`,`Disk`,`İşlemci (CPU)`,`Ekran`],e:`Kaydetmediğin belge çalışma masasında, yani RAM'deydi. Elektrik kesilince masa temizlendi. Kaydetseydin dolaba, yani diske yazılırdı.`},
{t:`"IF şifre == kayıtlı_şifre" karşılaştırmasını hangi donanım yapar?`,o:[`İşlemci (CPU)`,`Disk`,`Klavye`,`RAM`],e:`Hesaplamayı ve karşılaştırmayı masada çalışan kişi, yani işlemci yapar. Disk ve RAM bilgiyi tutar, klavye sadece girdiyi alır.`}
]},
{no:3,tr:`Girdi / Çıktı`,en:`Input / Output`,
def:`Girdi yazılıma dışarıdan gelen bilgidir; çıktı ise yazılımın bu bilgiyi işledikten sonra dışarıya verdiği sonuçtur.`,
an:`Çay makinesi: su ve çay yaprağı girdi, demlenmiş çay çıktı. Aradaki demleme işi yazılımın kendisi. Kısaca: al, işle, ver.`,
fi:`Fatura tutarını hesaplayan basit bir akış:`,
code:[`START`,
`  GET dakika FROM kullanıcı              // girdi`,
`  GET dakika_ücreti FROM sistem          // girdi`,
`  SET tutar = dakika * dakika_ücreti     // işle`,
`  IF tutar > 1000 THEN`,
`      SHOW "Yüksek fatura uyarısı"       // çıktı`,
`  END IF`,
`  SHOW tutar                             // çıktı`,
`END`],
note:`Girdi sadece klavyeden gelmez; bir dosya, bir sensör ya da başka bir sistemin gönderdiği veri de girdidir. Çıktı da sadece ekran değildir; dosya, e-posta ya da başka sisteme giden cevap olabilir.`,
qs:[
{t:`ATM'ye kartını takıp şifreni giriyor ve para çekiyorsun. Hangisi çıktıdır?`,o:[`Hazneden çıkan para`,`Takılan kart`,`Girilen şifre`,`Seçilen tutar`],e:`Kart, şifre ve tutar ATM'ye dışarıdan verilen bilgiler, yani girdi. Para işlemin sonunda dışarı verilen çıktıdır.`},
{t:`Bir yazılım, başka bir sistemin gönderdiği veriyi alıp işliyor. Bu veri yazılım için nedir?`,o:[`Girdi`,`Çıktı`,`Donanım`,`Hata`],e:`Girdinin klavyeden gelmesi gerekmez. Yazılıma dışarıdan gelen her bilgi girdidir, kaynağı başka bir sistem olsa bile.`},
{t:`"Al, işle, ver" üçlüsünde "ver" neyi anlatır?`,o:[`Çıktıyı`,`Girdiyi`,`İşlemciyi`,`Kaynak kodu`],e:`Al girdidir, işle yazılımın yaptığı iştir, ver ise sonucun dışarıya verilmesi yani çıktıdır.`}
]},
{no:4,tr:`Algoritma`,en:`Algorithm`,
def:`Algoritma, bir problemi çözmek için izlenen, sırası belli ve bir noktada biten adımlar dizisidir.`,
an:`Yemek tarifi bir algoritmadır: adımlar sıralı ve sonunda yemek hazır. Tarif kâğıtta durur; kodla bilgisayara yazdığında yazılım olur.`,
fi:`Bir listedeki en büyük sayıyı bulma algoritması:`,
code:[`START`,
`  GET sayılar FROM liste`,
`  SET en_büyük = sayılar[0]          // ilk sayıyı aday kabul et`,
`  FOR EACH sayı IN sayılar           // sayılara tek tek bak`,
`      IF sayı > en_büyük THEN`,
`          SET en_büyük = sayı        // daha büyükse adayı değiştir`,
`      END IF`,
`  END FOR`,
`  SHOW en_büyük`,
`END`],
note:`Algoritma dilden bağımsızdır. Aynı adımlar Java'da da Python'da da aynıdır; değişen sadece yazım şeklidir.`,
qs:[
{t:`Hangisi algoritmanın özelliği değildir?`,o:[`Adımların rastgele sırayla yapılması`,`Adımların sırasının belli olması`,`Bir noktada bitmesi`,`Bir problemi çözmeye yönelik olması`],e:`Algoritmada sıra önemlidir. Rastgele sırayla yapılan adımlar her seferinde aynı sonucu vermez.`},
{t:`Algoritma ile yazılım arasındaki ilişki nedir?`,o:[`Algoritma çözümün tarifidir, yazılım bu tarifin bilgisayarda çalışan halidir`,`Algoritma ve yazılım tamamen aynı şeydir`,`Algoritma sadece donanımda çalışır`,`Algoritma yazılımın görsel tasarımıdır`],e:`Tarif kâğıtta durur, pişirilince yemek olur. Algoritma da kodla yazılıp çalıştırılınca yazılım olur.`},
{t:`Hangisi bir algoritma örneğidir?`,o:[`Navigasyonun en kısa yolu bulmak için izlediği adımlar`,`Bilgisayarın kasası`,`Bir web sitesinin logosu`,`Ekranın parlaklık seviyesi`],e:`Navigasyon bir problemi, yani en kısa yolu, belli adımlarla çözüyor. Diğerleri adımlar dizisi değil.`}
]},
{no:5,tr:`Kaynak Kod`,en:`Source Code`,
def:`Kaynak kod, bir programın insanların okuyup yazabileceği bir programlama diliyle yazılmış metin halidir.`,
an:`Kaynak kod binanın mimari çizimidir. Usta, yani bilgisayar, çizime bakarak binayı yapar; çizimi değiştirirsen bina da değişir.`,
fi:`Aynı kuralın pseudo code ve Java kaynak kodu hali:`,
code:[`// Pseudo code`,
`IF yaş >= 18 THEN SHOW "Giriş serbest"`,
``,
`// Java kaynak kodu`,
`if (yas >= 18) {`,
`    System.out.println("Giriş serbest");`,
`}`],
note:`Kaynak kod genelde Git gibi bir versiyon kontrol sisteminde saklanır. Geliştiricinin "koda bakayım" dediği şey kaynak koddur.`,
qs:[
{t:`Kaynak kodun en temel özelliği nedir?`,o:[`İnsanların okuyup yazabileceği bir dilde olması`,`Sadece 0 ve 1'lerden oluşması`,`Donanımın içine gömülü olması`,`Sadece ekranda görünmesi`],e:`Kaynak kod insanlar için yazılır. Bilgisayarın doğrudan anladığı 0-1'li hal makine kodudur.`},
{t:`Bir geliştirici "kodu değiştirdim" diyor. Neyi değiştirmiştir?`,o:[`Programın kaynak kodunu`,`Bilgisayarın donanımını`,`Kullanıcının girdiği veriyi`,`Ekranın çözünürlüğünü`],e:`Geliştiricinin üzerinde çalıştığı şey programın metin hali, yani kaynak koddur.`},
{t:`Mimari çizim benzetmesinde "çizimi değiştirmek" neye karşılık gelir?`,o:[`Kaynak kodu değiştirip programın davranışını değiştirmeye`,`Bilgisayarı yenisiyle değiştirmeye`,`Programı kapatıp açmaya`,`Ekranı büyütmeye`],e:`Çizim değişirse bina değişir; kaynak kod değişirse program farklı davranır.`}
]}
]);

add(1,`Temeller`,[
{no:6,tr:`Programlama Dili`,en:`Programming Language`,
def:`Programlama dili, talimatları bilgisayarın anlayabileceği kurallarla yazmamızı sağlayan, kendi kelimeleri ve dil bilgisi olan yapay bir dildir.`,
an:`Türkçe ve İngilizce gibi düşün: "Merhaba" ile "Hello" aynı şeyi söyler. Java ile Python da aynı talimatı farklı kelime ve kurallarla yazar.`,
fi:`Aynı talimat, farklı dillerde:`,
code:[`// Pseudo code`,
`SHOW "Merhaba"`,
``,
`// Python`,
`print("Merhaba")`,
``,
`// Java`,
`System.out.println("Merhaba");`,
``,
`// JavaScript`,
`console.log("Merhaba");`],
note:`Her dilin bir sözdizimi (syntax) vardır. Bir noktalı virgülü unutmak bile kodun çalışmamasına yeter; bu hataya syntax error denir.`,
qs:[
{t:`Java, Python ve JavaScript'in ortak noktası nedir?`,o:[`Üçü de programlama dilidir`,`Üçü de işletim sistemidir`,`Üçü de donanım parçasıdır`,`Üçü de veritabanıdır`],e:`Üçü de talimat yazmak için kullanılan programlama dilleridir; kelimeleri ve kuralları farklıdır.`},
{t:`Dilin yazım kurallarına uymayan koda hangi hata verilir?`,o:[`Syntax error`,`Timeout`,`404 Not Found`,`Deploy error`],e:`Sözdizimi kurallarına uymayan kod daha çalışmadan hata verir; buna syntax error denir.`},
{t:`Aynı işi yapan bir program hem Java'da hem Python'da yazılıyor. Ne söylenebilir?`,o:[`Algoritma aynı kalır, sadece yazım kuralları değişir`,`İki program mutlaka farklı sonuç üretir`,`Python ile yazılan program donanım gerektirmez`,`Java ile yazılan program algoritma içermez`],e:`Çözümün adımları dilden bağımsızdır. Dil değişince değişen şey yazım şeklidir.`}
]},
{no:7,tr:`Derleyici / Yorumlayıcı`,en:`Compiler / Interpreter`,
def:`Derleyici ve yorumlayıcı, kaynak kodu bilgisayarın çalıştırabileceği hale çeviren programlardır; derleyici önce tamamını çevirir, yorumlayıcı satır satır çevirip çalıştırır.`,
an:`Derleyici kitap çevirmenidir: kitabın tamamını çevirip basar, sonra okursun. Yorumlayıcı simultane tercümandır: konuşmacı konuştukça cümle cümle çevirir.`,
fi:`İki yaklaşımın akışı:`,
code:[`// Derleyici (Java, C#, Go): önce tamamı çevrilir`,
`START`,
`  CALL derle(tüm_kod)`,
`  IF hata_var THEN`,
`      SHOW "Compile error"          // hiçbir satır çalışmaz`,
`  ELSE`,
`      RUN makine_kodu`,
`  END IF`,
`END`,
``,
`// Yorumlayıcı (Python, JavaScript): satır satır`,
`FOR EACH satır IN kaynak_kod`,
`    RUN satır                       // hata o satıra gelince çıkar`,
`END FOR`],
note:`Java ikisinin karışımıdır: önce bytecode'a derlenir, sonra JVM üzerinde çalışır. Build sırasında alınan "compile error" derleyiciden gelir.`,
qs:[
{t:`Derleyicinin temel işi nedir?`,o:[`Kaynak kodu çalışmadan önce bütünüyle çalıştırılabilir hale çevirmek`,`Kodu internete yüklemek`,`Veritabanını yedeklemek`,`Ekran tasarımı çizmek`],e:`Derleyici kitap çevirmeni gibi önce tamamını çevirir, sonra program çalışır.`},
{t:`Simultane tercüman benzetmesi hangisine uyar?`,o:[`Yorumlayıcı`,`Derleyici`,`Veritabanı`,`İşlemci`],e:`Yorumlayıcı kodu satır satır, konuşma ilerledikçe çevirip çalıştırır.`},
{t:`Derlenen bir dilde kodun son satırında yazım hatası var. Ne olur?`,o:[`Program hiç çalışmaz, derleme hatası alınır`,`İlk satırlar çalışır, son satırda durur`,`Hata görmezden gelinir`,`Program iki kez çalışır`],e:`Derleyici önce tamamını çevirir; tek bir hata bile çeviriyi durdurur. Yorumlayıcıda ise ilk satırlar çalışırdı.`}
]},
{no:8,tr:`Veri ve Veri Tipi`,en:`Data and Data Type`,
def:`Veri, yazılımın işlediği bilgidir; veri tipi ise bu bilginin türünü (sayı, metin, doğru/yanlış, tarih) belirleyip onunla hangi işlemlerin yapılabileceğini tanımlar.`,
an:`Mutfakta malzemeyi uygun kaba koyarsın: süt şişeye, un kavanoza. Veri tipi verinin kabıdır; süt kavanoza konmadığı gibi metinle de çarpma yapılmaz.`,
fi:`Temel veri tipleri ve bir tip hatası:`,
code:[`SET müşteri_adı = "Ayşe Yılmaz"     // String: metin`,
`SET yaş = 34                        // Integer: tam sayı`,
`SET fatura_tutarı = 249.90          // Decimal: ondalıklı sayı`,
`SET aktif_mi = true                 // Boolean: doğru / yanlış`,
`SET kayıt_tarihi = 2026-11-01       // Date: tarih`,
``,
`SET toplam = yaş + müşteri_adı      // hata: sayı + metin`],
note:`"34" ile 34 aynı değildir: ilki metin, ikincisi sayıdır. API'lerde sık görülen hatalardan biri, sayı beklenen alana metin gönderilmesidir.`,
qs:[
{t:`true / false değerlerini tutan veri tipi hangisidir?`,o:[`Boolean`,`String`,`Integer`,`Date`],e:`Boolean yalnızca iki değer alır: doğru (true) ya da yanlış (false).`},
{t:`"34" ile 34 arasındaki fark nedir?`,o:[`İlki metin (String), ikincisi sayı (Integer)`,`İkisi tamamen aynıdır`,`İlki tarih, ikincisi metindir`,`İlki ondalıklı, ikincisi tam sayıdır`],e:`Tırnak içindeki her şey metindir. "34" ile toplama yapılamaz, 34 ile yapılır.`},
{t:`249,90 TL'lik bir fatura tutarı için en uygun veri tipi hangisidir?`,o:[`Ondalıklı sayı (Decimal)`,`Boolean`,`Date`,`Tam sayı (Integer)`],e:`Kuruş kısmı olduğu için tam sayı yetmez. Para tutarları için genelde Decimal kullanılır.`}
]},
{no:9,tr:`Değişken`,en:`Variable`,
def:`Değişken, bir veriyi daha sonra kullanmak üzere bir isimle hafızada saklayan ve değeri program çalışırken değişebilen bir kutudur.`,
an:`Değişken etiketli bir kutudur: etikette "bakiye" yazar, içinde 500 vardır. Para çekince kutunun içi değişir, etiket aynı kalır.`,
fi:`Bakiyenin bir değişkenle takibi:`,
code:[`SET bakiye = 500                    // kutu oluştu, içinde 500`,
`GET çekilen FROM kullanıcı          // örn: 200`,
`IF çekilen <= bakiye THEN`,
`    SET bakiye = bakiye - çekilen   // kutunun içi değişti: 300`,
`    SHOW bakiye`,
`ELSE`,
`    SHOW "Yetersiz bakiye"`,
`END IF`],
note:`Değeri hiç değişmeyecek kutulara sabit (constant) denir, örneğin KDV_ORANI. İyi isimler kodu okunur yapar: x yerine fatura_tutarı yazmak gibi.`,
qs:[
{t:`Değişken için en doğru benzetme hangisidir?`,o:[`Üzerinde etiket olan, içi değişebilen bir kutu`,`Bilgisayarın fiziksel bir parçası`,`Programın kapanma komutu`,`Ekrandaki bir buton`],e:`Etiket değişkenin adı, kutunun içi değeridir. İçerik değişebilir, ad aynı kalır.`},
{t:`SET bakiye = 500 ve ardından SET bakiye = bakiye - 200 çalıştı. bakiye'nin son değeri nedir?`,o:[`300`,`500`,`200`,`700`],e:`Kutudaki 500'den 200 çıkarıldı ve sonuç aynı kutuya geri kondu: 300.`},
{t:`Değeri program boyunca hiç değişmeyen değişkene ne denir?`,o:[`Sabit (Constant)`,`Döngü`,`Fonksiyon`,`Parametre`],e:`KDV oranı ya da pi sayısı gibi değişmeyen değerler sabit olarak tanımlanır.`}
]},
{no:10,tr:`Koşul`,en:`Condition · IF / ELSE`,
def:`Koşul, yazılımın bir durumun doğru ya da yanlış olmasına göre farklı adımları seçmesini sağlayan karar yapısıdır.`,
an:`Yol ayrımındaki tabela: "Yağmur yağıyorsa şemsiye al, yağmıyorsa güneş gözlüğü." Yazılım her IF'te bir yol ayrımına gelir ve tek bir yola girer.`,
fi:`Paket önerisinde sıralı koşullar:`,
code:[`GET kullanım_gb FROM müşteri`,
`IF kullanım_gb > 50 THEN`,
`    SHOW "Sınırsız paket öner"`,
`ELSE IF kullanım_gb > 20 THEN`,
`    SHOW "50 GB paket öner"`,
`ELSE`,
`    SHOW "Mevcut paket yeterli"`,
`END IF`],
note:`Koşullar sırayla kontrol edilir ve ilk doğru olanın bloğu çalışır. Her IF dalı için en az bir test senaryosu düşünmek gerekir; buna dal kapsamı (branch coverage) denir.`,
qs:[
{t:`Kullanım 35 GB ise ekranda ne görünür?`,o:[`50 GB paket öner`,`Sınırsız paket öner`,`Mevcut paket yeterli`,`Hiçbir şey görünmez`],e:`35, 50'den büyük değil ama 20'den büyük. İkinci koşul doğru olduğu için o dal çalışır.`},
{t:`ELSE bloğu ne zaman çalışır?`,o:[`Üstündeki koşulların hiçbiri doğru olmadığında`,`Her zaman`,`IF doğru olduğunda`,`Sadece program kapanırken`],e:`ELSE "hiçbiri tutmadıysa" demektir; diğer dallar boşa düştüğünde çalışır.`},
{t:`Kullanım tam 50 GB ise hangi mesaj çıkar?`,o:[`50 GB paket öner`,`Sınırsız paket öner`,`Mevcut paket yeterli`,`Hata verir`],e:`50 > 50 yanlıştır, sınır dahil değil. 50 > 20 doğru olduğu için ikinci dal çalışır. Sınır değerleri en çok hata çıkan yerlerdir.`}
]}
]);

add(2,`Kodun yapı taşları`,[
{no:11,tr:`Döngü`,en:`Loop`,
def:`Döngü, aynı adımları bir koşul sağlandığı sürece ya da bir listedeki her eleman için tekrar tekrar çalıştıran yapıdır.`,
an:`Merdiven çıkmak gibi: "Son basamağa gelene kadar bir adım at." Aynı hareketi tekrarlıyorsun ve ne zaman duracağın belli.`,
fi:`Müşterilere fatura SMS'i göndermek ve bağlantıyı en fazla 3 kez denemek:`,
code:[`GET müşteriler FROM veritabanı`,
`FOR EACH müşteri IN müşteriler            // her müşteri için tekrar`,
`    IF müşteri.borç > 0 THEN`,
`        SEND "Faturanız hazır" TO müşteri.telefon`,
`    END IF`,
`END FOR`,
``,
`SET deneme = 0`,
`WHILE deneme < 3                         // koşul sürdükçe tekrar`,
`    CALL bağlan()`,
`    SET deneme = deneme + 1`,
`END WHILE`],
note:`Durma koşulu hiç sağlanmayan döngüye sonsuz döngü (infinite loop) denir; program kilitlenir ya da kaynakları tüketir.`,
qs:[
{t:`FOR EACH döngüsü ne yapar?`,o:[`Listedeki her eleman için aynı adımları çalıştırır`,`Programı tek seferde sonlandırır`,`Sadece ilk elemanı işler`,`Listedeki veriyi siler`],e:`FOR EACH listeyi baştan sona dolaşır ve her eleman için bloğu bir kez çalıştırır.`},
{t:`Durma koşulu hiç gerçekleşmeyen döngüye ne denir?`,o:[`Sonsuz döngü`,`Koşul`,`Sabit`,`Derleme hatası`],e:`Koşul hep doğru kalırsa döngü hiç bitmez; buna sonsuz döngü denir.`},
{t:`deneme 0'dan başlıyor, her turda 1 artıyor ve koşul "deneme < 3". Döngü kaç kez çalışır?`,o:[`3`,`2`,`4`,`Sonsuz`],e:`deneme 0, 1 ve 2 iken çalışır. 3 olunca koşul yanlış olur ve döngü biter.`}
]},
{no:12,tr:`Fonksiyon / Metot`,en:`Function / Method`,
def:`Fonksiyon, belirli bir işi yapan, bir isimle çağrılabilen ve tekrar tekrar kullanılabilen kod bloğudur; bir sınıfın içindeki fonksiyona metot denir.`,
an:`Kahve makinesindeki "Latte" butonu: içinde ne olduğunu bilmeden basarsın, her seferinde aynı işi yapar. Tarifi bir kere yazarsın, istediğin kadar çağırırsın.`,
fi:`KDV hesaplayan bir fonksiyonun tanımı ve çağrılması:`,
code:[`FUNCTION kdv_hesapla(tutar)`,
`    SET kdv = tutar * 0.20`,
`    RETURN tutar + kdv            // sonucu çağırana geri ver`,
`END FUNCTION`,
``,
`SET fatura1 = CALL kdv_hesapla(100)     // 120`,
`SET fatura2 = CALL kdv_hesapla(250)     // 300`],
note:`Fonksiyon aynı kodu tekrar yazmaktan kurtarır ve bir hatayı tek yerde düzeltmeyi sağlar. RETURN, fonksiyonun ürettiği sonucu çağırana geri verir.`,
qs:[
{t:`Fonksiyonun en büyük faydası nedir?`,o:[`Bir işi bir kere yazıp istenen yerde tekrar tekrar kullanmak`,`Bilgisayarı hızlandıran bir donanım olması`,`Veritabanını otomatik yedeklemesi`,`Ekranı yenilemesi`],e:`Latte butonu gibi: tarif bir kere yazılır, her basışta aynı iş yapılır.`},
{t:`kdv_hesapla(50) çağrıldığında RETURN ne döner?`,o:[`60`,`50`,`10`,`70`],e:`50 x 0.20 = 10 KDV; 50 + 10 = 60 geri döner.`},
{t:`Bir sınıfın içinde tanımlanan fonksiyona ne denir?`,o:[`Metot`,`Değişken`,`Döngü`,`Sabit`],e:`İşlev aynıdır; sınıfa ait olduğunda adı metot olur.`}
]},
{no:13,tr:`Parametre / Argüman`,en:`Parameter / Argument`,
def:`Parametre, fonksiyonun dışarıdan alacağı değer için tanımladığı yer tutucudur; argüman ise fonksiyon çağrılırken o yere gönderilen gerçek değerdir.`,
an:`Formdaki boş "Ad: ____" alanı parametredir; o alana yazılan "Ayşe" argümandır.`,
fi:`Tanımda parametre, çağrıda argüman:`,
code:[`FUNCTION fatura_getir(müşteri_no, dönem)      // parametreler`,
`    LOAD fatura FROM veritabanı WITH müşteri_no, dönem`,
`    RETURN fatura`,
`END FUNCTION`,
``,
`CALL fatura_getir(1002345, "2026-10")         // argümanlar`],
note:`Parametrelerin sırası ve tipi önemlidir. Dönem beklenen yere müşteri numarası gönderilirse fonksiyon yanlış sonuç döner ya da hata verir.`,
qs:[
{t:`FUNCTION fatura_getir(müşteri_no, dönem) satırındaki müşteri_no nedir?`,o:[`Parametre`,`Argüman`,`Döngü`,`Sabit`],e:`Tanım satırındaki isimler yer tutucudur, yani parametredir.`},
{t:`CALL fatura_getir(1002345, "2026-10") satırındaki 1002345 nedir?`,o:[`Argüman`,`Parametre`,`Fonksiyon adı`,`Dönüş değeri`],e:`Çağrı sırasında gönderilen gerçek değer argümandır.`},
{t:`Form benzetmesinde boş "Ad: ____" alanı neye karşılık gelir?`,o:[`Parametre`,`Argüman`,`RETURN`,`Döngü`],e:`Boş alan yer tutucudur, yani parametredir. İçine yazılan değer argümandır.`}
]},
{no:14,tr:`Dizi / Liste`,en:`Array / List`,
def:`Dizi ya da liste, birden fazla veriyi tek bir isim altında sıralı olarak tutan ve her elemana sıra numarasıyla (index) ulaşılan yapıdır.`,
an:`Apartmandaki posta kutuları: tek bir dolap ama her gözün numarası var. Dikkat: yazılımda numaralandırma genelde 0'dan başlar.`,
fi:`Bir müşterinin hatlarını listede tutmak:`,
code:[`SET hatlar = ["5321112233", "5334445566", "5357778899"]`,
`SHOW hatlar[0]              // ilk eleman: 5321112233`,
`SHOW hatlar[2]              // üçüncü eleman: 5357778899`,
`SHOW hatlar.length          // eleman sayısı: 3`,
`SHOW hatlar[3]              // hata: böyle bir göz yok`],
note:`Var olmayan bir sıra numarasına ulaşmak "index out of bounds" hatası verir. Boş liste, tek elemanlı liste ve çok elemanlı liste ayrı ayrı denenmesi gereken durumlardır.`,
qs:[
{t:`hatlar = [A, B, C] listesinde hatlar[1] hangisidir?`,o:[`B`,`A`,`C`,`Hata verir`],e:`Sayma 0'dan başlar: [0] A, [1] B, [2] C.`},
{t:`3 elemanlı bir listede hatlar[3]'e ulaşılmaya çalışılırsa ne olur?`,o:[`Index out of bounds hatası alınır`,`İlk eleman döner`,`Liste otomatik büyür`,`Son eleman döner`],e:`3 elemanın numaraları 0, 1 ve 2'dir. 3 numaralı göz yoktur.`},
{t:`Liste yapısının amacı nedir?`,o:[`Birden fazla veriyi tek isim altında sıralı tutmak`,`Tek bir sayıyı saklamak`,`Programı derlemek`,`Kullanıcıyı doğrulamak`],e:`Posta kutuları gibi: tek dolap, numaralı gözler.`}
]},
{no:15,tr:`Nesne`,en:`Object`,
def:`Nesne, birbiriyle ilgili verileri (özellikler) ve bu verilerle yapılabilecek işleri (metotlar) tek bir pakette toplayan yapıdır.`,
an:`Bir müşteri kartı düşün: üzerinde ad, numara, paket yazar (özellikler); "paket değiştir" ya da "fatura göster" düğmeleri vardır (metotlar). Kartın kendisi nesnedir.`,
fi:`Bir müşteri nesnesi:`,
code:[`SET müşteri = {`,
`    ad: "Ayşe Yılmaz",                 // özellik`,
`    müşteri_no: 1002345,               // özellik`,
`    paket: "Kurumsal 20 GB"            // özellik`,
`}`,
`SHOW müşteri.ad                        // Ayşe Yılmaz`,
`CALL müşteri.paket_değiştir("Kurumsal 50 GB")   // metot`],
note:`JSON'daki süslü parantezli yapılar da nesnedir. Bir API cevabında müşteri bilgisi genellikle bir nesne olarak gelir.`,
qs:[
{t:`Nesne neyi bir arada tutar?`,o:[`İlgili verileri ve bu verilerle yapılabilecek işleri`,`Sadece tek bir sayıyı`,`Sadece donanım bilgisini`,`Sadece hata mesajlarını`],e:`Nesne, özellikleri ve metotları tek pakette toplar.`},
{t:`müşteri.ad ifadesi neyi gösterir?`,o:[`Müşteri nesnesinin ad özelliğini`,`Bir döngüyü`,`Bir veritabanı tablosunu`,`Bir fonksiyon tanımını`],e:`Nokta, nesnenin içindeki bir özelliğe ya da metoda ulaşmak için kullanılır.`},
{t:`Müşteri kartı benzetmesinde "paket değiştir" düğmesi neye karşılık gelir?`,o:[`Metot`,`Özellik`,`Sabit`,`Index`],e:`Düğmeler bir iş yapar; nesnede iş yapan parçalar metottur.`}
]}
]);

add(2,`Kodun yapı taşları`,[
{no:16,tr:`Sınıf`,en:`Class`,
def:`Sınıf, aynı türdeki nesnelerin hangi özelliklere ve metotlara sahip olacağını tanımlayan şablondur; nesneler bu şablondan üretilir.`,
an:`Sınıf kurabiye kalıbıdır, nesneler kalıptan çıkan kurabiyeler. Kalıp bir tane, kurabiye istediğin kadar; her birinin süslemesi (değerleri) farklı olabilir.`,
fi:`Müşteri sınıfı ve ondan üretilen iki nesne:`,
code:[`CLASS Müşteri`,
`    özellikler: ad, müşteri_no, paket`,
`    FUNCTION paket_değiştir(yeni_paket)`,
`        SET paket = yeni_paket`,
`    END FUNCTION`,
`END CLASS`,
``,
`SET m1 = NEW Müşteri("Ayşe", 1002345, "20 GB")`,
`SET m2 = NEW Müşteri("Mehmet", 1002346, "50 GB")`],
note:`Java gibi nesne yönelimli (OOP) dillerde kodun büyük kısmı sınıflardan oluşur. NEW, şablondan yeni bir nesne üretir.`,
qs:[
{t:`Kurabiye kalıbı benzetmesinde kalıp neye karşılık gelir?`,o:[`Sınıf`,`Nesne`,`Değişken`,`Döngü`],e:`Kalıp şablondur, yani sınıf. Kalıptan çıkan her kurabiye bir nesnedir.`},
{t:`Aynı sınıftan üretilen iki nesne için hangisi doğrudur?`,o:[`Aynı özelliklere sahiptirler ama değerleri farklı olabilir`,`Değerleri her zaman aynıdır`,`Farklı metotlara sahiptirler`,`Biri silinince diğeri de silinir`],e:`İkisinin de adı, numarası ve paketi vardır; ama biri Ayşe, diğeri Mehmet'tir.`},
{t:`NEW Müşteri(...) ifadesi ne yapar?`,o:[`Müşteri sınıfından yeni bir nesne üretir`,`Müşteri sınıfını siler`,`Veritabanına bağlanır`,`Programı yeniden başlatır`],e:`NEW, kalıptan yeni bir kurabiye çıkarmak gibidir.`}
]},
{no:17,tr:`Kütüphane`,en:`Library`,
def:`Kütüphane, sık ihtiyaç duyulan işleri yapan, başkaları tarafından yazılmış ve kendi kodumuza ekleyip çağırabildiğimiz hazır kod paketidir.`,
an:`Hazır yapı malzemesi gibi: kapıyı kendin üretmezsin, hazır kapı alıp takarsın. Tarih hesaplamak ya da PDF oluşturmak için de hazır kütüphane kullanılır.`,
fi:`Kütüphaneyi projeye ekleyip kullanmak:`,
code:[`IMPORT tarih_kütüphanesi                 // hazır paketi ekle`,
`SET bugün = CALL tarih_kütüphanesi.bugün()`,
`SET son_ödeme = CALL tarih_kütüphanesi.gün_ekle(bugün, 15)`,
`SHOW son_ödeme                          // hazır fonksiyonla 15 gün sonrası`],
note:`Selenium, Rest Assured ya da Jackson birer kütüphanedir. Kütüphaneler Maven, npm gibi araçlarla projeye eklenir; bunlara bağımlılık (dependency) denir.`,
qs:[
{t:`Kütüphane kullanmanın temel faydası nedir?`,o:[`Sık yapılan işleri sıfırdan yazmadan hazır kodla yapmak`,`Bilgisayara yeni donanım eklemek`,`İnternet hızını artırmak`,`Kodu kendiliğinden test etmek`],e:`Hazır kapı almak gibi: aynı işi tekrar tekrar sıfırdan yazmazsın.`},
{t:`Hangisi bir kütüphane örneğidir?`,o:[`Selenium WebDriver`,`Windows`,`Klavye`,`404 Not Found`],e:`Selenium WebDriver, tarayıcıyı kodla yönetmek için projeye eklenen hazır bir pakettir.`},
{t:`Kütüphane ile kendi kodun arasındaki ilişki nedir?`,o:[`Kütüphaneyi sen çağırırsın, ne zaman kullanacağına sen karar verirsin`,`Kütüphane senin kodunu çağırır ve akışı o yönetir`,`Kütüphane sadece donanımda çalışır`,`Kütüphane kodun derlenmesini engeller`],e:`Kütüphanede kontrol sendedir. Akışı yöneten yapı ise framework'tür.`}
]},
{no:18,tr:`Framework`,en:`Framework`,
def:`Framework, uygulamanın iskeletini ve çalışma kurallarını hazır sunan, geliştiricinin kendi kodunu bu iskeletin belirlediği yerlere yazdığı yapıdır.`,
an:`Kütüphane mobilya mağazasıdır: istediğini alır, istediğin yere koyarsın. Framework hazır evdir: odalar ve kurallar belli, sen içini döşersin. Kısaca: kütüphaneyi sen çağırırsın, framework seni çağırır.`,
fi:`Bir web framework'ünde akışı framework yönetir:`,
code:[`// Framework hazır: sunucuyu açar, gelen isteği karşılar`,
`ON request "/fatura" DO                // framework seni çağırır`,
`    CALL fatura_getir(müşteri_no)      // sen sadece bu kısmı yazarsın`,
`END`],
note:`Spring Boot (backend), Angular (frontend), Cucumber ve Karate birer framework örneğidir. Framework'ün kurallarının dışına çıkmak işleri zorlaştırır.`,
qs:[
{t:`"Kütüphaneyi sen çağırırsın, framework seni çağırır" cümlesi neyi anlatır?`,o:[`Framework'te akışı framework yönetir, geliştirici kodunu belirlenen yerlere yazar`,`Framework ve kütüphane aynı şeydir`,`Kütüphane kodu otomatik yazar`,`Framework sadece veritabanında çalışır`],e:`Hazır evde odaların yeri bellidir; sen sadece içini döşersin.`},
{t:`Hangisi bir framework örneğidir?`,o:[`Spring Boot`,`Klavye`,`JSON`,`IP adresi`],e:`Spring Boot, Java ile backend uygulaması geliştirmek için hazır iskelet sunar.`},
{t:`Hazır ev benzetmesinde "evin içini döşemek" neye karşılık gelir?`,o:[`Geliştiricinin kendi iş mantığını framework'ün belirlediği yerlere yazması`,`Framework'ü silmek`,`Bilgisayarı değiştirmek`,`Kütüphane indirmek`],e:`İskelet hazır gelir; asıl iş kuralları geliştiricinin yazdığı kısımdadır.`}
]},
{no:19,tr:`Exception / Try-Catch`,en:`Exception Handling`,
def:`Exception, program çalışırken beklenmeyen bir durum oluştuğunda fırlatılan hatadır; try-catch ise bu hatayı yakalayıp programın çökmeden kontrollü şekilde devam etmesini sağlar.`,
an:`Trapezdeki akrobatın altındaki güvenlik ağı: düşüş (hata) yine olur ama ağ (catch) yakalar, gösteri devam eder.`,
fi:`Fatura servisine erişilemezse:`,
code:[`TRY`,
`    SET fatura = CALL fatura_servisi(müşteri_no)`,
`    SHOW fatura`,
`CATCH ServisErişilemiyorHatası`,
`    LOG "Fatura servisi cevap vermedi"         // iz bırak`,
`    SHOW "Faturanız şu an gösterilemiyor"      // kullanıcıya düzgün mesaj`,
`END TRY`],
note:`Yakalanmayan exception programı çökertir ya da kullanıcıya teknik bir hata ekranı gösterir. Loglarda gördüğün NullPointerException ya da TimeoutException birer exception adıdır.`,
qs:[
{t:`try-catch yapısının amacı nedir?`,o:[`Beklenmeyen hatayı yakalayıp programın kontrollü devam etmesini sağlamak`,`Hataları tamamen imkânsız hale getirmek`,`Kodu daha hızlı derlemek`,`Veritabanını yedeklemek`],e:`Hata yine oluşur; catch onu yakalar ve ne yapılacağına karar verir.`},
{t:`Exception yakalanmazsa genelde ne olur?`,o:[`Program ya da işlem çöker`,`Hata kendiliğinden düzelir`,`Program iki kez çalışır`,`Hiçbir etkisi olmaz`],e:`Ağ yoksa akrobat yere düşer; yakalanmayan hata da işlemi durdurur.`},
{t:`Güvenlik ağı benzetmesinde ağ neye karşılık gelir?`,o:[`Catch bloğu`,`Try bloğu`,`Exception'ın kendisi`,`Döngü`],e:`Try riskli gösteridir, exception düşüştür, catch ise düşeni yakalayan ağdır.`}
]},
{no:20,tr:`Null / Undefined`,en:`Null / Undefined`,
def:`Null, bir değişkenin "hiçbir değer taşımadığını" gösteren özel değerdir; undefined ise (özellikle JavaScript'te) değişkene henüz hiç değer atanmadığını gösterir.`,
an:`Null boş bir kutudur: kutu var ama içi boş. Undefined, kutuya ne konacağının hiç belirlenmemesidir. Sıfır ise içinde "0" yazan bir kâğıt olan kutudur; boş değildir.`,
fi:`Null kontrolü yapılmazsa:`,
code:[`SET müşteri = CALL müşteri_bul(9999999)   // böyle müşteri yok: null`,
`SHOW müşteri.ad                           // NullPointerException`,
``,
`// Doğrusu: önce kontrol et`,
`IF müşteri == null THEN`,
`    SHOW "Müşteri bulunamadı"`,
`ELSE`,
`    SHOW müşteri.ad`,
`END IF`],
note:`Null, 0 ve boş metin ("") farklı şeylerdir. Bir API cevabında alanın null gelmesi, hiç gelmemesi ve boş gelmesi ayrı durumlardır.`,
qs:[
{t:`null ile 0 arasındaki fark nedir?`,o:[`null "değer yok" demektir, 0 ise bir sayı değeridir`,`İkisi tamamen aynıdır`,`0 "değer yok" demektir, null bir sayıdır`,`null sadece metinlerde kullanılır`],e:`Boş kutu ile içinde "0" yazan kâğıt olan kutu aynı şey değildir.`},
{t:`null olan bir nesnenin özelliğine ulaşmaya çalışmak Java'da hangi hataya yol açar?`,o:[`NullPointerException`,`Syntax error`,`404 Not Found`,`Merge conflict`],e:`Boş kutunun içindeki adı okumaya çalışmak gibi; ortada okunacak bir şey yoktur.`},
{t:`JavaScript'te tanımlanmış ama hiç değer atanmamış bir değişkenin değeri nedir?`,o:[`undefined`,`null`,`0`,`""`],e:`Değer hiç verilmediyse undefined olur; null ise bilerek "boş" denmiş halidir.`}
]}
]);

add(3,`Sistemin katmanları`,[
{no:21,tr:`İşletim Sistemi`,en:`Operating System`,
def:`İşletim sistemi, donanımı yöneten ve diğer yazılımların donanımı kullanabilmesine aracılık eden temel yazılımdır.`,
an:`Apartman yöneticisi: sakinler (uygulamalar) asansörü, suyu, elektriği (donanımı) doğrudan kurcalamaz; yöneticiye söyler, o paylaştırır.`,
fi:`Bir uygulama dosya kaydetmek istediğinde:`,
code:[`// Uygulama: "Bu belgeyi kaydet"`,
`CALL işletim_sistemi.dosya_yaz("rapor.pdf")`,
``,
`// İşletim sistemi:`,
`IF kullanıcının_yazma_izni_var THEN`,
`    WRITE dosya TO disk            // donanımla o konuşur`,
`ELSE`,
`    RETURN "Erişim reddedildi"`,
`END IF`],
note:`Windows, macOS, Linux, iOS ve Android birer işletim sistemidir. Sunucuların çoğu Linux üzerinde çalışır.`,
qs:[
{t:`İşletim sisteminin temel görevi nedir?`,o:[`Donanımı yönetmek ve uygulamaların donanımı kullanmasına aracılık etmek`,`Sadece internet tarayıcısı açmak`,`Sadece oyun çalıştırmak`,`Kaynak kod yazmak`],e:`Uygulamalar donanıma yöneticinin, yani işletim sisteminin üzerinden ulaşır.`},
{t:`Hangisi işletim sistemi değildir?`,o:[`Chrome`,`Linux`,`macOS`,`Android`],e:`Chrome bir tarayıcı uygulamasıdır; işletim sisteminin üzerinde çalışır.`},
{t:`Apartman benzetmesinde yönetici neye karşılık gelir?`,o:[`İşletim sistemi`,`Uygulama`,`Donanım`,`Kullanıcı`],e:`Sakinler uygulamalar, apartmanın tesisatı donanım, ikisinin arasındaki yönetici işletim sistemidir.`}
]},
{no:22,tr:`İstemci`,en:`Client`,
def:`İstemci, bir hizmeti ya da veriyi almak için sunucuya istek gönderen taraftır; tarayıcı, mobil uygulama ya da başka bir servis istemci olabilir.`,
an:`Restorandaki müşteri: menüye bakar, sipariş verir ve yemeğin gelmesini bekler. Yemeği kendisi yapmaz, ister.`,
fi:`İstemci tarafının işi:`,
code:[`// İstemci (tarayıcı / mobil uygulama)`,
`GET müşteri_no FROM ekran`,
`SEND istek TO sunucu              // "Bu müşterinin faturasını ver"`,
`WAIT cevap`,
`IF cevap.başarılı THEN`,
`    SHOW cevap.fatura ON ekran`,
`ELSE`,
`    SHOW "Bir hata oluştu"`,
`END IF`],
note:`Bir sistem hem istemci hem sunucu olabilir: backend, tarayıcıya göre sunucudur ama veriyi aldığı başka bir servise göre istemcidir.`,
qs:[
{t:`Restoran benzetmesinde istemci kimdir?`,o:[`Sipariş veren müşteri`,`Mutfaktaki aşçı`,`Restoranın binası`,`Menünün kendisi`],e:`İsteyen taraf istemcidir; yemeği hazırlayan mutfak ise sunucudur.`},
{t:`Hangisi istemci olabilir?`,o:[`Tarayıcı, mobil uygulama ya da başka bir servis`,`Sadece fiziksel bir bilgisayar`,`Sadece veritabanı`,`Sadece klavye`],e:`İstemci bir roldür: istek gönderen her yazılım istemcidir.`},
{t:`Backend, verisini başka bir servisten çekiyor. Bu ilişkide backend nedir?`,o:[`İstemci`,`Sunucu`,`Veritabanı`,`İşletim sistemi`],e:`İsteyen taraf istemcidir. Backend tarayıcıya göre sunucu, veriyi aldığı servise göre istemcidir.`}
]},
{no:23,tr:`Sunucu`,en:`Server`,
def:`Sunucu, istemcilerden gelen istekleri karşılayan, işleyen ve cevap döndüren yazılım ya da bu yazılımın çalıştığı bilgisayardır.`,
an:`Restoranın mutfağı: siparişi alır, hazırlar, tabağı gönderir. Aynı anda birçok masaya hizmet verir ve hep açık kalması beklenir.`,
fi:`Sunucu tarafının işi:`,
code:[`// Sunucu: sürekli dinler`,
`WHILE sunucu_açık`,
`    RECEIVE istek FROM istemci`,
`    IF istek.geçerli THEN`,
`        LOAD fatura FROM veritabanı`,
`        SEND fatura TO istemci          // cevap`,
`    ELSE`,
`        SEND hata TO istemci`,
`    END IF`,
`END WHILE`],
note:`"Sunucu" hem fiziksel makineyi hem de üzerinde çalışan yazılımı anlatabilir. Sunucu çökerse ona bağlı tüm istemciler etkilenir; bu yüzden sunucular izlenir ve yedekli çalıştırılır.`,
qs:[
{t:`Sunucunun temel işi nedir?`,o:[`Gelen istekleri karşılayıp cevap döndürmek`,`Başka sistemlere sadece istek göndermek`,`Kullanıcının ekranını çizmek`,`Klavyeden girdi almak`],e:`Mutfak gibi: sipariş gelir, hazırlanır, tabak gönderilir.`},
{t:`Bir sunucu çökerse ne olur?`,o:[`Ona bağlı tüm istemciler hizmet alamaz`,`Sadece bir kullanıcı etkilenir`,`Hiçbir şey olmaz`,`İstemciler cevabı kendileri üretir`],e:`Mutfak kapanırsa hiçbir masaya yemek çıkmaz.`},
{t:`"Sunucu" kelimesi neyi anlatabilir?`,o:[`Hem fiziksel makineyi hem de üzerinde çalışan yazılımı`,`Sadece klavyeyi`,`Sadece tarayıcıyı`,`Sadece kaynak kodu`],e:`Bağlama göre hem makine hem de istekleri karşılayan yazılım için kullanılır.`}
]},
{no:24,tr:`Client-Server Mimarisi`,en:`Client-Server Architecture`,
def:`Client-server mimarisi, işin istek gönderen istemciler ile bu istekleri karşılayan merkezi sunucular arasında paylaştırıldığı yapıdır.`,
an:`Restoranın tamamı: masalar (istemciler) sipariş verir, garson (ağ) taşır, mutfak (sunucu) hazırlar. Her masa kendi mutfağını kurmaz.`,
fi:`Tam tur: istek ve cevap:`,
code:[`// İstemci`,
`SEND "GET /fatura/1002345" TO sunucu`,
`// Sunucu`,
`RECEIVE istek`,
`LOAD fatura FROM veritabanı`,
`SEND fatura TO istemci`,
`// İstemci`,
`RECEIVE fatura`,
`SHOW fatura ON ekran`],
note:`Web ve mobil dünyasının neredeyse tamamı bu mimariyle çalışır. Veri ve iş kuralları sunucuda toplandığı için güncellemek ve korumak kolaylaşır.`,
qs:[
{t:`Client-server mimarisinde iş nasıl bölünür?`,o:[`İstemci ister, sunucu işler ve cevap verir`,`Her istemci kendi verisini tutar ve kimseyle konuşmaz`,`Sunucu istek alır ama cevap vermez`,`İstemci ve sunucu aynı işi yapar`],e:`Masa sipariş verir, mutfak hazırlar; görevler ayrıdır.`},
{t:`Restoran benzetmesinde garson neye karşılık gelir?`,o:[`İstek ve cevabı taşıyan ağ`,`Sunucu`,`İstemci`,`Veritabanı`],e:`Garson siparişi mutfağa, tabağı masaya taşır; ağ da istek ve cevabı taşır.`},
{t:`Bu mimarinin bir avantajı nedir?`,o:[`Veri ve iş kurallarının merkezde toplanması`,`Hiç sunucu gerektirmemesi`,`İnternetsiz çalışmak zorunda olması`,`Her kullanıcının kendi veritabanını kurması`],e:`Kural sunucuda bir kez değişir, tüm istemciler hemen yeni kurala göre hizmet alır.`}
]},
{no:25,tr:`Frontend`,en:`Frontend`,
def:`Frontend, kullanıcının gördüğü ve etkileşime girdiği arayüz katmanıdır; ekranlar, butonlar, formlar ve bunların davranışı bu katmandadır.`,
an:`Restoranın salonu: masa düzeni, menü, garsonun güler yüzü. Müşteri mutfağı görmez; deneyimi salonda yaşar.`,
fi:`Bir buton tıklandığında frontend'in yaptığı:`,
code:[`ON click "Faturayı Göster" DO`,
`    IF müşteri_no boş THEN`,
`        SHOW "Müşteri numarası giriniz"      // ön kontrol (validasyon)`,
`    ELSE`,
`        SHOW yükleniyor_animasyonu`,
`        SEND istek TO backend`,
`        SHOW gelen_fatura IN tablo`,
`    END IF`,
`END`],
note:`Frontend genelde HTML, CSS ve JavaScript (Angular, React gibi) ile yazılır ve tarayıcıda çalışır. Tasarım Figma gibi araçlarda hazırlanır, frontend geliştirici onu koda döker.`,
qs:[
{t:`Frontend neyi kapsar?`,o:[`Kullanıcının gördüğü ve etkileşime girdiği arayüzü`,`Veritabanı tablolarını`,`Sunucunun işletim sistemini`,`Ağ kablolarını`],e:`Salon gibi: kullanıcının deneyimlediği her şey frontend'dedir.`},
{t:`Butona basar basmaz "Müşteri numarası giriniz" uyarısının çıkması hangi katmanın işidir?`,o:[`Frontend`,`Veritabanı`,`İşletim sistemi`,`Donanım`],e:`Boş alan kontrolü sunucuya gitmeden ekranda yapılır; bu frontend validasyonudur.`},
{t:`Frontend kodu genellikle nerede çalışır?`,o:[`Kullanıcının tarayıcısında`,`Veritabanı sunucusunda`,`Ağ kablosunda`,`Derleyicinin içinde`],e:`HTML, CSS ve JavaScript tarayıcıya indirilir ve orada çalışır.`}
]}
]);

add(3,`Sistemin katmanları`,[
{no:26,tr:`Backend`,en:`Backend`,
def:`Backend, kullanıcının görmediği, iş kurallarının işletildiği, verinin işlendiği ve frontend'e cevap üreten sunucu tarafı katmandır.`,
an:`Restoranın mutfağı: tarif burada uygulanır, malzeme burada işlenir. Salon (frontend) ne kadar şık olursa olsun yemeği mutfak yapar.`,
fi:`Backend'in fatura isteğini işlemesi:`,
code:[`RECEIVE istek FROM frontend`,
`IF NOT token_geçerli(istek) THEN`,
`    RETURN 401                                 // yetkisiz`,
`END IF`,
`LOAD fatura FROM veritabanı WITH istek.müşteri_no`,
`SET fatura.gecikme_faizi = CALL faiz_hesapla(fatura)   // iş kuralı`,
`RETURN fatura AS JSON`],
note:`Backend genelde Java (Spring Boot), C#, Python ya da Node.js ile yazılır. Frontend'deki kontroller atlatılabilir; asıl güvenlik ve iş kuralı kontrolleri backend'de yapılmalıdır.`,
qs:[
{t:`Backend'in temel görevi nedir?`,o:[`İş kurallarını işletip veriyi işlemek ve cevap üretmek`,`Butonların rengini belirlemek`,`Ekran çözünürlüğünü ayarlamak`,`Klavyeden girdi almak`],e:`Mutfak gibi: asıl iş, yani kurallar ve veri işleme, backend'de yapılır.`},
{t:`Önemli kontroller neden sadece frontend'de değil backend'de de yapılmalıdır?`,o:[`Ekran atlanıp backend'e doğrudan istek atılabilir`,`Backend kontrolleri daha renkli görünür`,`Frontend hiç kontrol yapamaz`,`Backend sadece gece çalışır`],e:`Postman gibi araçlarla ekranı hiç kullanmadan backend'e istek gönderilebilir.`},
{t:`Gecikme faizinin hesaplanması hangi katmanda yapılmalıdır?`,o:[`Backend`,`Frontend`,`İşletim sistemi`,`Tarayıcı`],e:`Para hesaplayan iş kuralları tek bir merkezde, backend'de olmalıdır.`}
]},
{no:27,tr:`Middleware`,en:`Middleware`,
def:`Middleware, farklı sistemlerin arasında durup aralarındaki iletişimi, veri dönüşümünü ve yönlendirmeyi üstlenen ara katman yazılımıdır.`,
an:`Tercüman ve kurye bir arada: biri SOAP, diğeri REST konuşuyorsa middleware ikisinin dilini bilir; mesajı alır, çevirir ve doğru adrese teslim eder.`,
fi:`Eski bir sistemden gelen veriyi yeni sisteme taşımak:`,
code:[`RECEIVE soap_cevabı FROM eski_crm`,
`SET json = CALL dönüştür(soap_cevabı)        // XML'den JSON'a (mapping)`,
`IF soap_cevabı.statü == "A" THEN`,
`    SET json.durum = "Aktif"                 // kodu anlamlı değere çevir`,
`END IF`,
`SEND json TO backend`],
note:`TIBCO, MuleSoft ve IBM Integration Bus bilinen middleware ürünleridir. Middleware sayesinde backend, eski sistemin karmaşık yapısıyla doğrudan uğraşmaz.`,
qs:[
{t:`Middleware'in temel görevi nedir?`,o:[`Sistemler arası iletişimi, dönüşümü ve yönlendirmeyi üstlenmek`,`Kullanıcı arayüzünü çizmek`,`Bilgisayarın donanımını yönetmek`,`Kaynak kodu derlemek`],e:`Tercüman ve kurye gibi: alır, çevirir, doğru yere iletir.`},
{t:`Tercüman benzetmesinde "çeviri" middleware'de neye karşılık gelir?`,o:[`Veri dönüşümü (mapping)`,`Veriyi silmek`,`Veriyi şifresiz bırakmak`,`Ekranı yenilemek`],e:`Bir sistemin formatındaki veriyi diğerinin anlayacağı formata çevirmek mapping'dir.`},
{t:`Hangisi bir middleware ürünüdür?`,o:[`TIBCO`,`Chrome`,`Excel`,`Figma`],e:`TIBCO, sistemler arası entegrasyon için kullanılan bir middleware platformudur.`}
]},
{no:28,tr:`Veritabanı`,en:`Database`,
def:`Veritabanı, verilerin düzenli, kalıcı ve sorgulanabilir şekilde saklandığı sistemdir.`,
an:`Düzenli bir arşiv odası: her dosya belli bir dolapta, belli bir rafta. "Şu müşterinin geçen ayki faturası" dediğinde arşivci saniyeler içinde getirir.`,
fi:`Veritabanından okumak ve veritabanına yazmak:`,
code:[`// Okuma`,
`LOAD fatura FROM veritabanı`,
`    WHERE müşteri_no = 1002345 AND dönem = "2026-10"`,
``,
`// Yazma`,
`SAVE ödeme TO veritabanı`,
`    WITH tutar = 249.90, tarih = bugün`],
note:`Oracle, PostgreSQL ve MySQL ilişkisel (SQL) veritabanlarıdır; MongoDB gibi NoSQL veritabanları da vardır. Uygulama kapansa bile veri veritabanında kalır.`,
qs:[
{t:`Veritabanının temel amacı nedir?`,o:[`Verileri düzenli, kalıcı ve sorgulanabilir şekilde saklamak`,`Kullanıcı arayüzünü çizmek`,`Kodu derlemek`,`Ağ trafiğini yönlendirmek`],e:`Arşiv odası gibi: düzenli saklar, istenince hızlıca bulur.`},
{t:`Hangisi bir veritabanıdır?`,o:[`PostgreSQL`,`Chrome`,`Jenkins`,`Figma`],e:`PostgreSQL ilişkisel bir veritabanıdır. Chrome tarayıcı, Jenkins CI aracı, Figma tasarım aracıdır.`},
{t:`Uygulama kapatılıp açılınca müşteri kayıtları neden kaybolmaz?`,o:[`Kayıtlar kalıcı olarak veritabanında saklanır`,`Kayıtlar RAM'de durur`,`Kayıtlar ekranda kalır`,`Kayıtlar her açılışta yeniden yazılır`],e:`RAM geçicidir; veritabanı ise veriyi diske kalıcı yazar.`}
]},
{no:29,tr:`Monolit`,en:`Monolith`,
def:`Monolit, uygulamanın tüm parçalarının (arayüz, iş kuralları, veri erişimi) tek bir kod tabanında toplandığı ve tek parça olarak deploy edildiği mimaridir.`,
an:`Tek parça bir gemi: kurmak ve yönetmek başta kolay. Ama bir kamarayı tamir etmek için tüm gemiyi limana çekmen gerekir.`,
fi:`Monolitte küçük bir değişikliğin yolculuğu:`,
code:[`// Tek uygulama: fatura + ödeme + müşteri + kampanya`,
`CALL değiştir(kampanya_modülü)       // küçük bir değişiklik`,
`CALL build(tüm_uygulama)             // hepsi yeniden derlenir`,
`CALL deploy(tüm_uygulama)            // hepsi birlikte yayına çıkar`,
`IF ödeme_modülünde_hata THEN`,
`    SHOW "Tüm uygulama etkilenir"`,
`END IF`],
note:`Monolit kötü değildir; küçük ekipler ve yeni projeler için hızlıdır. Uygulama ve ekip büyüdükçe deploy süreleri uzar ve bir hata her şeyi etkileyebilir.`,
qs:[
{t:`Monolit mimarinin tanımı hangisidir?`,o:[`Tüm parçaların tek kod tabanında toplanıp birlikte deploy edildiği yapı`,`Her özelliğin ayrı bir servis olduğu yapı`,`Sadece veritabanından oluşan yapı`,`Sadece frontend'den oluşan yapı`],e:`Tek parça gemi: her şey aynı gövdede.`},
{t:`Monolitte küçük bir değişiklik için genellikle ne gerekir?`,o:[`Tüm uygulamanın yeniden build ve deploy edilmesi`,`Sadece ilgili satırın canlıda elle düzeltilmesi`,`Hiçbir deploy gerekmemesi`,`Sadece veritabanının yeniden başlatılması`],e:`Parçalar ayrılmadığı için bir kamara tamiri bile tüm geminin limana çekilmesini gerektirir.`},
{t:`Monolit hangi durumda avantajlıdır?`,o:[`Küçük bir ekip ve yeni, sade bir projede`,`Yüzlerce ekibin aynı anda çalıştığı dev sistemlerde`,`Her parçanın farklı dilde yazılması gerektiğinde`,`Parçaların bağımsız ölçeklenmesi gerektiğinde`],e:`Küçük ölçekte tek parça yapı hızlı geliştirme ve kolay yönetim sağlar.`}
]},
{no:30,tr:`Mikroservis`,en:`Microservice`,
def:`Mikroservis mimarisi, uygulamanın her biri tek bir işten sorumlu, birbirinden bağımsız geliştirilip deploy edilebilen küçük servislere bölündüğü yapıdır.`,
an:`Gemi yerine filo: fatura teknesi, ödeme teknesi, müşteri teknesi. Bir tekne tamire girse diğerleri seyre devam eder; ama filoyu koordine etmek daha zordur.`,
fi:`Mikroservislerin birlikte çalışması:`,
code:[`// Her servis ayrı uygulama, ayrı deploy`,
`CALL müşteri_servisi.getir(1002345)`,
`CALL fatura_servisi.son_fatura(1002345)`,
`TRY`,
`    CALL kampanya_servisi.öneriler(1002345)`,
`CATCH ServisErişilemiyorHatası`,
`    SHOW "Kampanyalar gösterilemiyor"     // diğerleri çalışmaya devam eder`,
`END TRY`],
note:`Avantajı bağımsızlık ve ölçeklenebilirliktir; bedeli ise ağ trafiği, izleme ve servisler arası hata ayıklamanın zorlaşmasıdır. Bir istek birçok servisten geçtiği için loglarda takip zorlaşır.`,
qs:[
{t:`Mikroservis mimarisinin temel fikri nedir?`,o:[`Uygulamayı bağımsız deploy edilebilen küçük servislere bölmek`,`Tüm kodu tek dosyada toplamak`,`Veritabanını kaldırmak`,`Frontend'i backend'e gömmek`],e:`Gemi yerine filo: her tekne kendi işini yapar.`},
{t:`İyi tasarlanmış bir mikroservis yapısında kampanya servisi çökerse ne olur?`,o:[`Sadece kampanya özelliği etkilenir, diğerleri çalışmaya devam eder`,`Tüm sistem durur`,`Fatura servisi de otomatik kapanır`,`Veritabanı silinir`],e:`Bağımsızlık sayesinde hata bir servisle sınırlı kalabilir.`},
{t:`Mikroservislerin bir dezavantajı nedir?`,o:[`Servisler arası iletişim ve hata takibinin karmaşıklaşması`,`Hiç ölçeklenememesi`,`Tek bir ekip tarafından yönetilmek zorunda olması`,`Her değişiklikte tüm sistemin deploy edilmesi`],e:`Filoyu koordine etmek tek gemiyi yönetmekten zordur.`}
]}
]);

add(4,`Frontend ve tarayıcı`,[
{no:31,tr:`Tarayıcı`,en:`Browser`,
def:`Tarayıcı, web sayfalarını sunucudan isteyip gelen HTML, CSS ve JavaScript'i yorumlayarak ekranda çalışır hale getiren uygulamadır.`,
an:`Tarayıcı bir tiyatro sahnesidir: senaryo (HTML), dekor ve kostüm (CSS), oyuncuların hareketleri (JavaScript) sunucudan gelir; sahnede canlandırmak tarayıcının işidir.`,
fi:`Adres çubuğuna bir adres yazıldığında:`,
code:[`GET adres FROM adres_çubuğu`,
`CALL dns_çöz(adres)                  // alan adını IP'ye çevir`,
`SEND istek TO sunucu`,
`RECEIVE html, css, js`,
`CALL sayfayı_çiz(html, css)          // render`,
`RUN js                               // etkileşimleri başlat`],
note:`Chrome, Safari, Firefox ve Edge birer tarayıcıdır. Aynı sayfa farklı tarayıcılarda farklı görünebilir; bu yüzden cross-browser testleri yapılır.`,
qs:[
{t:`Tarayıcının temel işi nedir?`,o:[`Sunucudan gelen HTML, CSS ve JavaScript'i yorumlayıp sayfayı çalışır hale getirmek`,`Veritabanını yönetmek`,`Kodu derleyip sunucuya yüklemek`,`İşletim sistemini güncellemek`],e:`Senaryo, dekor ve hareket sunucudan gelir; sahneye koyan tarayıcıdır.`},
{t:`Bir sayfa Chrome'da düzgün, Safari'de bozuk görünüyor. Bunu yakalayan teste ne denir?`,o:[`Cross-browser test`,`Load test`,`Unit test`,`Stress test`],e:`Aynı sayfanın farklı tarayıcılarda doğru çalıştığını doğrulamaya cross-browser test denir.`},
{t:`Tiyatro benzetmesinde sahne neye karşılık gelir?`,o:[`Tarayıcı`,`HTML`,`Sunucu`,`Veritabanı`],e:`HTML senaryo, CSS dekor, JavaScript hareket; hepsinin canlandığı yer tarayıcıdır.`}
]},
{no:32,tr:`HTML`,en:`HyperText Markup Language`,
def:`HTML, bir web sayfasının iskeletini ve içeriğini (başlık, paragraf, form, buton) etiketlerle tanımlayan işaretleme dilidir.`,
an:`HTML binanın iskeletidir: duvarlar, odalar, kapılar nerede, onu söyler. Boya (CSS) ya da elektrik tesisatı (JavaScript) değildir.`,
fi:`Basit bir giriş formunun HTML'i:`,
code:[`<form id="giris">`,
`  <label>Müşteri No</label>`,
`  <input id="musteriNo" type="text">`,
`  <button id="girisBtn">Giriş</button>`,
`</form>`],
note:`HTML bir programlama dili değil, işaretleme dilidir; koşul ya da döngü içermez. Selenium ile elementleri bulmak için kullanılan id ve class değerleri HTML'den gelir.`,
qs:[
{t:`HTML'in görevi nedir?`,o:[`Sayfanın iskeletini ve içeriğini tanımlamak`,`Sayfayı renklendirmek`,`Sunucuda veritabanını yönetmek`,`Sayfaya karar mantığı eklemek`],e:`İskelet HTML'dir; renk CSS'in, davranış JavaScript'in işidir.`},
{t:`HTML neden programlama dili sayılmaz?`,o:[`Koşul ya da döngü gibi mantık içermez, sadece yapıyı tanımlar`,`Çok eski olduğu için`,`Sadece sunucuda çalıştığı için`,`Derlenmesi gerektiği için`],e:`HTML "burada bir buton var" der ama "tıklanırsa şunu yap" diyemez.`},
{t:`Selenium ile bir butonu bulmak için kullanılan id değeri nereden gelir?`,o:[`HTML'den`,`Veritabanından`,`İşletim sisteminden`,`Sunucu loglarından`],e:`id="girisBtn" gibi değerler HTML etiketinin içinde tanımlanır.`}
]},
{no:33,tr:`CSS`,en:`Cascading Style Sheets`,
def:`CSS, HTML ile kurulan sayfanın renk, yazı tipi, boşluk ve yerleşim gibi görünümünü belirleyen stil dilidir.`,
an:`HTML iskelet ise CSS boya, mobilya ve dekorasyondur. Aynı ev, farklı dekorla bambaşka görünür.`,
fi:`Giriş butonunun görünümünü tanımlamak:`,
code:[`#girisBtn {`,
`  background: red;        /* arka plan rengi */`,
`  color: white;           /* yazı rengi */`,
`  padding: 12px 24px;     /* iç boşluk */`,
`  border-radius: 8px;     /* köşe yuvarlaklığı */`,
`}`],
note:`CSS hataları işlevi bozmaz ama deneyimi bozar: butonun ekrandan taşması ya da yazının okunmaması gibi. Figma tasarımıyla ekranın birebir uyumu çoğunlukla CSS'in konusudur.`,
qs:[
{t:`CSS neyi belirler?`,o:[`Sayfanın renk, yazı tipi ve yerleşim gibi görünümünü`,`Sayfanın veritabanı bağlantısını`,`Butonun tıklanınca ne yapacağını`,`Sunucunun adresini`],e:`CSS görünümün dilidir; davranış JavaScript'tedir.`},
{t:`Ev benzetmesinde CSS neye karşılık gelir?`,o:[`Boya ve dekorasyon`,`İskelet`,`Elektrik tesisatı`,`Tapu`],e:`İskelet HTML, tesisat JavaScript, boya ve dekor CSS'tir.`},
{t:`Butonun rengi Figma'daki tasarımla aynı değil. Sorun büyük ihtimalle nerededir?`,o:[`CSS`,`Veritabanı`,`Backend iş kuralı`,`DNS`],e:`Renk, boşluk ve yazı tipi farkları neredeyse her zaman CSS kaynaklıdır.`}
]},
{no:34,tr:`JavaScript`,en:`JavaScript`,
def:`JavaScript, web sayfasına davranış kazandıran, tarayıcıda çalışan programlama dilidir; tıklamalara tepki vermek, sunucudan veri çekmek ve ekranı güncellemek onun işidir.`,
an:`Evin elektrik tesisatı: düğmeye basınca ışığın yanmasını sağlar. İskelet (HTML) ve dekor (CSS) durur; hareket JavaScript'ten gelir.`,
fi:`Butona tıklanınca faturayı getirmek:`,
code:[`ON click "#girisBtn" DO`,
`    SET no = CALL değer_al("#musteriNo")`,
`    IF no == "" THEN`,
`        SHOW "Müşteri no boş olamaz"`,
`    ELSE`,
`        SET cevap = CALL fetch("/api/fatura/" + no)   // sunucudan veri`,
`        CALL ekranı_güncelle(cevap)`,
`    END IF`,
`END`],
note:`Adı benzese de JavaScript'in Java ile ilgisi yoktur. Angular ve React JavaScript (ya da TypeScript) üzerine kurulu frontend araçlarıdır; Node.js ile JavaScript sunucuda da çalışabilir.`,
qs:[
{t:`Ev benzetmesinde JavaScript neye karşılık gelir?`,o:[`Elektrik tesisatı`,`İskelet`,`Boya`,`Tapu`],e:`Düğmeye basınca bir şey olmasını sağlayan tesisattır; sayfadaki davranış da JavaScript'tendir.`},
{t:`JavaScript ile Java arasındaki ilişki nedir?`,o:[`İsimleri benzer ama farklı dillerdir`,`Aynı dilin iki sürümüdür`,`JavaScript, Java'nın tarayıcı eklentisidir`,`Java, JavaScript'in derlenmiş halidir`],e:`İsim benzerliği tarihsel bir pazarlama tercihidir; diller birbirinden bağımsızdır.`},
{t:`Butona basınca sayfa yenilenmeden sunucudan veri çekilip tablo güncelleniyor. Bu hangi teknolojinin işidir?`,o:[`JavaScript`,`HTML`,`CSS`,`DNS`],e:`Arka planda istek atıp ekranı güncellemek JavaScript'in yaptığı iştir.`}
]}
]);

add(4,`Frontend ve tarayıcı`,[
{no:35,tr:`DOM`,en:`Document Object Model`,
def:`DOM, tarayıcının HTML'i okuyup bellekte oluşturduğu, sayfadaki her elemanın bir düğüm olduğu ağaç yapısıdır; JavaScript sayfayı bu ağaç üzerinden değiştirir.`,
an:`Soy ağacı gibi: en üstte sayfa, altında form, onun altında input ve buton. JavaScript bu ağaçta bir dalı bulur, değiştirir ya da yeni dal ekler.`,
fi:`DOM ağacı ve bir elemanı değiştirmek:`,
code:[`// HTML'den oluşan ağaç`,
`document`,
` └─ form#giris`,
`     ├─ input#musteriNo`,
`     └─ button#girisBtn`,
``,
`SET buton = CALL document.bul("#girisBtn")     // ağaçta bul`,
`SET buton.yazı = "Yükleniyor..."               // dalı değiştir`],
note:`Selenium'un findElement komutu, XPath ve CSS selector'lar DOM ağacında arama yapar. Eleman DOM'a eklenmeden aranırsa "element not found" hatası alınır.`,
qs:[
{t:`DOM nedir?`,o:[`Tarayıcının HTML'den oluşturduğu, elemanların ağaç şeklinde dizildiği yapı`,`Bir veritabanı türü`,`Bir sunucu işletim sistemi`,`CSS'in bir sürümü`],e:`HTML metindir; tarayıcı onu okuyup bellekte bir ağaca, yani DOM'a çevirir.`},
{t:`JavaScript sayfadaki bir yazıyı değiştirmek istediğinde neyi kullanır?`,o:[`DOM'u`,`Veritabanını`,`DNS'i`,`Derleyiciyi`],e:`JavaScript ağaçtaki ilgili düğümü bulur ve onu değiştirir; ekran da güncellenir.`},
{t:`Selenium "element not found" hatası veriyor. Olası sebep hangisidir?`,o:[`Eleman henüz DOM'a eklenmemiş`,`Veritabanı kapalı`,`İşlemci çok hızlı`,`Butonun rengi yanlış`],e:`Bileşen geç yüklenirse eleman ağaçta henüz yoktur; bu yüzden bekleme (wait) kullanılır.`}
]},
{no:36,tr:`Component`,en:`Component`,
def:`Component (bileşen), kendi görünümü ve davranışı olan, sayfada tekrar tekrar kullanılabilen bağımsız arayüz parçasıdır.`,
an:`Lego parçası: bir kere üretilir, farklı yerlerde birleştirilip kullanılır. Fatura kartı bileşeni hem ana sayfada hem detay sayfasında aynı parçadır.`,
fi:`Bir fatura kartı bileşeni ve kullanımı:`,
code:[`COMPONENT FaturaKartı(fatura)`,
`    SHOW fatura.dönem`,
`    SHOW fatura.tutar`,
`    IF fatura.ödendi == false THEN`,
`        SHOW "Öde" butonu`,
`    END IF`,
`END`,
``,
`FOR EACH f IN faturalar`,
`    CALL FaturaKartı(f)                 // aynı parça, farklı veri`,
`END FOR`],
note:`Angular, React ve Vue bileşen mantığıyla çalışır. Bir bileşende yapılan düzeltme onu kullanan tüm ekranlara yansır; bir hata da aynı şekilde yayılır.`,
qs:[
{t:`Component'in temel özelliği nedir?`,o:[`Kendi görünümü ve davranışı olan, tekrar kullanılabilen arayüz parçası olması`,`Bir veritabanı tablosu olması`,`Bir sunucu işletim sistemi olması`,`Sadece bir renk kodu olması`],e:`Lego gibi: bir kere yapılır, birçok yerde kullanılır.`},
{t:`FaturaKartı bileşenindeki bir hata düzeltilirse ne olur?`,o:[`Bileşeni kullanan tüm ekranlarda düzelir`,`Sadece tek bir ekranda düzelir`,`Hiçbir ekran etkilenmez`,`Veritabanı sıfırlanır`],e:`Parça tek olduğu için düzeltme de her yere birden yansır.`},
{t:`Lego benzetmesinde Lego parçası neye karşılık gelir?`,o:[`Component`,`DOM`,`Sunucu`,`Veritabanı`],e:`Bağımsız, birleştirilebilir ve tekrar kullanılabilir parça bileşendir.`}
]},
{no:37,tr:`Responsive Tasarım`,en:`Responsive Design`,
def:`Responsive tasarım, bir arayüzün telefon, tablet ve masaüstü gibi farklı ekran boyutlarına kendini otomatik uyarlayacak şekilde hazırlanmasıdır.`,
an:`Su gibi: hangi kaba dökersen onun şeklini alır. Aynı sayfa geniş ekranda üç sütun, telefonda tek sütun olur.`,
fi:`Ekran genişliğine göre yerleşim:`,
code:[`IF ekran_genişliği >= 1024 THEN`,
`    SET düzen = "3 sütun"           // masaüstü`,
`ELSE IF ekran_genişliği >= 768 THEN`,
`    SET düzen = "2 sütun"           // tablet`,
`ELSE`,
`    SET düzen = "1 sütun"           // telefon`,
`END IF`],
note:`CSS'te bu kurallar media query ile yazılır. Responsive testlerde DevTools'taki cihaz modu kullanılır; taşan tablolar ve sığmayan butonlar en sık bulgulardır.`,
qs:[
{t:`Responsive tasarımın amacı nedir?`,o:[`Arayüzün farklı ekran boyutlarına kendini uyarlaması`,`Sayfanın daha hızlı derlenmesi`,`Veritabanının küçülmesi`,`Sunucunun daha az elektrik harcaması`],e:`Su gibi: kap değişince şekil değişir, içerik aynı kalır.`},
{t:`Bu kurala göre 800 piksel genişliğindeki bir tablette düzen ne olur?`,o:[`2 sütun`,`3 sütun`,`1 sütun`,`Hata verir`],e:`800, 1024'ten küçük ama 768'den büyük; ikinci koşul çalışır.`},
{t:`CSS'te ekran boyutuna göre farklı kural yazmayı sağlayan yapı hangisidir?`,o:[`Media query`,`Try-catch`,`Foreign key`,`Webhook`],e:`Media query, "ekran şu genişlikteyse bu stili uygula" demenin yoludur.`}
]},
{no:38,tr:`DevTools`,en:`Developer Tools · Console / Network`,
def:`DevTools, tarayıcıya gömülü geliştirici araçlarıdır; sayfanın HTML'ini, JavaScript hatalarını (Console) ve sunucuya giden istekleri (Network) incelemeyi sağlar.`,
an:`Arabanın kaputunu açmak gibi: dışarıdan her şey normal görünür, kaputu açınca hangi parçanın ses yaptığını görürsün. Mac'te Cmd + Option + I ile açılır.`,
fi:`Ekranda "Bir hata oluştu" görünce izlenecek yol:`,
code:[`CALL aç(DevTools)`,
`FOR EACH istek IN network_sekmesi`,
`    IF istek.status >= 400 THEN`,
`        READ istek.request_body          // ne gönderildi?`,
`        READ istek.response_body         // ne döndü?`,
`    END IF`,
`END FOR`,
`READ console_sekmesi                     // kırmızı JS hataları var mı?`],
note:`Console'daki kırmızı hatalar genelde frontend kaynaklıdır; Network'te 4xx ya da 5xx dönen bir istek ise sorunu backend'e ya da veriye işaret eder. Bug kaydına bu ekranların görüntüsü eklenir.`,
qs:[
{t:`Sunucuya giden isteklerin durum kodunu ve cevabını DevTools'un hangi sekmesinde görürsün?`,o:[`Network`,`Console`,`Elements`,`Application`],e:`Network sekmesi her isteği, gönderilen veriyi ve dönen cevabı listeler.`},
{t:`Console'da kırmızı bir JavaScript hatası var, Network'teki tüm istekler 200 dönmüş. Sorun büyük ihtimalle nerededir?`,o:[`Frontend`,`Backend`,`Veritabanı`,`DNS`],e:`Sunucu doğru cevap vermiş; veriyi ekrana yansıtırken tarayıcı tarafında hata oluşmuş.`},
{t:`DevTools için en uygun benzetme hangisidir?`,o:[`Arabanın kaputunu açıp motoru incelemek`,`Arabayı boyamak`,`Arabayı satmak`,`Arabaya yakıt koymak`],e:`Dışarıdan görünmeyen çalışma mantığını incelemeyi sağlar.`}
]}
]);

add(5,`Ağ ve web`,[
{no:39,tr:`IP Adresi`,en:`IP Address`,
def:`IP adresi, bir ağa bağlı her cihazı tanımlayan ve verinin doğru cihaza ulaşmasını sağlayan sayısal adrestir.`,
an:`Evin açık adresi: kargo (veri) doğru kapıya bu adres sayesinde gider. 192.168.1.10 gibi sayılar bilgisayarların adres defteridir.`,
fi:`Bir paketin hedefe ulaşması:`,
code:[`SET hedef_ip = "10.20.30.40"            // sunucunun adresi`,
`SEND paket TO hedef_ip`,
`IF hedef_ip ulaşılamıyor THEN`,
`    SHOW "Connection timed out"`,
`END IF`,
``,
`// Özel ağ: 192.168.x.x, 10.x.x.x (sadece iç ağda geçerli)`,
`// Genel ağ: internette herkesin ulaşabildiği adresler`],
note:`IPv4 adresleri 4 parçalıdır (örn. 172.16.5.20). Şirket içi test ortamlarına genelde iç ağdaki IP'ler üzerinden erişilir; VPN kapalıyken bu adreslere ulaşılamaz.`,
qs:[
{t:`IP adresinin görevi nedir?`,o:[`Ağdaki bir cihazı tanımlayıp verinin doğru cihaza ulaşmasını sağlamak`,`Bir web sayfasını renklendirmek`,`Kullanıcının şifresini saklamak`,`Kodu derlemek`],e:`Kargo için açık adres neyse, veri için IP adresi odur.`},
{t:`Hangisi geçerli bir IPv4 adresidir?`,o:[`192.168.1.10`,`192.168.1`,`www.ornek.com`,`300.400.500.600`],e:`IPv4 dört parçadan oluşur ve her parça 0 ile 255 arasındadır. www.ornek.com ise bir alan adıdır.`},
{t:`10.x.x.x ile başlayan bir test sunucusuna evden VPN'siz neden ulaşılamaz?`,o:[`Bu adres şirketin iç (özel) ağına aittir`,`Adres yanlış yazılmıştır`,`Sunucu kesin kapalıdır`,`Tarayıcı eskidir`],e:`Özel IP'ler internete açık değildir; iç ağa VPN ile bağlanmak gerekir.`}
]},
{no:40,tr:`Port`,en:`Port`,
def:`Port, aynı IP adresindeki bir cihazda çalışan farklı servisleri birbirinden ayıran numaralı kapıdır.`,
an:`IP bir apartmanın adresi ise port daire numarasıdır. Kargo apartmana gelir ama doğru daireye port numarasıyla gider: web 443'te, PostgreSQL 5432'de oturur.`,
fi:`Aynı sunucuda farklı kapılar:`,
code:[`SET sunucu = "10.20.30.40"`,
`SEND istek TO sunucu:443        // HTTPS web servisi`,
`SEND istek TO sunucu:8080       // backend uygulaması`,
`SEND istek TO sunucu:5432       // PostgreSQL veritabanı`,
`IF port_kapalı THEN`,
`    SHOW "Connection refused"`,
`END IF`],
note:`Bilinen portlar: 80 HTTP, 443 HTTPS, 22 SSH, 1521 Oracle, 5432 PostgreSQL. localhost:8080 gibi adreslerde iki noktadan sonraki sayı porttur.`,
qs:[
{t:`Port neyi ayırt eder?`,o:[`Aynı cihazda çalışan farklı servisleri`,`Farklı ülkeleri`,`Farklı tarayıcıları`,`Farklı veritabanı tablolarını`],e:`Aynı apartmandaki farklı daireler gibi: adres aynı, kapı numarası farklı.`},
{t:`HTTPS'in varsayılan portu hangisidir?`,o:[`443`,`80`,`22`,`5432`],e:`80 HTTP, 22 SSH, 5432 PostgreSQL içindir; HTTPS 443'ü kullanır.`},
{t:`"localhost:8080" adresindeki 8080 nedir?`,o:[`Port numarası`,`IP adresi`,`Kullanıcı adı`,`HTTP durum kodu`],e:`İki noktadan sonra gelen sayı, bağlanılacak servisin kapı numarasıdır.`}
]},
{no:41,tr:`DNS`,en:`Domain Name System`,
def:`DNS, insanların hatırlayabildiği alan adlarını bilgisayarların kullandığı IP adreslerine çeviren sistemdir.`,
an:`Telefon rehberi: "Annem" yazarsın, telefon numarayı bulup arar. DNS de alan adını yazınca arka planda IP'yi bulur.`,
fi:`Tarayıcı bir alan adını çözerken:`,
code:[`SET alan_adı = "api.ornek.com"`,
`IF önbellekte_var(alan_adı) THEN`,
`    SET ip = CALL önbellekten_al(alan_adı)`,
`ELSE`,
`    SET ip = CALL dns_sunucusu.sor(alan_adı)    // "Bu adın IP'si ne?"`,
`END IF`,
`SEND istek TO ip`],
note:`Alan adı açılmıyor ama IP ile açılıyorsa sorun büyük ihtimalle DNS'tedir. Ortam değişikliğinden sonra eski DNS kaydının önbellekte kalması da sık görülen bir sorundur.`,
qs:[
{t:`DNS'in görevi nedir?`,o:[`Alan adını IP adresine çevirmek`,`Sayfayı renklendirmek`,`Veritabanını yedeklemek`,`Kullanıcıyı doğrulamak`],e:`Rehber gibi: isimden numarayı bulur.`},
{t:`Rehber benzetmesinde "Annem" yazmak neye karşılık gelir?`,o:[`Alan adı yazmak`,`IP adresi yazmak`,`Port açmak`,`Şifre girmek`],e:`İnsanların hatırladığı isim alan adıdır; numara ise IP adresidir.`},
{t:`Bir site alan adıyla açılmıyor ama IP adresiyle açılıyor. Sorun büyük ihtimalle nerededir?`,o:[`DNS`,`CSS`,`Veritabanı`,`Klavye`],e:`Sunucu ayakta; sadece isimden adrese çeviri başarısız oluyor.`}
]},
{no:42,tr:`URL ve Domain`,en:`URL and Domain`,
def:`URL, internetteki bir kaynağın tam adresidir; domain (alan adı) ise bu adresin sunucuyu tanımlayan, insanlar için okunabilir kısmıdır.`,
an:`Domain apartmanın adı, URL ise "apartman + kat + daire + kapıdaki isim" şeklindeki tam adrestir.`,
fi:`Bir URL'nin parçaları:`,
code:[`https://api.ornek.com:443/v1/faturalar/1002345?donem=2026-10`,
``,
`// https://               protokol`,
`// api.ornek.com          domain (api. kısmı alt alan adı, subdomain)`,
`// :443                   port`,
`// /v1/faturalar/1002345  path (kaynağın yolu)`,
`// ?donem=2026-10         query parametresi`],
note:`Test ve canlı ortam çoğu zaman sadece domain ile ayrılır (test-api... ve api... gibi). URL'deki küçük bir fark isteği tamamen başka bir ortama gönderebilir.`,
qs:[
{t:`https://api.ornek.com/v1/faturalar adresinde domain hangisidir?`,o:[`api.ornek.com`,`https`,`/v1/faturalar`,`v1`],e:`https protokol, /v1/faturalar path'tir; sunucuyu tanımlayan kısım api.ornek.com'dur.`},
{t:`URL'de ? işaretinden sonra gelen donem=2026-10 kısmı nedir?`,o:[`Query parametresi`,`Domain`,`Port`,`Protokol`],e:`Soru işaretinden sonra gelen anahtar=değer çiftleri query parametreleridir.`},
{t:`Apartman benzetmesinde URL neye karşılık gelir?`,o:[`Kat ve daire dahil tam adres`,`Sadece apartmanın adı`,`Apartmanın yöneticisi`,`Apartmanın asansörü`],e:`Domain apartmanın adıdır; URL ise kaynağa kadar giden tam adrestir.`}
]},
{no:43,tr:`Protokol`,en:`Protocol`,
def:`Protokol, iki sistemin birbiriyle nasıl konuşacağını belirleyen, mesajların biçimini ve sırasını tanımlayan ortak kurallar bütünüdür.`,
an:`Telefonda konuşma adabı: arayan "Alo" der, açan cevap verir, sırayla konuşulur, "Görüşürüz" ile kapanır. Kurallar ortak olmasa iki taraf anlaşamaz.`,
fi:`HTTP protokolünde bir konuşma:`,
code:[`// İstemci, protokolün istediği biçimde sorar`,
`SEND "GET /faturalar HTTP/1.1" TO sunucu`,
`SEND "Host: api.ornek.com" TO sunucu`,
``,
`// Sunucu, aynı kurallarla cevap verir`,
`RECEIVE "HTTP/1.1 200 OK"`,
`RECEIVE body`],
note:`HTTP, HTTPS, FTP, SMTP (e-posta), TCP ve IP birer protokoldür. Protokol kurallarına uymayan mesaj karşı tarafça anlaşılmaz ya da reddedilir.`,
qs:[
{t:`Protokol nedir?`,o:[`İki sistemin nasıl konuşacağını belirleyen ortak kurallar`,`Bir programlama dili`,`Bir donanım parçası`,`Bir veritabanı tablosu`],e:`Konuşma adabı gibi: kim, ne zaman, hangi biçimde konuşur.`},
{t:`Hangisi bir protokoldür?`,o:[`HTTP`,`JSON`,`Java`,`Oracle`],e:`JSON bir veri formatı, Java bir dil, Oracle bir veritabanıdır. HTTP ise iletişim protokolüdür.`},
{t:`Telefon adabı benzetmesinde "Alo" ile başlamak gibi kurallar neye karşılık gelir?`,o:[`Protokolün tanımladığı mesaj sırası ve biçimi`,`Veritabanı şeması`,`CSS stili`,`Değişken adı`],e:`Protokol mesajın biçimini ve sırasını önceden belirler.`}
]},
{no:44,tr:`HTTP / HTTPS`,en:`HyperText Transfer Protocol (Secure)`,
def:`HTTP, web'de istemci ile sunucu arasındaki istek ve cevapları taşıyan protokoldür; HTTPS ise aynı protokolün trafiği şifreleyerek taşıyan güvenli halidir.`,
an:`HTTP kartpostal gibidir: yolda eline geçen herkes okuyabilir. HTTPS mühürlü zarftır: sadece alıcı açabilir.`,
fi:`Aynı verinin iki yolculuğu:`,
code:[`// HTTP: veri açık taşınır`,
`SEND "kullanıcı=ayse&şifre=12345" TO http://site.com`,
`// Araya giren biri "şifre=12345" yazısını okur`,
``,
`// HTTPS: veri şifreli taşınır`,
`SEND "kullanıcı=ayse&şifre=12345" TO https://site.com`,
`// Araya giren biri "x8#Kq!9z..." gibi anlamsız veri görür`],
note:`HTTPS'in güvenliği SSL/TLS sertifikasından gelir. Tarayıcıdaki kilit simgesi bağlantının HTTPS olduğunu gösterir; giriş ve ödeme sayfalarında HTTP kabul edilemez.`,
qs:[
{t:`HTTP ile HTTPS arasındaki temel fark nedir?`,o:[`HTTPS trafiği şifreler, HTTP şifrelemez`,`HTTPS daha renkli sayfalar gösterir`,`HTTP sadece mobilde çalışır`,`HTTPS bir veritabanı protokolüdür`],e:`İkisi aynı dili konuşur; fark, HTTPS'in mesajı mühürlü zarfta taşımasıdır.`},
{t:`Kartpostal benzetmesi hangisine uyar?`,o:[`HTTP`,`HTTPS`,`DNS`,`VPN`],e:`Kartpostalı yoldaki herkes okuyabilir; şifresiz HTTP trafiği de öyledir.`},
{t:`Adres çubuğundaki kilit simgesi neyi gösterir?`,o:[`Bağlantının HTTPS ile şifreli olduğunu`,`Sitenin hiç hata vermediğini`,`Sitenin ücretsiz olduğunu`,`Sayfanın önbellekte olduğunu`],e:`Kilit, trafiğin geçerli bir sertifikayla şifrelendiğini gösterir; sitenin hatasız olduğunu değil.`}
]}
]);

add(5,`Ağ ve web`,[
{no:45,tr:`SSL / TLS Sertifikası`,en:`SSL / TLS Certificate`,
def:`SSL/TLS sertifikası, bir sitenin kimliğini doğrulayan ve HTTPS bağlantısının şifrelenmesini sağlayan, güvenilir bir otorite tarafından imzalanmış dijital belgedir.`,
an:`Noter onaylı kimlik kartı: "Ben gerçekten api.ornek.com'um" der ve bunu güvenilir bir kurum imzalamıştır. Süresi dolmuş kimlik kabul edilmez.`,
fi:`Tarayıcının sertifika kontrolü:`,
code:[`RECEIVE sertifika FROM sunucu`,
`IF sertifika.süresi_dolmuş THEN`,
`    SHOW "Bağlantınız gizli değil"`,
`ELSE IF sertifika.alan_adı != istenen_alan_adı THEN`,
`    SHOW "Sertifika bu siteye ait değil"`,
`ELSE IF NOT güvenilir_otorite_imzalamış THEN`,
`    SHOW "Güvenilmeyen sertifika"`,
`ELSE`,
`    CALL şifreli_bağlantı_kur()`,
`END IF`],
note:`SSL eski adıdır, bugün kullanılan TLS'tir ama ikisi aynı anlamda söylenir. Test ortamlarında self-signed (kendinden imzalı) sertifikalar yüzünden Postman ya da tarayıcı SSL hatası verebilir.`,
qs:[
{t:`SSL/TLS sertifikasının iki temel işi nedir?`,o:[`Sitenin kimliğini doğrulamak ve bağlantının şifrelenmesini sağlamak`,`Sayfayı hızlandırmak ve önbelleğe almak`,`Kullanıcı şifrelerini saklamak`,`Veritabanını yedeklemek`],e:`Kimlik kartı gibi "ben oyum" der; şifreli bağlantının anahtarı da bu kartla kurulur.`},
{t:`Sertifikasının süresi dolmuş bir siteye girince tarayıcı ne yapar?`,o:[`Güvenlik uyarısı gösterir`,`Siteyi daha hızlı açar`,`Hiçbir şey fark etmez`,`Bağlantıyı otomatik HTTP'ye çevirir`],e:`Süresi dolmuş kimlik geçersizdir; tarayıcı kullanıcıyı uyarır.`},
{t:`Postman "self signed certificate" hatası veriyor. Bu ne anlama gelir?`,o:[`Sertifika güvenilir bir otorite yerine sunucunun kendisi tarafından imzalanmış`,`Sunucu tamamen kapalı`,`İstek gövdesi hatalı`,`Kullanıcı şifresi yanlış`],e:`Kimliği kendi kendine onaylamak gibidir; araç bu imzaya varsayılan olarak güvenmez.`}
]},
{no:46,tr:`Localhost`,en:`Localhost`,
def:`Localhost, bir bilgisayarın kendisini işaret eden özel adrestir (127.0.0.1); bir uygulamayı dışarı açmadan kendi makinende çalıştırıp denemeyi sağlar.`,
an:`Kendi kendine mektup yazmak: zarf postaneye gitmeden aynı evin içinde elden ele geçer. Dışarıdan kimse o mektubu göremez.`,
fi:`Geliştiricinin kendi makinesinde çalışması:`,
code:[`RUN backend ON localhost:8080            // kendi bilgisayarında başlat`,
`SEND "GET /api/fatura/1" TO localhost:8080`,
`RECEIVE cevap                            // istek makineden hiç çıkmadı`,
``,
`// Başkası aynı adresi yazarsa kendi makinesine bakar`],
note:`"Bende çalışıyor" cümlesi çoğu zaman localhost'ta çalıştığı anlamına gelir; test ortamında farklı config, veri ya da ağ kuralları yüzünden davranış değişebilir.`,
qs:[
{t:`Localhost neyi işaret eder?`,o:[`Kullanılan bilgisayarın kendisini`,`Şirketin ana sunucusunu`,`Google'ın sunucusunu`,`En yakın DNS sunucusunu`],e:`Localhost her makinede "ben" demektir.`},
{t:`Localhost'un IP adresi hangisidir?`,o:[`127.0.0.1`,`192.168.1.1`,`8.8.8.8`,`10.0.0.1`],e:`127.0.0.1 her bilgisayarda kendisini gösteren özel adrestir.`},
{t:`Geliştirici sana "localhost:8080/fatura" linkini gönderdi; sen açınca çalışmıyor. Neden?`,o:[`Localhost senin bilgisayarını gösterir ve uygulama orada çalışmıyor`,`Linkin süresi dolmuş`,`Tarayıcın eski`,`Sunucu bakımda`],e:`Link senin makinende kendi makineni işaret eder; uygulama ise geliştiricinin makinesinde çalışıyor.`}
]},
{no:47,tr:`Proxy`,en:`Proxy`,
def:`Proxy, istemci ile hedef sunucu arasına giren, istekleri onun adına ileten ve bu sırada filtreleme, kayıt ya da önbellekleme yapabilen aracı sunucudur.`,
an:`Şirket santrali: dışarıyı doğrudan aramazsın, santral senin adına bağlar; kimin nereyi aradığını kaydeder, yasaklı numaraları engeller.`,
fi:`Kurumsal bir ağdan dışarı çıkış:`,
code:[`SEND istek TO proxy                       // önce aracıya`,
`// Proxy:`,
`IF hedef IN yasaklı_liste THEN`,
`    RETURN 403`,
`ELSE`,
`    LOG istek                             // kim, nereye, ne zaman`,
`    SEND istek TO hedef_sunucu            // senin adına ilet`,
`    RETURN cevap`,
`END IF`],
note:`Kurumsal ağlarda Maven, npm ya da Postman gibi araçların dışarıya erişmesi için proxy ayarı gerekebilir. Ayar yanlışsa "connection refused" ya da timeout hataları alınır.`,
qs:[
{t:`Proxy'nin temel işi nedir?`,o:[`İstemci adına istekleri iletmek ve bu sırada filtrelemek ya da kaydetmek`,`Alan adını IP'ye çevirmek`,`Sayfayı renklendirmek`,`Veritabanı sorgusu yazmak`],e:`Santral gibi: senin adına bağlar, kaydeder, gerekirse engeller.`},
{t:`Santral benzetmesinde santral neye karşılık gelir?`,o:[`Proxy`,`Hedef sunucu`,`İstemci`,`Veritabanı`],e:`Arada duran ve senin adına bağlantı kuran aracı proxy'dir.`},
{t:`Maven şirket ağında bağımlılık indiremiyor ama evde indiriyor. Olası sebep nedir?`,o:[`Şirket ağında proxy ayarı eksik ya da hatalı`,`Bilgisayarın RAM'i yetersiz`,`Kod derlenmemiş`,`Veritabanı kapalı`],e:`Kurumsal ağda dışarı çıkış proxy üzerinden yapılır; araç proxy'yi bilmezse dışarı çıkamaz.`}
]},
{no:48,tr:`Firewall`,en:`Firewall`,
def:`Firewall (güvenlik duvarı), ağ trafiğini önceden tanımlı kurallara göre denetleyip izin verilen bağlantıları geçiren, diğerlerini engelleyen güvenlik sistemidir.`,
an:`Sitenin güvenlik kulübesi: listede adı olan girer, olmayan kapıda kalır. Kural "sadece şu adreslerden, sadece 443 numaralı kapıdan" gibi yazılır.`,
fi:`Firewall kural kontrolü:`,
code:[`RECEIVE bağlantı`,
`IF bağlantı.kaynak_ip IN izinli_ipler AND bağlantı.port == 443 THEN`,
`    CALL izin_ver(bağlantı)`,
`ELSE`,
`    CALL düşür(bağlantı)          // sessizce: karşı taraf timeout alır`,
`END IF`],
note:`Yeni bir sistem başka bir sisteme bağlanacaksa genelde firewall izni (erişim talebi) açılması gerekir. Firewall'a takılan istekler çoğu zaman hata mesajı değil, timeout olarak görünür.`,
qs:[
{t:`Firewall'un temel görevi nedir?`,o:[`Ağ trafiğini kurallara göre denetleyip izin vermek ya da engellemek`,`Alan adını IP'ye çevirmek`,`Kodu derlemek`,`Kullanıcı arayüzünü çizmek`],e:`Güvenlik kulübesi gibi: listede olan geçer, olmayan kalır.`},
{t:`Firewall'a takılan bir istek istemci tarafında çoğunlukla nasıl görünür?`,o:[`Timeout`,`200 OK`,`201 Created`,`Syntax error`],e:`Firewall paketi genelde sessizce düşürür; istemci cevap bekler ve sonunda zaman aşımına uğrar.`},
{t:`Yeni bir servisin test veritabanına bağlanabilmesi için genelde ne yapılır?`,o:[`Firewall'da gerekli IP ve port için erişim izni açılır`,`Tarayıcı güncellenir`,`CSS dosyası değiştirilir`,`Bilgisayar yeniden başlatılır`],e:`Kulübedeki listeye yeni servisin adresini eklemek gerekir.`}
]},
{no:49,tr:`VPN`,en:`Virtual Private Network`,
def:`VPN, internet üzerinden şifreli bir tünel kurarak cihazı uzaktaki bir ağa, sanki o ağın içindeymiş gibi bağlayan teknolojidir.`,
an:`Evden şirkete kazılmış gizli bir tünel: içinden geçen kimseye görünmez ve tünelin ucu doğrudan şirketin içine açılır.`,
fi:`Evden test ortamına erişim:`,
code:[`IF vpn_bağlı == false THEN`,
`    SEND istek TO "test-api.sirket.local"     // iç ağ adresi`,
`    // sonuç: DNS çözülemez ya da timeout`,
`ELSE`,
`    SEND istek TO "test-api.sirket.local"`,
`    // sonuç: şirket içindeymiş gibi erişim`,
`END IF`],
note:`VPN koptuğunda iç ağdaki ortamlara, iç araçlara ve veritabanlarına erişim kesilir. "Ortam çalışmıyor" demeden önce VPN'i kontrol etmek iyi bir alışkanlıktır.`,
qs:[
{t:`VPN ne sağlar?`,o:[`Uzaktaki bir ağa şifreli tünelle, içerideymiş gibi bağlanmayı`,`İnternet hızını iki katına çıkarmayı`,`Kodun otomatik derlenmesini`,`Veritabanının yedeklenmesini`],e:`Tünelin ucu şirketin içine açılır; ağ seni içeride sanır.`},
{t:`Evden çalışırken şirket içindeki test sunucusu açılmıyor. İlk neyi kontrol edersin?`,o:[`VPN bağlantısını`,`Ekran parlaklığını`,`Klavye dilini`,`CSS dosyasını`],e:`İç ağ adreslerine dışarıdan ancak VPN ile ulaşılır.`},
{t:`Tünel benzetmesinde tünelin şirket tarafındaki ucu neyi anlatır?`,o:[`Bağlanınca şirketin iç ağındaymış gibi olmayı`,`Bilgisayarın kapanmasını`,`Bir veritabanı tablosunu`,`Bir CSS kuralını`],e:`Tünelden çıkınca kendini şirketin içinde bulursun.`}
]},
{no:50,tr:`Load Balancer`,en:`Load Balancer`,
def:`Load balancer (yük dengeleyici), gelen istekleri aynı uygulamanın birden fazla sunucusu arasında dağıtarak yükü dengeleyen ve çöken sunucuya trafik göndermeyen sistemdir.`,
an:`Bankadaki sıramatik: müşterileri boş veznelere dağıtır. Bir vezne kapanırsa ona numara vermez.`,
fi:`İsteklerin sunuculara dağıtılması:`,
code:[`SET sunucular = [s1, s2, s3]`,
`RECEIVE istek`,
`SET sıradaki = CALL en_az_meşgul(sunucular)`,
`IF sıradaki.sağlıklı THEN                // health check`,
`    SEND istek TO sıradaki`,
`ELSE`,
`    CALL listeden_çıkar(sıradaki)`,
`    SEND istek TO diğer_sunucu`,
`END IF`],
note:`Bir hata bazen görünüp bazen görünmüyorsa, istekler farklı sunuculara düşüyor ve sunuculardan biri farklı versiyon ya da config ile çalışıyor olabilir.`,
qs:[
{t:`Load balancer'ın görevi nedir?`,o:[`Gelen istekleri birden fazla sunucuya dağıtıp yükü dengelemek`,`Alan adını IP'ye çevirmek`,`Veriyi şifrelemek`,`Kullanıcı şifrelerini saklamak`],e:`Sıramatik gibi: kimse tek bir veznede yığılmaz.`},
{t:`Üç sunucudan biri çöktüğünde load balancer ne yapar?`,o:[`Çöken sunucuya trafik göndermeyi bırakır`,`Tüm sistemi kapatır`,`Çöken sunucuya daha çok trafik gönderir`,`Kullanıcıları siler`],e:`Health check başarısız olan sunucu dağıtımdan çıkarılır.`},
{t:`Aynı istek bazen başarılı bazen hatalı dönüyor. Olası sebep nedir?`,o:[`Sunuculardan biri farklı versiyon ya da config ile çalışıyor`,`Kullanıcının klavyesi bozuk`,`Butonun rengi yanlış`,`İnternet bağlantısı hiç yok`],e:`İstek hangi sunucuya düşerse onun davranışını görürsün; sunucular aynı değilse sonuç değişir.`}
]},
{no:51,tr:`Gateway / API Gateway`,en:`API Gateway`,
def:`API Gateway, arkadaki birçok servisin önünde duran, tüm istekleri tek bir giriş noktasından karşılayıp kimlik kontrolü, yönlendirme ve trafik sınırlaması yapan katmandır.`,
an:`Plazanın ana kapısı ve resepsiyonu: herkes aynı kapıdan girer, kimliği kontrol edilir ve hangi kata gideceği söylenir. Katlardaki ofisler kapı güvenliğiyle tek tek uğraşmaz.`,
fi:`API Gateway'in bir isteği karşılaması:`,
code:[`RECEIVE istek FROM istemci`,
`IF NOT token_geçerli(istek) THEN`,
`    RETURN 401                              // kimlik yok`,
`ELSE IF istek_sayısı > limit THEN`,
`    RETURN 429                              // çok fazla istek`,
`END IF`,
`IF istek.path == "/fatura" THEN`,
`    SEND istek TO fatura_servisi            // doğru kata yönlendir`,
`ELSE IF istek.path == "/odeme" THEN`,
`    SEND istek TO ödeme_servisi`,
`END IF`],
note:`Gateway arkadaki servise ulaşamazsa 502 Bad Gateway, servis zamanında cevap vermezse 504 Gateway Timeout döner. Bu hatalar çoğu zaman gateway'in değil, arkasındaki servisin sorununu gösterir.`,
qs:[
{t:`API Gateway'in temel işi nedir?`,o:[`Servislerin önünde tek giriş noktası olup kimlik kontrolü ve yönlendirme yapmak`,`Veritabanı tablolarını oluşturmak`,`Kullanıcı arayüzünü çizmek`,`Kodu derlemek`],e:`Resepsiyon gibi: kimlik kontrolü yapar ve doğru kata yönlendirir.`},
{t:`Plaza benzetmesinde resepsiyon neye karşılık gelir?`,o:[`API Gateway`,`Veritabanı`,`Frontend`,`İşletim sistemi`],e:`Herkesin geçtiği tek giriş noktası gateway'dir.`},
{t:`Gateway, arkadaki fatura servisinden zamanında cevap alamıyor. İstemci hangi hatayı görür?`,o:[`504 Gateway Timeout`,`200 OK`,`201 Created`,`400 Bad Request`],e:`Gateway bekledi ama arkadaki servis süresi içinde cevap vermedi; bu 504'tür.`}
]}
]);

add(6,`API dünyası`,[
{no:52,tr:`API`,en:`Application Programming Interface`,
def:`API, iki yazılımın birbiriyle konuşabilmesi için tanımlanmış kurallar ve giriş noktalarıdır; hangi isteğin nasıl gönderileceğini ve nasıl bir cevap alınacağını belirler.`,
an:`Restoranın menüsü ve garsonu: mutfağa girip yemeği kendin pişirmezsin; menüde ne varsa garsona söylersin, o da tabağı getirir. Menü, neyin istenebileceğini belirleyen API'dir.`,
fi:`Mobil uygulama faturayı backend'in API'sinden ister:`,
code:[`SEND GET "https://api.ornek.com/v1/faturalar/1002345"`,
`    WITH header Authorization = "Bearer abc123"`,
`RECEIVE cevap`,
`IF cevap.status == 200 THEN`,
`    SHOW cevap.body.tutar`,
`END IF`],
note:`API ekranı olmayan bir arayüzdür: kullanıcı için değil, başka yazılımlar için yazılır. Bu yüzden API'ler ekran olmadan Postman, SoapUI ya da Karate gibi araçlarla test edilir.`,
qs:[
{t:`API için en doğru tanım hangisidir?`,o:[`İki yazılımın konuşması için tanımlanmış kurallar ve giriş noktaları`,`Bir veritabanı türü`,`Bir programlama dili`,`Bir ekran tasarım aracı`],e:`API yazılımlar arası anlaşmadır: ne istenebilir, nasıl istenir, ne döner.`},
{t:`Restoran benzetmesinde menü neye karşılık gelir?`,o:[`API'nin neyin istenebileceğini tanımlaması`,`Veritabanı`,`Kullanıcı arayüzü`,`Sunucunun donanımı`],e:`Menüde olmayanı sipariş edemezsin; API'de tanımlı olmayanı da isteyemezsin.`},
{t:`API'ler neden ekran olmadan test edilebilir?`,o:[`Başka yazılımlar için yazıldıkları için doğrudan istek atılıp cevap kontrol edilir`,`API'lerin hiç cevabı olmadığı için`,`API'ler sadece veritabanında çalıştığı için`,`API'ler test edilemez`],e:`İstek gönderilir, gelen cevabın kodu ve içeriği doğrulanır; ekrana gerek yoktur.`}
]},
{no:53,tr:`Endpoint`,en:`Endpoint`,
def:`Endpoint, bir API'nin belirli bir işi yapan, URL ve HTTP metoduyla tanımlanmış tekil giriş noktasıdır.`,
an:`API bir restoransa endpoint menüdeki tek bir yemektir: "GET /faturalar" bir yemek, "POST /odemeler" başka bir yemek.`,
fi:`Bir fatura API'sinin endpoint'leri:`,
code:[`GET    /v1/faturalar                 // tüm faturaları listele`,
`GET    /v1/faturalar/{id}            // tek bir faturayı getir`,
`POST   /v1/odemeler                  // yeni ödeme oluştur`,
`PUT    /v1/musteriler/{id}/adres     // adresi güncelle`,
`DELETE /v1/odemeler/{id}/talimat     // ödeme talimatını iptal et`],
note:`Aynı URL farklı metotla farklı endpoint olabilir: GET /musteriler listeler, POST /musteriler yeni müşteri oluşturur. Swagger sayfaları bir API'nin tüm endpoint'lerini listeler.`,
qs:[
{t:`Endpoint nedir?`,o:[`API'nin URL ve metotla tanımlanmış tek bir giriş noktası`,`Bir veritabanı tablosu`,`Bir CSS dosyası`,`Bir sunucu işletim sistemi`],e:`Menüdeki tek bir yemek gibi: belli bir işi yapan tek bir kapıdır.`},
{t:`"GET /v1/faturalar/{id}" ve "POST /v1/odemeler" için ne söylenebilir?`,o:[`İkisi farklı endpoint'tir`,`İkisi aynı endpoint'tir`,`İkisi de veritabanı tablosudur`,`İkisi de frontend bileşenidir`],e:`Adres ve metot farklı olduğu için farklı işler yapan farklı giriş noktalarıdır.`},
{t:`Bir API'nin tüm endpoint'lerini listeleyen dokümantasyon sayfası genelde hangisidir?`,o:[`Swagger`,`Jenkins`,`Figma`,`Kibana`],e:`Swagger (OpenAPI), endpoint'leri, parametreleri ve cevap örneklerini tek sayfada gösterir.`}
]},
{no:54,tr:`Request / Response`,en:`Request / Response`,
def:`Request, istemcinin sunucuya gönderdiği istektir; response ise sunucunun bu isteğe döndüğü, durum kodu ve verisi olan cevaptır.`,
an:`Sipariş fişi ve gelen tabak: fişte ne istediğin yazar; tabakla birlikte bir not gelir: "Afiyet olsun" (200) ya da "Bu yemek kalmadı" (404).`,
fi:`Bir request ve response'un anatomisi:`,
code:[`// REQUEST`,
`POST /v1/odemeler                            // metot + endpoint`,
`Content-Type: application/json               // header`,
`{ "musteriNo": 1002345, "tutar": 249.90 }    // body`,
``,
`// RESPONSE`,
`HTTP/1.1 201 Created                         // durum kodu`,
`{ "odemeId": "OD-778", "durum": "ALINDI" }   // body`],
note:`Bir API testinde üç şey kontrol edilir: durum kodu doğru mu, body'deki alanlar ve değerler doğru mu, cevap süresi kabul edilebilir mi.`,
qs:[
{t:`Request ile response arasındaki ilişki nedir?`,o:[`Request istemcinin isteği, response sunucunun buna cevabıdır`,`İkisi de sunucudan gelir`,`Response her zaman request'ten önce gelir`,`İkisi de sadece veritabanında tutulur`],e:`Fiş gider, tabak gelir.`},
{t:`Response'ta isteğin sonucunu özetleyen bilgi hangisidir?`,o:[`HTTP durum kodu`,`Kullanıcının şifresi`,`CSS dosyası`,`Sunucunun IP adresi`],e:`200, 404, 500 gibi kodlar isteğin nasıl sonuçlandığını tek bakışta söyler.`},
{t:`Sipariş fişi benzetmesinde fiş neye karşılık gelir?`,o:[`Request`,`Response`,`Veritabanı`,`Endpoint listesi`],e:`Fiş, ne istediğini yazdığın kâğıttır; yani request.`}
]},
{no:55,tr:`HTTP Metotları`,en:`HTTP Methods · GET, POST, PUT, DELETE`,
def:`HTTP metotları, bir isteğin kaynak üzerinde ne yapmak istediğini söyleyen fiillerdir: GET okur, POST oluşturur, PUT ve PATCH günceller, DELETE siler.`,
an:`Kütüphanede kitapla yapılanlar: GET kitaba bakmak, POST rafa yeni kitap koymak, PUT kitabı yenisiyle değiştirmek, DELETE kitabı raftan kaldırmak.`,
fi:`Aynı kaynak üzerinde farklı metotlar:`,
code:[`GET    /musteriler/1002345      // oku: değişiklik yapmaz`,
`POST   /musteriler              // oluştur: yeni kayıt`,
`PUT    /musteriler/1002345      // güncelle: kaydın tamamını değiştir`,
`PATCH  /musteriler/1002345      // güncelle: sadece bir alanı değiştir`,
`DELETE /musteriler/1002345      // sil`],
note:`GET ile veri değiştirilmemelidir; GET tekrar tekrar atılsa da sunucudaki veri değişmemelidir. Desteklenmeyen metotla gelen isteğe sunucu 405 Method Not Allowed döner.`,
qs:[
{t:`Yeni bir kayıt oluşturmak için genellikle hangi metot kullanılır?`,o:[`POST`,`GET`,`DELETE`,`PATCH`],e:`Rafa yeni kitap koymak POST'tur.`},
{t:`GET isteğinin temel kuralı nedir?`,o:[`Veriyi okur, sunucuda değişiklik yapmaz`,`Her zaman veri siler`,`Sadece dosya yükler`,`Sadece şifreli çalışır`],e:`GET bakmaktır; bakmak kitabı değiştirmez.`},
{t:`Bir kaydın sadece telefon alanını güncellemek için en uygun metot hangisidir?`,o:[`PATCH`,`PUT`,`GET`,`DELETE`],e:`PUT kaydın tamamını gönderip değiştirir; tek bir alanı güncellemek için PATCH kullanılır.`}
]},
{no:56,tr:`Header`,en:`Header`,
def:`Header, bir isteğin ya da cevabın kendisiyle ilgili ek bilgileri (kimlik, içerik türü, dil gibi) taşıyan anahtar-değer alanlarıdır.`,
an:`Kargo paketinin üzerindeki etiket: içindekini değil, paketle ilgili bilgiyi taşır: kimden geldiği, ne olduğu, "kırılacak eşya" uyarısı.`,
fi:`Sık kullanılan header'lar:`,
code:[`// Request header'ları`,
`Authorization: Bearer eyJhbGciOi...      // kimlik (token)`,
`Content-Type: application/json           // body'nin formatı`,
`Accept-Language: tr-TR                   // istenen dil`,
`X-Correlation-Id: 7f3a-91bc              // isteği loglarda izlemek için`,
``,
`// Response header'ı`,
`Content-Type: application/json`],
note:`Token'ın eksik ya da hatalı olması 401, Content-Type'ın yanlış olması 415 Unsupported Media Type hatasına yol açar. Correlation id, bir isteği servisler arasında loglarda takip etmeyi sağlar.`,
qs:[
{t:`Header ne taşır?`,o:[`İstek ya da cevapla ilgili ek bilgileri (kimlik, format, dil)`,`Veritabanı tablolarını`,`Sayfanın CSS kodunu`,`Sunucunun işletim sistemini`],e:`Etiket gibi: paketin kendisini değil, paket hakkındaki bilgiyi taşır.`},
{t:`Body'nin JSON formatında olduğunu hangi header söyler?`,o:[`Content-Type`,`Authorization`,`Accept-Language`,`X-Correlation-Id`],e:`Content-Type: application/json, gövdenin JSON olduğunu bildirir.`},
{t:`Kargo etiketi benzetmesinde paketin içindeki ürün neye karşılık gelir?`,o:[`Body`,`Header`,`Endpoint`,`Port`],e:`Etiket header'dır; asıl gönderilen veri kutunun içindeki body'dir.`}
]},
{no:57,tr:`Body / Payload`,en:`Body / Payload`,
def:`Body (payload), bir istek ya da cevapta taşınan asıl veridir; genellikle JSON ya da XML formatındadır.`,
an:`Kargo paketinin içindeki ürün: etiket (header) paketi tanıtır, asıl gönderilen şey kutunun içindedir.`,
fi:`Ödeme isteğinin body'si ve sunucudaki kontrol:`,
code:[`// Request body`,
`{ "musteriNo": 1002345, "tutar": 249.90, "kartTipi": "KREDI" }`,
``,
`// Sunucu tarafı kontrol`,
`IF body.tutar <= 0 THEN`,
`    RETURN 400 WITH "tutar sıfırdan büyük olmalı"`,
`END IF`,
`IF body.musteriNo == null THEN`,
`    RETURN 400 WITH "musteriNo zorunlu"`,
`END IF`],
note:`GET isteklerinde genelde body olmaz; veri URL'deki parametrelerle gönderilir. Negatif testlerde zorunlu alanı silmek, tipini değiştirmek ve sınır değer vermek en verimli denemelerdir.`,
qs:[
{t:`Body nedir?`,o:[`İstek ya da cevapta taşınan asıl veri`,`İsteğin gönderildiği adres`,`Sunucunun IP adresi`,`Kimlik doğrulama yöntemi`],e:`Kutunun içindeki ürün: asıl iletilmek istenen veri.`},
{t:`Zorunlu bir alan body'de gönderilmezse doğru tasarlanmış bir API genellikle ne döner?`,o:[`400 Bad Request`,`200 OK`,`301 Redirect`,`503 Service Unavailable`],e:`İstek eksik ya da hatalı oluşturulmuş; hata istemci tarafında, bu yüzden 4xx döner.`},
{t:`Hangi metotta genelde body gönderilmez?`,o:[`GET`,`POST`,`PUT`,`PATCH`],e:`GET okumak içindir; ne istendiği URL ve parametrelerle anlatılır.`}
]},
{no:58,tr:`Query ve Path Parametresi`,en:`Query and Path Parameters`,
def:`Path parametresi URL yolunun içinde belirli bir kaynağı gösterir (/faturalar/1002345); query parametresi ise ? işaretinden sonra filtreleme ve sıralama gibi ek koşulları taşır (?donem=2026-10).`,
an:`Path parametresi daire numarasıdır: hangi kapıya gideceğini söyler. Query parametresi kapıdaki talimattır: "sadece ekim ayının mektuplarını ver".`,
fi:`İkisi bir arada:`,
code:[`GET /v1/musteriler/1002345/faturalar?donem=2026-10&durum=ODENMEDI`,
``,
`SET müşteri = path.id            // 1002345: hangi müşteri (path)`,
`SET dönem = query.donem          // 2026-10: filtre (query)`,
`SET durum = query.durum          // ODENMEDI: filtre (query)`],
note:`Path parametresi değişince başka bir kaynağa gidilir; query parametresi değişince aynı kaynağın farklı bir görünümü gelir. Var olmayan path parametresi genelde 404, geçersiz query değeri genelde 400 döner.`,
qs:[
{t:`/faturalar/1002345 adresindeki 1002345 nedir?`,o:[`Path parametresi`,`Query parametresi`,`Header`,`Port`],e:`URL yolunun içinde, hangi kaynağın istendiğini gösterir.`},
{t:`?donem=2026-10 hangi tür parametredir?`,o:[`Query parametresi`,`Path parametresi`,`Body`,`Header`],e:`Soru işaretinden sonra gelen anahtar=değer çiftleri query parametresidir.`},
{t:`Var olmayan bir müşteri numarası path parametresi olarak gönderilirse genelde hangi kod döner?`,o:[`404 Not Found`,`200 OK`,`201 Created`,`502 Bad Gateway`],e:`Böyle bir daire yok; kaynak bulunamadı demektir.`}
]}
]);

add(6,`API dünyası`,[
{no:59,tr:`JSON`,en:`JavaScript Object Notation`,
def:`JSON, veriyi anahtar-değer çiftleriyle, insanların da okuyabileceği hafif bir metin formatında taşıyan veri formatıdır.`,
an:`Etiketli saklama kutuları: "ad" etiketli kutuda "Ayşe", "hatlar" etiketli kutuda bir liste. Süslü parantez nesne, köşeli parantez liste demektir.`,
fi:`Bir müşteri cevabı JSON olarak (açıklamalar sadece burada, gerçek JSON'da yorum olmaz):`,
code:[`{`,
`  "musteriNo": 1002345,                     // sayı`,
`  "ad": "Ayşe Yılmaz",                      // metin`,
`  "aktif": true,                            // boolean`,
`  "faturaAdresi": null,                     // değer yok`,
`  "hatlar": ["5321112233", "5334445566"],   // liste`,
`  "paket": { "ad": "Kurumsal", "gb": 20 }   // iç içe nesne`,
`}`],
note:`REST API'lerin büyük çoğunluğu JSON konuşur. Sık hatalar: virgül unutmak, tırnaksız anahtar yazmak ya da sayı beklenen alana "1002345" gibi metin göndermek.`,
qs:[
{t:`JSON'da köşeli parantez [ ] neyi ifade eder?`,o:[`Liste (dizi)`,`Nesne`,`Yorum satırı`,`Boş değer`],e:`Süslü parantez { } nesne, köşeli parantez [ ] listedir.`},
{t:`"aktif": true alanının veri tipi nedir?`,o:[`Boolean`,`String`,`Integer`,`Liste`],e:`true ve false tırnaksız yazılır ve boolean'dır. "true" yazılsaydı metin olurdu.`},
{t:`Hangisi geçerli bir JSON nesnesidir?`,o:[`{ "ad": "Ayşe", "yas": 34 }`,`{ ad: Ayşe, yas: 34 }`,`( "ad" = "Ayşe" )`,`<ad>Ayşe</ad>`],e:`JSON'da anahtarlar ve metin değerler çift tırnak içinde yazılır. Son seçenek XML'dir.`}
]},
{no:60,tr:`XML`,en:`eXtensible Markup Language`,
def:`XML, veriyi açılış ve kapanış etiketleri arasında, hiyerarşik ve kendini tanımlayan bir yapıda taşıyan işaretleme formatıdır.`,
an:`İç içe zarflar: her zarfın üstünde ne olduğu yazar ve açılan her zarf kapanmak zorundadır. <musteri> açıldıysa </musteri> ile kapanır.`,
fi:`Aynı müşteri bilgisi XML olarak:`,
code:[`<musteri>`,
`  <musteriNo>1002345</musteriNo>`,
`  <ad>Ayşe Yılmaz</ad>`,
`  <aktif>true</aktif>`,
`  <hatlar>`,
`    <hat>5321112233</hat>`,
`    <hat>5334445566</hat>`,
`  </hatlar>`,
`</musteri>`],
note:`SOAP servisleri XML konuşur ve XML'in yapısı XSD şemasıyla tanımlanır. Kapanmamış tek bir etiket bile tüm mesajı geçersiz kılar. JSON'a göre daha uzun ama daha katı kurallıdır.`,
qs:[
{t:`<ad>Ayşe</ad> ifadesinde </ad> nedir?`,o:[`Kapanış etiketi`,`Açılış etiketi`,`Yorum satırı`,`Değişken`],e:`Eğik çizgiyle başlayan etiket, açılan zarfı kapatır.`},
{t:`XML hangi servis türüyle en çok anılır?`,o:[`SOAP`,`GraphQL`,`WebSocket`,`CSS`],e:`SOAP mesajlarının tamamı XML zarflarıdır.`},
{t:`XML'de açılan bir etiket kapatılmazsa ne olur?`,o:[`Mesaj geçersiz olur ve işlenemez`,`Etiket otomatik kapanır`,`Mesaj JSON'a dönüşür`,`Sadece uyarı verir, işlenmeye devam eder`],e:`XML katıdır: yapı bozuksa mesajın tamamı reddedilir.`}
]},
{no:61,tr:`REST`,en:`Representational State Transfer`,
def:`REST, kaynakları URL'lerle tanımlayıp bu kaynaklar üzerinde HTTP metotlarıyla işlem yapmayı öneren, genellikle JSON kullanan bir API tasarım yaklaşımıdır.`,
an:`İyi düzenlenmiş bir kütüphane: her kitabın sabit bir raf adresi var (URL) ve herkes aynı birkaç fiili kullanır: bak (GET), ekle (POST), değiştir (PUT), kaldır (DELETE).`,
fi:`REST yaklaşımıyla bir kaynak:`,
code:[`// Kaynak: fatura (URL'de isim olur, fiil olmaz)`,
`GET  /faturalar/77           // REST'e uygun: kaynak + metot`,
`POST /faturaGetir            // REST'e aykırı: fiil URL'de`,
``,
`// Her istek kendi başına yeter (stateless)`,
`SEND GET /faturalar/77 WITH token     // sunucu önceki isteği hatırlamaz`],
note:`REST bir protokol değil, bir tasarım yaklaşımıdır. Stateless olması, her isteğin kimlik dahil gereken her bilgiyi kendisi taşıması demektir; bu yüzden token her istekte gönderilir.`,
qs:[
{t:`REST nedir?`,o:[`Kaynakları URL'lerle tanımlayıp HTTP metotlarıyla işlem yapan API tasarım yaklaşımı`,`Bir veritabanı`,`Bir programlama dili`,`XML'i zorunlu kılan bir protokol`],e:`REST bir yaklaşımdır: kaynak URL'de, işlem metotta.`},
{t:`REST'e en uygun endpoint hangisidir?`,o:[`GET /faturalar/77`,`POST /faturaGetir`,`GET /faturaSil?id=77`,`POST /getAllFaturalar`],e:`URL'de kaynak adı, ne yapılacağı ise metotta olmalıdır.`},
{t:`REST'in "stateless" olması ne demektir?`,o:[`Her istek gereken tüm bilgiyi kendisi taşır, sunucu önceki isteği hatırlamak zorunda değildir`,`Sunucu hiç veri saklamaz`,`İstekler sadece gece çalışır`,`Cevaplar her zaman boş döner`],e:`Sunucu "az önce kimdi" diye hatırlamaz; her istek kimliğini yeniden getirir.`}
]},
{no:62,tr:`SOAP ve WSDL`,en:`SOAP and WSDL`,
def:`SOAP, XML zarflarıyla mesajlaşan, kuralları katı tanımlanmış bir web servis protokolüdür; WSDL ise bir SOAP servisinin hangi operasyonları hangi alanlarla sunduğunu anlatan XML sözleşmesidir.`,
an:`SOAP resmi yazışmadır: zarf, başlık ve gövde formatı kesin bellidir. WSDL o kurumun yazışma kılavuzudur: hangi dilekçeyi hangi alanlarla yazacağını söyler.`,
fi:`Bir SOAP isteğinin yapısı:`,
code:[`<soapenv:Envelope>                 // zarf`,
`  <soapenv:Header/>                // başlık`,
`  <soapenv:Body>                   // gövde`,
`    <getFatura>                    // WSDL'de tanımlı operasyon`,
`      <musteriNo>1002345</musteriNo>`,
`    </getFatura>`,
`  </soapenv:Body>`,
`</soapenv:Envelope>`],
note:`SoapUI'ye WSDL verildiğinde tüm operasyonların örnek istekleri otomatik oluşur. SOAP hatası genelde HTTP 500 ile birlikte body'de Fault elemanı olarak döner. Kurumsal ve eski sistemlerde hâlâ çok yaygındır.`,
qs:[
{t:`WSDL neyi tanımlar?`,o:[`Bir SOAP servisinin operasyonlarını ve alanlarını`,`Bir web sayfasının rengini`,`Bir veritabanının yedeğini`,`Bir sunucunun IP adresini`],e:`Yazışma kılavuzu gibi: hangi işlem hangi alanlarla istenir, ne döner.`},
{t:`SOAP mesajları hangi formattadır?`,o:[`XML`,`JSON`,`CSV`,`YAML`],e:`SOAP'ta zarf, başlık ve gövde XML etiketleriyle yazılır.`},
{t:`SoapUI'ye bir WSDL verildiğinde ne olur?`,o:[`Servisin operasyonları için örnek istekler otomatik oluşur`,`Servis silinir`,`Veritabanı yedeklenir`,`Servis REST'e dönüşür`],e:`Kılavuz okunur ve her dilekçenin boş şablonu hazırlanır.`}
]},
{no:63,tr:`Swagger / OpenAPI`,en:`Swagger / OpenAPI`,
def:`OpenAPI, bir REST API'nin endpoint'lerini, parametrelerini ve cevaplarını standart bir formatta tanımlayan şartnamedir; Swagger ise bu tanımı okunur ve denenebilir bir sayfaya çeviren araç setidir.`,
an:`Restoran menüsünün detaylı hali: her yemeğin içeriği, porsiyonu ve fiyatı yazar; üstelik menüden deneme siparişi bile verebilirsin (Try it out).`,
fi:`Bir endpoint'in OpenAPI tanımı (YAML):`,
code:[`/v1/faturalar/{id}:`,
`  get:`,
`    summary: Tek bir faturayı getirir`,
`    parameters:`,
`      - name: id`,
`        in: path`,
`        required: true`,
`    responses:`,
`      200: Fatura bulundu`,
`      404: Fatura bulunamadı`],
note:`OpenAPI, REST dünyasında WSDL'in karşılığı gibidir. Swagger'daki tanım ile API'nin gerçek davranışının farklı olması (kontrat uyumsuzluğu) sık bulunan hatalardandır.`,
qs:[
{t:`Swagger/OpenAPI ne işe yarar?`,o:[`REST API'nin endpoint, parametre ve cevaplarını standart biçimde tanımlayıp göstermek`,`Veritabanı yedeklemek`,`Sunucu donanımını izlemek`,`CSS dosyalarını sıkıştırmak`],e:`Detaylı menü gibi: ne var, nasıl istenir, ne döner.`},
{t:`Swagger sayfasındaki "Try it out" butonu ne sağlar?`,o:[`Endpoint'e doğrudan sayfadan istek atmayı`,`Sayfanın rengini değiştirmeyi`,`API'yi silmeyi`,`Kodu derlemeyi`],e:`Menüden deneme siparişi vermek gibi: isteği doldurup gönderir, cevabı görürsün.`},
{t:`OpenAPI'nin SOAP dünyasındaki karşılığı hangisidir?`,o:[`WSDL`,`JSON`,`Cookie`,`DNS`],e:`İkisi de servisin sözleşmesidir: biri REST için, diğeri SOAP için.`}
]},
{no:64,tr:`Mapping`,en:`Data Mapping`,
def:`Mapping, bir sistemin veri yapısındaki alanların başka bir sistemin veri yapısındaki karşılıklarına eşlenmesi ve gerekirse dönüştürülmesidir.`,
an:`İki farklı formun birbirine aktarılması: eski formdaki "Adı Soyadı" kutusu yeni formda "ad" ve "soyad" diye ikiye bölünür; "Durum: A" yeni formda "AKTIF" olur.`,
fi:`Eski sistemden gelen veriyi yeni yapıya eşlemek:`,
code:[`// Kaynak: CRM (XML)  ->  Hedef: API (JSON)`,
`SET hedef.musteriNo = kaynak.CUST_ID`,
`SET hedef.ad        = CALL böl(kaynak.FULL_NAME)[0]`,
`SET hedef.soyad     = CALL böl(kaynak.FULL_NAME)[1]`,
`IF kaynak.STATUS == "A" THEN`,
`    SET hedef.durum = "AKTIF"`,
`ELSE`,
`    SET hedef.durum = "PASIF"`,
`END IF`,
`SET hedef.tutar = kaynak.AMT / 100           // kuruştan TL'ye`],
note:`Mapping hataları sessizdir: sistem hata vermez ama yanlış alan yanlış yere gider. Bu yüzden her alan kaynak ve hedefte tek tek karşılaştırılır; null, boş ve özel karakterli değerler ayrıca denenir.`,
qs:[
{t:`Mapping nedir?`,o:[`Bir sistemdeki alanların başka sistemdeki karşılıklarına eşlenip dönüştürülmesi`,`Bir harita uygulaması`,`Veritabanının silinmesi`,`Bir CSS özelliği`],e:`Eski formdaki her kutunun yeni formda nereye gideceğini belirlemektir.`},
{t:`Kaynakta STATUS = "A" geliyor. Bu mapping'e göre hedefte durum ne olur?`,o:[`AKTIF`,`PASIF`,`A`,`null`],e:`Koşul doğru olduğu için "A" değeri "AKTIF" olarak eşlenir.`},
{t:`Mapping hatalarını tehlikeli yapan nedir?`,o:[`Çoğu zaman hata vermeden yanlış veri üretmeleri`,`Her zaman sistemi çökertmeleri`,`Sadece ekranda renk bozmaları`,`Sadece gece oluşmaları`],e:`İşlem başarılı görünür ama soyad ad alanına yazılmış olabilir; fark edilmesi zordur.`}
]},
{no:65,tr:`Webhook`,en:`Webhook`,
def:`Webhook, bir sistemde belirli bir olay gerçekleştiğinde, o sistemin önceden kaydedilmiş bir adrese kendiliğinden HTTP isteği göndererek haber vermesidir.`,
an:`Kargo takip sayfasını sürekli yenilemek yerine "Kargo yola çıkınca bana SMS at" demek. Sen sormazsın, olay olunca haber sana gelir.`,
fi:`Ödeme sağlayıcısının sonucu bildirmesi:`,
code:[`// Kurulum: adres bir kere kaydedilir`,
`CALL ödeme_sağlayıcı.kaydet("https://api.ornek.com/odeme-sonucu")`,
``,
`// Olay olunca sağlayıcı kendiliğinden çağırır`,
`ON ödeme_tamamlandı DO`,
`    SEND POST "https://api.ornek.com/odeme-sonucu"`,
`        WITH { "odemeId": "OD-778", "durum": "BASARILI" }`,
`END`],
note:`Normal API'de sen sorarsın (polling), webhook'ta sistem sana haber verir. Webhook'u alan servis o an kapalıysa bildirim kaçabilir; bu yüzden tekrar deneme (retry) mekanizması önemlidir.`,
qs:[
{t:`Webhook'un normal API çağrısından farkı nedir?`,o:[`Olay olunca karşı sistem kendiliğinden haber verir, sürekli sormaya gerek kalmaz`,`Webhook hiç HTTP kullanmaz`,`Webhook sadece veritabanında çalışır`,`Webhook her saniye otomatik soru sorar`],e:`SMS bildirimi gibi: haber sana gelir.`},
{t:`Kargo benzetmesinde "takip sayfasını sürekli yenilemek" neye karşılık gelir?`,o:[`Polling (sürekli sorma)`,`Webhook`,`DNS`,`Firewall`],e:`Durum değişti mi diye tekrar tekrar sormaya polling denir.`},
{t:`Webhook'u alacak servis o an kapalıysa ne risk oluşur?`,o:[`Bildirim kaçabilir; bu yüzden retry mekanizması gerekir`,`Hiçbir risk yoktur`,`Veritabanı silinir`,`Tarayıcı kapanır`],e:`SMS geldiğinde telefon kapalıysa mesaj kaybolabilir; tekrar gönderim bunu önler.`}
]}
]);

add(7,`Durum kodları ve hatalar`,[
{no:66,tr:`HTTP Status Code`,en:`HTTP Status Code · 2xx–5xx`,
def:`HTTP durum kodu, sunucunun her cevapta isteğin nasıl sonuçlandığını üç haneli bir sayıyla bildirmesidir; ilk hane sonucun ailesini söyler.`,
an:`Trafik ışığı gibi oku: 2xx yeşil (tamam), 3xx sarı (başka yere yönel), 4xx kırmızı ve hata sende (istemci), 5xx kırmızı ve hata bende (sunucu).`,
fi:`Durum kodunu ilk hanesine göre yorumlamak:`,
code:[`SET aile = ilk_hane(status)`,
`IF aile == 2 THEN SHOW "Başarılı"               // 200, 201, 204`,
`ELSE IF aile == 3 THEN SHOW "Yönlendirme"       // 301, 302, 304`,
`ELSE IF aile == 4 THEN SHOW "İstemci hatası"    // 400, 401, 403, 404`,
`ELSE IF aile == 5 THEN SHOW "Sunucu hatası"     // 500, 502, 503, 504`,
`END IF`],
note:`4xx görünce ilk soru "isteği doğru mu gönderdim?", 5xx görünce "sunucu tarafında ne bozuldu?" olmalıdır. Bug kaydına durum kodu her zaman yazılır.`,
qs:[
{t:`4xx ailesindeki kodlar genel olarak neyi anlatır?`,o:[`Hatanın istemci tarafında, yani istekte olduğunu`,`Sunucunun çöktüğünü`,`İsteğin başarılı olduğunu`,`Yönlendirme yapıldığını`],e:`4 ile başlayan kodlar "isteğinde bir sorun var" der.`},
{t:`503 kodu hangi aileye aittir?`,o:[`Sunucu hatası (5xx)`,`Başarılı (2xx)`,`Yönlendirme (3xx)`,`İstemci hatası (4xx)`],e:`İlk hane 5 olduğu için sorun sunucu tarafındadır.`},
{t:`Trafik ışığı benzetmesinde 2xx neye karşılık gelir?`,o:[`Yeşil: işlem tamam`,`Kırmızı: istemci hatası`,`Sarı: başka yere yönel`,`Kırmızı: sunucu hatası`],e:`2 ile başlayan kodlar başarı ailesidir.`}
]},
{no:67,tr:`200 OK / 201 Created`,en:`200 OK / 201 Created`,
def:`200 OK isteğin başarıyla işlendiğini, 201 Created ise isteğin başarıyla işlenip yeni bir kaynak oluşturulduğunu bildiren başarı kodlarıdır.`,
an:`200 "Siparişin hazır, buyur" demektir. 201 "Siparişin hazır ve senin için yeni bir masa da açtık" demektir: ortada yeni bir şey oluşmuştur.`,
fi:`Hangi işlem hangi başarı kodunu döner:`,
code:[`GET    /faturalar/77         -> 200 OK           // var olan veri döndü`,
`POST   /odemeler             -> 201 Created      // yeni kayıt oluştu`,
`PUT    /musteriler/5/adres   -> 200 OK           // güncellendi`,
`DELETE /talimatlar/9         -> 204 No Content   // silindi, içerik yok`],
note:`200 dönmesi her şeyin doğru olduğu anlamına gelmez: body'deki veri yanlış olabilir ya da bazı sistemler hatayı 200 ile birlikte body'de döner. Bu yüzden testte kod kadar body de kontrol edilir.`,
qs:[
{t:`Yeni bir ödeme kaydı başarıyla oluşturulduğunda en doğru kod hangisidir?`,o:[`201 Created`,`200 OK`,`204 No Content`,`404 Not Found`],e:`Yeni bir kaynak oluştuğu için en doğru başarı kodu 201'dir.`},
{t:`Bir API 200 döndü. Test için bu yeterli midir?`,o:[`Hayır, body'deki veri de doğrulanmalıdır`,`Evet, 200 her şeyin doğru olduğunu garanti eder`,`Hayır, 200 her zaman hata demektir`,`Evet, body hiçbir zaman kontrol edilmez`],e:`Kod yeşil olabilir ama tabağa yanlış yemek konmuş olabilir; içeriğe de bakılır.`},
{t:`204 No Content ne anlama gelir?`,o:[`İşlem başarılı ama dönecek içerik yok`,`Sunucu çöktü`,`Kaynak bulunamadı`,`Yetki yok`],e:`Silme gibi işlemlerde başarı bildirilir ama gövdede veri gönderilmez.`}
]},
{no:68,tr:`301 / 302 Redirect`,en:`Redirect`,
def:`301 ve 302 yönlendirme kodlarıdır: istenen kaynağın başka bir adreste olduğunu söyler; 301 kalıcı, 302 geçici taşınmayı anlatır.`,
an:`Taşınan dükkânın kapısındaki not: "Yeni adresimiz karşı sokak" (301, kalıcı) ya da "Tadilattayız, şu an yan dükkândayız" (302, geçici).`,
fi:`Tarayıcının yönlendirmeyi takip etmesi:`,
code:[`SEND GET "http://site.com/kampanya" TO sunucu`,
`RECEIVE 301 WITH header Location = "https://site.com/kampanyalar"`,
`SEND GET "https://site.com/kampanyalar"      // tarayıcı otomatik gider`,
`RECEIVE 200`],
note:`Yeni adres Location header'ında gelir. HTTP'den HTTPS'e ve giriş yapılmamışsa login sayfasına yönlendirme en yaygın örneklerdir. Sonsuz yönlendirme döngüsü "too many redirects" hatası verir.`,
qs:[
{t:`301 ile 302 arasındaki fark nedir?`,o:[`301 kalıcı, 302 geçici yönlendirmedir`,`301 hata, 302 başarıdır`,`301 sadece mobilde, 302 masaüstünde çalışır`,`Fark yoktur, ikisi aynıdır`],e:`Kapıdaki not ya "temelli taşındık" ya da "geçici olarak yandayız" der.`},
{t:`Yönlendirilecek yeni adres hangi header'da gelir?`,o:[`Location`,`Content-Type`,`Authorization`,`Accept-Language`],e:`Location header'ı "şuraya git" adresini taşır.`},
{t:`Giriş yapmadan korumalı bir sayfaya girince login sayfasına atılmak genelde hangi kod ailesiyle olur?`,o:[`3xx yönlendirme`,`2xx başarı`,`5xx sunucu hatası`,`1xx bilgi`],e:`Sunucu seni başka bir adrese, yani login sayfasına yönlendirir.`}
]},
{no:69,tr:`400 Bad Request`,en:`400 Bad Request`,
def:`400 Bad Request, sunucunun isteği hatalı biçimlendirildiği ya da geçersiz veri içerdiği için işleyemediğini bildiren istemci hatası kodudur.`,
an:`Eksik ya da yanlış doldurulmuş dilekçe: memur "Bu formu böyle kabul edemem, düzeltip tekrar getirin" der. Sorun memurda değil, dilekçededir.`,
fi:`Sunucunun bir isteği geri çevirmesi:`,
code:[`RECEIVE body`,
`IF NOT geçerli_json(body) THEN RETURN 400 WITH "Geçersiz JSON"`,
`IF body.tutar == null THEN RETURN 400 WITH "tutar zorunlu"`,
`IF body.tutar < 0 THEN RETURN 400 WITH "tutar negatif olamaz"`,
`IF NOT geçerli_tarih(body.tarih) THEN RETURN 400 WITH "tarih hatalı"`],
note:`İyi bir API, 400 ile birlikte hangi alanın neden reddedildiğini açıklayan bir mesaj döner. Negatif test senaryolarının çoğunun beklenen sonucu 400'dür.`,
qs:[
{t:`400 Bad Request genel olarak neyi anlatır?`,o:[`İsteğin hatalı ya da geçersiz veri içerdiğini`,`Sunucunun çöktüğünü`,`Kaynağın bulunamadığını`,`Yetkinin olmadığını`],e:`Dilekçe hatalı doldurulmuş; düzeltilip tekrar gönderilmeli.`},
{t:`Zorunlu "tutar" alanı olmadan ödeme isteği atılırsa beklenen kod nedir?`,o:[`400 Bad Request`,`200 OK`,`500 Internal Server Error`,`302 Found`],e:`Eksik zorunlu alan istemcinin hatasıdır; doğru cevap 400'dür.`},
{t:`Zorunlu alan eksikken API 500 dönüyor. Bu ne anlama gelir?`,o:[`Sunucu hatalı girdiyi düzgün yakalamıyor; bu bir bug'dır`,`Her şey doğru çalışıyor`,`İstemci hatası doğru raporlanmış`,`Sunucu bakımdadır`],e:`Hatalı istek 4xx ile dönmelidir. 500, sunucunun durumu yakalayamayıp çöktüğünü gösterir.`}
]},
{no:70,tr:`401 Unauthorized`,en:`401 Unauthorized`,
def:`401 Unauthorized, isteğin kimlik bilgisi olmadığı ya da kimlik bilgisinin (token) geçersiz veya süresi dolmuş olduğu için reddedildiğini bildiren koddur.`,
an:`Plazaya kartsız gelmek: güvenlik "Sizi tanımıyorum, kartınızı gösterin" der. Kim olduğun bilinmiyor.`,
fi:`Kimlik kontrolünün ilk adımı:`,
code:[`RECEIVE istek`,
`IF istek.header.Authorization == null THEN`,
`    RETURN 401              // kimlik hiç yok`,
`ELSE IF token_süresi_dolmuş(istek) THEN`,
`    RETURN 401              // kimlik var ama geçersiz`,
`END IF`,
`CALL devam_et(istek)`],
note:`Adı "Unauthorized" olsa da aslında kimlik doğrulama (authentication) hatasıdır. 401 görünce ilk bakılacak yer, token'ın gönderilip gönderilmediği ve süresinin dolup dolmadığıdır.`,
qs:[
{t:`401 Unauthorized en çok neyi anlatır?`,o:[`Kimliğin doğrulanamadığını (token yok ya da geçersiz)`,`Kimlik doğru ama yetki yok`,`Kaynak bulunamadı`,`Sunucu çöktü`],e:`Sunucu "sen kimsin?" sorusunun cevabını alamamıştır.`},
{t:`Dün çalışan bir istek bugün aynen gönderildiğinde 401 dönüyor. Olası sebep nedir?`,o:[`Token'ın süresi dolmuş`,`Veritabanı silinmiş`,`Body çok kısa`,`Endpoint'in adı değişmiş`],e:`Token'ların ömrü vardır; süresi dolan token ile kimlik kanıtlanamaz.`},
{t:`Plaza benzetmesinde 401 hangi duruma karşılık gelir?`,o:[`Kartsız gelip kim olduğunu kanıtlayamamak`,`Kartın var ama o kata giriş iznin yok`,`Plazanın kapalı olması`,`Gittiğin ofisin taşınmış olması`],e:`Kimlik hiç ya da geçerli şekilde gösterilmemiş.`}
]},
{no:71,tr:`403 Forbidden`,en:`403 Forbidden`,
def:`403 Forbidden, kimliği doğrulanmış kullanıcının istediği kaynağa ya da işleme yetkisi olmadığı için isteğin reddedildiğini bildiren koddur.`,
an:`Kartın var, plazaya girdin; ama yönetim katının turnikesi açılmıyor. Kim olduğun biliniyor, sadece oraya giriş iznin yok.`,
fi:`Yetki kontrolü:`,
code:[`SET kullanıcı = CALL token_çöz(istek)          // kim olduğu belli`,
`IF istek.işlem == "fatura_iptal" AND kullanıcı.rol != "SUPERVISOR" THEN`,
`    RETURN 403              // kimlik tamam, yetki yok`,
`END IF`,
`CALL fatura_iptal_et(istek)`],
note:`401 "seni tanımıyorum", 403 "seni tanıyorum ama buna iznin yok" demektir. Rol bazlı ekranlarda her rolün yetkisi olmayan işlemleri denemek, 403'ün doğru döndüğünü doğrulamanın yoludur.`,
qs:[
{t:`401 ile 403 arasındaki fark nedir?`,o:[`401 kimlik doğrulanamadı, 403 kimlik doğru ama yetki yok demektir`,`İkisi tamamen aynıdır`,`401 sunucu hatası, 403 başarıdır`,`403 kaynak bulunamadı demektir`],e:`Kartsız gelmek 401, kartla izinsiz kata çıkmaya çalışmak 403'tür.`},
{t:`Sadece yöneticilerin yapabildiği fatura iptalini normal bir kullanıcı denerse beklenen kod nedir?`,o:[`403 Forbidden`,`401 Unauthorized`,`200 OK`,`404 Not Found`],e:`Kullanıcı tanınıyor ama bu işleme yetkisi yok.`},
{t:`Plaza benzetmesinde 403 hangi duruma karşılık gelir?`,o:[`Kartın var ama yönetim katının turnikesi açılmıyor`,`Kartsız gelmek`,`Plazanın yanlış adreste olması`,`Asansörün bozulması`],e:`Kimlik geçerli, yetki yetersiz.`}
]},
{no:72,tr:`404 Not Found`,en:`404 Not Found`,
def:`404 Not Found, istenen adreste ya da istenen kimlikle bir kaynağın bulunamadığını bildiren koddur.`,
an:`Var olmayan bir daireye kargo götürmek: apartman doğru ama 47 numaralı daire yok. Kurye "Böyle bir adres yok" der.`,
fi:`404'ün iki farklı sebebi:`,
code:[`// 1) Endpoint yok: URL yanlış yazılmış`,
`GET /v1/faturlar/77                // "faturlar" yazım hatası: 404`,
``,
`// 2) Endpoint var, kayıt yok`,
`GET /v1/faturalar/99999999`,
`LOAD fatura FROM veritabanı WITH id = 99999999`,
`IF fatura == null THEN RETURN 404`],
note:`404 bazen kaynağın yokluğunu, bazen de yanlış URL'yi gösterir; cevap mesajı ikisini ayırt etmeye yardım eder. Güvenlik gereği bazı sistemler yetkisiz kaynaklar için 403 yerine 404 döner.`,
qs:[
{t:`404 Not Found neyi anlatır?`,o:[`İstenen kaynağın ya da adresin bulunamadığını`,`Kimliğin doğrulanamadığını`,`Sunucunun çöktüğünü`,`İsteğin başarılı olduğunu`],e:`Böyle bir daire yok: ne adres ne de kayıt bulunabildi.`},
{t:`Endpoint adında yazım hatası yapılırsa genelde ne döner?`,o:[`404 Not Found`,`201 Created`,`401 Unauthorized`,`503 Service Unavailable`],e:`Sunucu o yolda hiçbir şey bulamaz.`},
{t:`Doğru endpoint'e var olmayan bir fatura numarasıyla istek atılırsa beklenen kod nedir?`,o:[`404 Not Found`,`200 OK`,`500 Internal Server Error`,`302 Found`],e:`Kapı doğru ama arkasında böyle bir kayıt yok.`}
]}
]);

add(7,`Durum kodları ve hatalar`,[
{no:73,tr:`429 Too Many Requests`,en:`429 Too Many Requests`,
def:`429 Too Many Requests, istemcinin belirli bir sürede izin verilenden fazla istek gönderdiği için geçici olarak engellendiğini bildiren koddur.`,
an:`Kafeteryadaki "kişi başı 2 kurabiye" kuralı: üçüncüyü almaya kalkınca kasiyer "Biraz bekle" der. Yasaklanmadın, sadece yavaşlaman gerekiyor.`,
fi:`Sunucu tarafında istek sınırı:`,
code:[`SET limit = 100                           // dakikada en fazla 100 istek`,
`SET sayaç = CALL son_dakikadaki_istekler(istemci)`,
`IF sayaç >= limit THEN`,
`    RETURN 429 WITH header Retry-After = 30    // 30 saniye sonra dene`,
`ELSE`,
`    CALL isteği_işle()`,
`END IF`],
note:`Yük testlerinde gateway'in istek limitine takılıp 429 almak sık görülür; bu durumda ölçülen şey sistemin değil limitin sınırıdır. Retry-After header'ı ne kadar beklenmesi gerektiğini söyler.`,
qs:[
{t:`429 Too Many Requests ne anlatır?`,o:[`Belirli sürede izin verilenden fazla istek gönderildiğini`,`Kaynağın bulunamadığını`,`Sunucunun çöktüğünü`,`Body'nin hatalı olduğunu`],e:`Kurabiye kuralı: kotanı doldurdun, biraz beklemelisin.`},
{t:`429 ile gelen Retry-After header'ı ne söyler?`,o:[`Ne kadar bekledikten sonra tekrar denenebileceğini`,`Kaynağın yeni adresini`,`Kullanıcının token'ını`,`Body'nin formatını`],e:`Kasiyerin "30 saniye sonra gel" demesi gibidir.`},
{t:`Yük testinde isteklerin çoğu 429 dönüyor. Bu ne anlama gelir?`,o:[`Test, uygulamanın değil istek limitinin sınırını ölçüyor`,`Uygulama mükemmel çalışıyor`,`Veritabanı silinmiş`,`Tüm isteklerin body'si hatalı`],e:`İstekler uygulamaya ulaşmadan kapıda geri çevriliyor; limit test ortamı için ayarlanmalı.`}
]},
{no:74,tr:`500 Internal Server Error`,en:`500 Internal Server Error`,
def:`500 Internal Server Error, sunucuda beklenmeyen ve yakalanmayan bir hata oluştuğu için isteğin tamamlanamadığını bildiren genel sunucu hatası kodudur.`,
an:`Mutfakta ocak patladı: sipariş doğruydu, menüdeydi; ama içeride bir şeyler ters gitti. Garsonun söyleyebildiği tek şey "Mutfakta bir sorun oldu".`,
fi:`Yakalanmayan bir hatanın 500'e dönüşmesi:`,
code:[`RECEIVE istek`,
`SET müşteri = CALL müşteri_bul(istek.no)     // null döndü`,
`SET ad = müşteri.ad                          // NullPointerException`,
`// exception yakalanmadı`,
`RETURN 500                                   // Internal Server Error`],
note:`500 neredeyse her zaman bir bug'dır. Sebep cevapta değil, sunucu loglarındadır; bug kaydına isteğin zamanı ve varsa correlation id eklenirse geliştirici logu hızla bulur.`,
qs:[
{t:`500 Internal Server Error genelde neyi gösterir?`,o:[`Sunucuda beklenmeyen ve yakalanmayan bir hata oluştuğunu`,`İsteğin başarılı olduğunu`,`Kimliğin doğrulanamadığını`,`Kaynağın taşındığını`],e:`Sipariş doğru, mutfak çöktü.`},
{t:`500 hatasının asıl sebebini bulmak için nereye bakılır?`,o:[`Sunucu loglarına`,`Tarayıcı temasına`,`Klavye ayarlarına`,`DNS önbelleğine`],e:`Cevap sadece "sorun oldu" der; ne olduğu sunucunun loglarında yazar.`},
{t:`Mutfak benzetmesinde 500 hangi duruma karşılık gelir?`,o:[`Sipariş doğru ama mutfakta bir şey ters gitti`,`Sipariş fişi hatalı doldurulmuş`,`Menüde olmayan yemek istenmiş`,`Müşteri kimliğini göstermemiş`],e:`Hatalı fiş 400, olmayan yemek 404, kimliksiz müşteri 401 olurdu.`}
]},
{no:75,tr:`502 Bad Gateway`,en:`502 Bad Gateway`,
def:`502 Bad Gateway, araya giren bir gateway ya da proxy'nin arkadaki servisten geçersiz bir cevap aldığını ya da ona hiç bağlanamadığını bildiren koddur.`,
an:`Resepsiyon (gateway) yönetim katını arıyor ama hat düşüyor ya da karşıdan anlamsız bir ses geliyor. Resepsiyon çalışıyor; sorun arkadaki ofiste.`,
fi:`Gateway'in arkadaki servise ulaşamaması:`,
code:[`RECEIVE istek FROM istemci                   // gateway`,
`SET cevap = CALL fatura_servisi(istek)`,
`IF bağlantı_reddedildi OR cevap_bozuk THEN`,
`    RETURN 502                    // arkadaki servis düzgün cevap vermedi`,
`END IF`],
note:`502 genelde arkadaki servisin çöktüğünü, yeniden başladığını ya da deploy sırasında olduğunu gösterir. OpenShift gibi ortamlarda ilgili pod'un ayakta olup olmadığına bakmak ilk adımdır.`,
qs:[
{t:`502 Bad Gateway neyi anlatır?`,o:[`Gateway'in arkadaki servisten geçersiz cevap aldığını ya da ona bağlanamadığını`,`İstemcinin body'yi hatalı gönderdiğini`,`Kullanıcının yetkisi olmadığını`,`Kaydın başarıyla oluşturulduğunu`],e:`Resepsiyon arıyor ama arkadaki ofisten düzgün bir cevap gelmiyor.`},
{t:`Deploy sırasında kısa süreli 502 hataları görülmesinin olası sebebi nedir?`,o:[`Arkadaki servis o an yeniden başlıyor`,`Kullanıcının token'ı yanlış`,`Body'de zorunlu alan eksik`,`URL'de yazım hatası var`],e:`Servis ayağa kalkana kadar gateway ona bağlanamaz.`},
{t:`Resepsiyon benzetmesinde sorun nerededir?`,o:[`Arkadaki ofiste, yani serviste`,`Resepsiyonun kendisinde`,`Ziyaretçinin kimliğinde`,`Plazanın adresinde`],e:`Gateway işini yapıyor; cevap vermeyen arkadaki servis.`}
]},
{no:76,tr:`503 Service Unavailable`,en:`503 Service Unavailable`,
def:`503 Service Unavailable, sunucunun aşırı yük ya da bakım nedeniyle isteği şu an karşılayamadığını bildiren geçici bir hata kodudur.`,
an:`Kapıdaki "Bakımdayız" ya da "Yoğunluk nedeniyle sipariş alamıyoruz" levhası: dükkân yerinde ama şu an hizmet veremiyor.`,
fi:`Sunucunun kendini korumaya alması:`,
code:[`IF bakım_modu == true THEN`,
`    RETURN 503 WITH header Retry-After = 600     // 10 dakika sonra dene`,
`ELSE IF aktif_istek_sayısı > kapasite THEN`,
`    RETURN 503                                   // aşırı yük`,
`ELSE`,
`    CALL isteği_işle()`,
`END IF`],
note:`503 kalıcı değil geçicidir; durum düzelince aynı istek başarılı olur. Planlı bakımlar ve yük testlerinde kapasitenin aşılması en sık sebeplerdir.`,
qs:[
{t:`503 Service Unavailable neyi anlatır?`,o:[`Sunucunun bakım ya da aşırı yük nedeniyle şu an hizmet veremediğini`,`Kaynağın kalıcı olarak silindiğini`,`Kullanıcının şifresinin yanlış olduğunu`,`İsteğin başarılı olduğunu`],e:`Dükkân yerinde ama geçici olarak hizmet veremiyor.`},
{t:`503 ile 500 arasındaki fark nedir?`,o:[`503 genelde geçici bir kapasite ya da bakım durumu, 500 ise beklenmeyen bir hatadır`,`İkisi tamamen aynıdır`,`503 istemci hatasıdır`,`500 sadece bakımda döner`],e:`503 "şu an olmaz, sonra gel", 500 "içeride bir şey bozuldu" der.`},
{t:`Levha benzetmesinde "Bakımdayız" levhası hangi koda karşılık gelir?`,o:[`503`,`404`,`201`,`401`],e:`Bakım ve aşırı yük durumlarının kodu 503'tür.`}
]},
{no:77,tr:`504 Gateway Timeout`,en:`504 Gateway Timeout`,
def:`504 Gateway Timeout, araya giren gateway ya da proxy'nin arkadaki servisten belirlenen süre içinde cevap alamadığını bildiren koddur.`,
an:`Resepsiyon yönetim katını arıyor, telefon çalıyor ama kimse açmıyor; bir süre sonra "Cevap alamadım" der. Hat var, cevap yok.`,
fi:`Gateway'in bekleme süresi:`,
code:[`SET zaman_aşımı = 30                    // saniye`,
`SEND istek TO fatura_servisi`,
`WAIT cevap UNTIL zaman_aşımı`,
`IF cevap_gelmedi THEN`,
`    RETURN 504                          // servis yavaş ya da takıldı`,
`END IF`],
note:`502 "bağlanamadım ya da anlamsız cevap aldım", 504 "bağlandım ama zamanında cevap alamadım" demektir. 504 çoğu zaman yavaş bir veritabanı sorgusuna ya da arkadaki başka bir servisin yavaşlığına işaret eder.`,
qs:[
{t:`504 Gateway Timeout neyi anlatır?`,o:[`Gateway'in arkadaki servisten zamanında cevap alamadığını`,`Kullanıcının yetkisi olmadığını`,`Body'nin hatalı olduğunu`,`Kaynağın kalıcı olarak taşındığını`],e:`Telefon çaldı, kimse süresinde açmadı.`},
{t:`502 ile 504 arasındaki fark nedir?`,o:[`502 bağlanamadı ya da geçersiz cevap aldı, 504 ise cevap süresinde gelmedi demektir`,`İkisi tamamen aynıdır`,`504 istemci hatasıdır`,`502 bir başarı kodudur`],e:`Biri "hat düştü", diğeri "çaldı ama açılmadı" durumudur.`},
{t:`Bir rapor ağır sorgu yüzünden 40 saniyede hazırlanıyor, gateway limiti 30 saniye. Kullanıcı ne görür?`,o:[`504 Gateway Timeout`,`200 OK`,`401 Unauthorized`,`301 Moved Permanently`],e:`Gateway 30 saniyede vazgeçer; servis sonradan bitirse bile cevap kullanıcıya ulaşmaz.`}
]},
{no:78,tr:`Timeout`,en:`Timeout`,
def:`Timeout (zaman aşımı), bir isteğe ya da işleme belirlenen süre içinde cevap gelmediğinde beklemenin kesilip işlemin hata olarak sonlandırılmasıdır.`,
an:`Telefonu belli sayıda çaldırıp kapatmak: karşı taraf açmıyorsa sonsuza kadar beklemezsin. Bekleme süresinin sınırı timeout'tur.`,
fi:`Her katmanın kendi bekleme süresi:`,
code:[`SET frontend_timeout = 60                // saniye`,
`SET gateway_timeout  = 30`,
`SET backend_timeout  = 20                // arkadaki servisi bekleme süresi`,
`TRY`,
`    SET cevap = CALL servis() WITH timeout = backend_timeout`,
`CATCH TimeoutException`,
`    LOG "Servis 20 saniyede cevap vermedi"`,
`    RETURN hata`,
`END TRY`],
note:`Katmanların süreleri uyumsuzsa kullanıcı hata görürken arka planda işlem tamamlanmış olabilir. Ödeme gibi işlemlerde timeout sonrası "işlem gerçekleşti mi?" kontrolü kritik bir test senaryosudur.`,
qs:[
{t:`Timeout nedir?`,o:[`Belirlenen sürede cevap gelmeyince beklemenin kesilmesi`,`Sunucunun yeniden başlatılması`,`Bir veritabanı tablosu`,`Bir CSS animasyonu`],e:`Telefonu belli bir süre çaldırıp kapatmak gibi.`},
{t:`Ödeme isteği timeout'a düştü ve kullanıcı hata gördü. Hangi risk test edilmelidir?`,o:[`İşlemin arka planda yine de gerçekleşmiş olabileceği`,`Ekran renginin değişmesi`,`Klavyenin kilitlenmesi`,`DNS kaydının silinmesi`],e:`Bekleyen taraf vazgeçti ama işlemi yapan taraf işini bitirmiş olabilir; çift ödeme riski doğar.`},
{t:`Firewall'a takılan istekler istemci tarafında çoğunlukla nasıl görünür?`,o:[`Timeout`,`201 Created`,`204 No Content`,`301 Moved Permanently`],e:`Firewall genelde cevap vermeden düşürür; istemci bekler ve zaman aşımına uğrar.`}
]},
{no:79,tr:`CORS Error`,en:`Cross-Origin Resource Sharing`,
def:`CORS hatası, tarayıcının bir web sayfasının kendi adresinden farklı bir adresteki API'ye istek atmasını, o API izin vermediği için engellemesidir.`,
an:`Apartman görevlisi kuralı: başka binadan gelen kurye, ancak gideceği dairenin "bu kuryeyi kabul ediyorum" listesinde varsa içeri girer. Listeyi daire (API) tutar, kapıda kontrolü görevli (tarayıcı) yapar.`,
fi:`Tarayıcının CORS kontrolü:`,
code:[`// Sayfa: https://portal.ornek.com   API: https://api.ornek.com`,
`SEND OPTIONS istek TO api                 // ön kontrol (preflight)`,
`RECEIVE header Access-Control-Allow-Origin`,
`IF izinli_adres == "https://portal.ornek.com" THEN`,
`    SEND asıl_istek TO api`,
`ELSE`,
`    LOG "blocked by CORS policy"          // Console'da kırmızı hata`,
`END IF`],
note:`CORS bir tarayıcı kuralıdır: aynı istek Postman'den çalışır, tarayıcıdan hata verir. Kalıcı çözüm frontend'de değil, API tarafındaki Access-Control-Allow-Origin ayarındadır.`,
qs:[
{t:`CORS hatası neden oluşur?`,o:[`Farklı adresteki API izin vermediği için tarayıcı isteği engeller`,`Veritabanı kapalı olduğu için`,`Kullanıcının şifresi yanlış olduğu için`,`CSS dosyası bozuk olduğu için`],e:`Kurye listede yok; görevli kapıdan içeri almıyor.`},
{t:`Aynı istek Postman'den çalışıyor ama tarayıcıda CORS hatası veriyor. Neden?`,o:[`CORS tarayıcının uyguladığı bir kuraldır; Postman bu kontrolü yapmaz`,`Postman daha hızlı olduğu için`,`Tarayıcının interneti yavaş olduğu için`,`Postman veritabanına doğrudan bağlandığı için`],e:`Kapıdaki görevli tarayıcıdır; Postman o kapıdan geçmez.`},
{t:`CORS hatası kalıcı olarak nerede çözülür?`,o:[`API tarafındaki izin (Access-Control-Allow-Origin) ayarında`,`Kullanıcının bilgisayarında`,`Veritabanı tablosunda`,`CSS dosyasında`],e:`Listeyi daire tutar: izin API'nin cevabında verilmelidir.`}
]}
]);

add(8,`Güvenlik ve kimlik`,[
{no:80,tr:`Authentication`,en:`Authentication · Kimlik Doğrulama`,
def:`Authentication, bir kullanıcının ya da sistemin iddia ettiği kişi olduğunu kanıtlama sürecidir; "Sen kimsin?" sorusunun cevabıdır.`,
an:`Havalimanındaki pasaport kontrolü: görevli fotoğrafa ve yüzüne bakıp "Gerçekten bu kişi misin?" diye kontrol eder. Nereye uçabileceğin ise ayrı bir sorudur.`,
fi:`Giriş sırasında kimlik doğrulama:`,
code:[`GET kullanıcı_adı, şifre FROM giriş_formu`,
`LOAD kayıt FROM veritabanı WITH kullanıcı_adı`,
`IF kayıt == null OR hash(şifre) != kayıt.şifre_hash THEN`,
`    RETURN 401 WITH "Kullanıcı adı veya şifre hatalı"`,
`END IF`,
`IF kayıt.otp_gerekli THEN`,
`    CALL sms_kodu_iste()                 // ikinci adım (2FA)`,
`END IF`,
`RETURN token                             // kimlik kanıtlandı`],
note:`Şifre, SMS kodu (OTP), parmak izi ya da sertifika kimlik kanıtı olabilir; ikisinin birlikte istenmesine iki faktörlü doğrulama (2FA) denir. Hatalı girişte "kullanıcı yok" ile "şifre yanlış" ayrımı yapılmaması güvenlik gereğidir.`,
qs:[
{t:`Authentication hangi soruya cevap verir?`,o:[`Sen kimsin?`,`Neye iznin var?`,`Saat kaç?`,`Hangi sunucudasın?`],e:`Kimlik doğrulama, iddia edilen kimliğin gerçek olup olmadığını kontrol eder.`},
{t:`Şifreye ek olarak SMS kodu istenmesine ne denir?`,o:[`İki faktörlü doğrulama (2FA)`,`Authorization`,`Load balancing`,`Mapping`],e:`Bildiğin bir şey (şifre) ve sahip olduğun bir şey (telefon) birlikte istenir.`},
{t:`Hatalı girişte neden "Bu kullanıcı yok" yerine "Kullanıcı adı veya şifre hatalı" denir?`,o:[`Saldırganın hangi kullanıcıların var olduğunu öğrenmesini engellemek için`,`Mesaj daha kısa olduğu için`,`Veritabanı hızlansın diye`,`Tarayıcı bunu zorunlu tuttuğu için`],e:`Ayrı mesajlar, hangi kullanıcı adlarının geçerli olduğunu dışarıya sızdırır.`}
]},
{no:81,tr:`Authorization`,en:`Authorization · Yetkilendirme`,
def:`Authorization, kimliği doğrulanmış bir kullanıcının hangi işlemleri yapmaya ve hangi verilere erişmeye izinli olduğunu belirleme sürecidir; "Neye iznin var?" sorusunun cevabıdır.`,
an:`Pasaport kontrolünden geçtin (authentication); şimdi biniş kartına bakılıyor: business salonuna girebilir misin, hangi uçağa binebilirsin? Bu authorization'dır.`,
fi:`Rol bazlı yetki kontrolü:`,
code:[`SET kullanıcı = CALL kimliği_çöz(token)       // önce authentication`,
`IF istek.işlem IN kullanıcı.rol.izinler THEN`,
`    CALL işlemi_yap()`,
`ELSE`,
`    RETURN 403                                // yetki yok`,
`END IF`,
``,
`// TEMSILCI:   müşteri görüntüle, not ekle`,
`// SUPERVISOR: + fatura iptal, iade onayı`],
note:`Sıra her zaman önce authentication, sonra authorization şeklindedir. Yetki testlerinde ekranda butonun gizlenmesi yetmez; aynı işlem API'den doğrudan denendiğinde de 403 dönmelidir.`,
qs:[
{t:`Authorization hangi soruya cevap verir?`,o:[`Neye iznin var?`,`Sen kimsin?`,`Şifren ne?`,`Hangi tarayıcıyı kullanıyorsun?`],e:`Kimlik belli; şimdi bu kimliğin neler yapabileceğine bakılır.`},
{t:`Authentication ve authorization hangi sırayla yapılır?`,o:[`Önce authentication, sonra authorization`,`Önce authorization, sonra authentication`,`Aynı anda, sıra önemsiz`,`Sadece authorization yapılır`],e:`Kim olduğunu bilmeden neye izinli olduğuna karar verilemez.`},
{t:`Temsilci ekranında "Fatura iptal" butonu gizlenmiş. Yetki testi için bu yeterli midir?`,o:[`Hayır, aynı işlem API'den denendiğinde de 403 dönmelidir`,`Evet, buton gizliyse işlem yapılamaz`,`Hayır, butonun rengi de değişmelidir`,`Evet, API'ler zaten test edilmez`],e:`Buton gizlemek sadece görünümdür; asıl kontrol backend'de olmalıdır.`}
]},
{no:82,tr:`Token`,en:`Token`,
def:`Token, kimliği doğrulanan kullanıcıya verilen ve sonraki isteklerde şifre yerine kimlik kanıtı olarak gönderilen süreli dijital anahtardır.`,
an:`Festival bilekliği: girişte kimliğini bir kere gösterirsin, bileklik takılır. Sonra her sahneye bilekliğini göstererek girersin. Festival bitince bileklik geçersiz olur.`,
fi:`Token'ın yaşam döngüsü:`,
code:[`// 1) Giriş: bir kere şifre`,
`SEND POST /login WITH kullanıcı_adı, şifre`,
`RECEIVE token                           // örn: 15 dakika geçerli`,
``,
`// 2) Sonraki istekler: şifre yok, token var`,
`SEND GET /faturalar WITH header Authorization = "Bearer " + token`,
``,
`// 3) Süre dolunca`,
`RECEIVE 401                             // yeni token alınmalı`],
note:`Token şifre kadar değerlidir: loglara, ekran görüntülerine ve bug kayıtlarına açık şekilde yazılmamalıdır. Süresi dolan token'ı yenilemek için genelde refresh token kullanılır.`,
qs:[
{t:`Token ne işe yarar?`,o:[`Her istekte şifre göndermeden kimliği kanıtlamaya`,`Veritabanını yedeklemeye`,`Sayfayı renklendirmeye`,`Alan adını IP'ye çevirmeye`],e:`Bileklik gibi: kimliği bir kere gösterirsin, sonra bilekliği.`},
{t:`Token'ın süresi dolduktan sonra istek atılırsa genelde ne döner?`,o:[`401 Unauthorized`,`200 OK`,`201 Created`,`404 Not Found`],e:`Geçersiz bileklikle kimlik kanıtlanamaz.`},
{t:`Bir bug kaydına neden açık token yapıştırılmamalıdır?`,o:[`Token kimlik kanıtıdır; ele geçiren kişi kullanıcı adına işlem yapabilir`,`Token çok uzun olduğu için`,`Jira token kabul etmediği için`,`Token'lar her zaman yanlış olduğu için`],e:`Bilekliği başkasına vermek, onun senin yerine içeri girmesine izin vermektir.`}
]},
{no:83,tr:`JWT`,en:`JSON Web Token`,
def:`JWT, kullanıcı bilgilerini ve yetkilerini JSON olarak taşıyan, değiştirilmediğini kanıtlamak için dijital olarak imzalanmış, noktayla ayrılmış üç parçalı bir token formatıdır.`,
an:`Üzeri yazılı, mühürlü bir giriş kartı: adın, rolün ve son kullanma tarihin açıkça yazar; köşedeki mühür sayesinde yazının değiştirilmediği anlaşılır. Okunabilir ama taklit edilemez.`,
fi:`Bir JWT'nin üç parçası:`,
code:[`eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiIxMDAyMzQ1Iiwicm9sZSI6IlRFTVNJTENJIn0.Xk3...`,
``,
`// 1. Header:    { "alg": "HS256" }           imza yöntemi`,
`// 2. Payload:   { "sub": "1002345", "role": "TEMSILCI" }`,
`// 3. Signature: imza (içerik değişirse tutmaz)`],
note:`JWT'nin payload kısmı şifreli değil, sadece kodlanmıştır; herhangi bir JWT çözücüyle okunabilir. Bu yüzden içine şifre ya da hassas veri konmaz. "exp" alanı token'ın ne zaman geçersiz olacağını söyler.`,
qs:[
{t:`JWT kaç parçadan oluşur?`,o:[`3: header, payload, signature`,`2: kullanıcı adı ve şifre`,`1: sadece imza`,`4: header, body, footer, imza`],e:`Noktalarla ayrılmış üç parça vardır.`},
{t:`JWT'nin payload kısmı için hangisi doğrudur?`,o:[`Şifreli değildir, okunabilir; bu yüzden hassas veri konmaz`,`Tamamen şifrelidir, kimse okuyamaz`,`Sadece veritabanı açabilir`,`İçinde kullanıcının şifresi bulunur`],e:`Kartın üstündeki yazı herkes tarafından okunur; mühür sadece değiştirilmediğini kanıtlar.`},
{t:`Biri JWT'deki "role" alanını TEMSILCI'den SUPERVISOR'a çevirirse ne olur?`,o:[`İmza artık tutmaz ve token reddedilir`,`Kullanıcı süpervizör olur`,`Token'ın süresi uzar`,`Hiçbir şey değişmez`],e:`Yazıyı değiştirmek mührü bozar; sunucu imzayı doğrulayamaz.`}
]},
{no:84,tr:`OAuth 2.0`,en:`OAuth 2.0`,
def:`OAuth 2.0, bir uygulamanın kullanıcının şifresini hiç görmeden, kullanıcının onayıyla başka bir sistemdeki verilerine sınırlı erişim almasını sağlayan yetkilendirme standardıdır.`,
an:`Otel vale anahtarı: arabanı park ettirmek için valeye asıl anahtarını değil, sadece motoru çalıştırıp kapıyı açan ama bagajı açmayan özel anahtarı verirsin.`,
fi:`"Google ile giriş yap" akışı:`,
code:[`// 1) Kullanıcı Google'a yönlendirilir, şifresini sadece Google'a girer`,
`// 2) Google sorar: "Uygulama X profilinize erişmek istiyor, izin?"`,
`IF kullanıcı_izin_verdi THEN`,
`    RECEIVE yetki_kodu FROM google`,
`    SET access_token = CALL google.token_al(yetki_kodu)`,
`    CALL profil_getir(access_token)     // sadece izin verilen kapsam`,
`END IF`],
note:`Uygulama şifreyi hiç görmez; sadece sınırlı yetkili ve süreli bir token alır. Scope, token'ın neye erişebileceğini sınırlar: "sadece profil" verilen token takvime erişemez.`,
qs:[
{t:`OAuth 2.0'ın temel faydası nedir?`,o:[`Uygulamanın kullanıcının şifresini görmeden, onayıyla sınırlı erişim alması`,`Şifrelerin veritabanında açık saklanması`,`Sunucunun daha hızlı çalışması`,`Sayfanın responsive olması`],e:`Vale asıl anahtarı değil, sınırlı anahtarı alır.`},
{t:`Vale benzetmesinde "bagajı açmayan anahtar" neyi anlatır?`,o:[`Token'ın sadece izin verilen kapsamla (scope) sınırlı olmasını`,`Şifrenin paylaşılmasını`,`Sunucunun çökmesini`,`DNS çözümlemesini`],e:`Token sadece izin verilen işleri yapabilir.`},
{t:`"Google ile giriş yap" akışında kullanıcı şifresini kime girer?`,o:[`Sadece Google'a`,`Bağlandığı uygulamaya`,`Hem uygulamaya hem Google'a`,`Hiç kimseye`],e:`Şifre sadece kimliği yöneten tarafa girilir; uygulama sadece token alır.`}
]}
]);

add(8,`Güvenlik ve kimlik`,[
{no:85,tr:`SSO`,en:`Single Sign-On`,
def:`SSO, kullanıcının bir kez giriş yapıp aynı kimlikle birden fazla uygulamaya tekrar şifre girmeden erişebilmesini sağlayan kimlik yönetimi yaklaşımıdır.`,
an:`Plazanın tek giriş kartı: sabah bir kere okutursun; kantine, otoparka, toplantı odalarına aynı kartla girersin. Her kapı için ayrı kart taşımazsın.`,
fi:`Kurumsal uygulamalarda SSO:`,
code:[`CALL aç(jira)`,
`IF sso_oturumu_yok THEN`,
`    CALL yönlendir(kurumsal_giriş_sayfası)   // tek giriş noktası`,
`    GET kullanıcı_adı, şifre, otp FROM kullanıcı`,
`    SET sso_oturumu = "aktif"`,
`END IF`,
`CALL aç(confluence)                          // tekrar şifre sorulmaz`,
`CALL aç(jenkins)                             // tekrar şifre sorulmaz`],
note:`Şirketlerde Active Directory, Okta ya da Microsoft Entra ID gibi sistemlerle kurulur. Kolaylığın bedeli: SSO hesabı ele geçirilirse tüm uygulamalara erişilir, bu yüzden genelde 2FA ile korunur.`,
qs:[
{t:`SSO ne sağlar?`,o:[`Bir kez giriş yapıp birden fazla uygulamaya tekrar şifresiz erişmeyi`,`Her uygulamaya farklı şifreyle girmeyi`,`Şifresiz ve kimliksiz erişimi`,`Sadece mobil uygulamalara girişi`],e:`Tek kart, birçok kapı.`},
{t:`Plaza benzetmesinde tek giriş kartı neye karşılık gelir?`,o:[`SSO oturumu`,`Firewall`,`Load balancer`,`DNS`],e:`Bir kere doğrulanan kimlik, diğer kapılarda da geçerli olur.`},
{t:`SSO'nun güvenlik açısından riski nedir?`,o:[`Tek hesap ele geçirilirse tüm bağlı uygulamalara erişilebilir`,`Şifreler hiç kullanılmaz`,`Uygulamalar yavaşlar`,`Ekranlar responsive olmaz`],e:`Tek kart kaybolursa tüm kapılar açılır; bu yüzden ek doğrulama gerekir.`}
]},
{no:86,tr:`API Key`,en:`API Key`,
def:`API key, bir uygulamanın ya da sistemin bir API'yi kullanırken kendini tanıtmak için gönderdiği sabit ve gizli anahtardır.`,
an:`Apartmanın bina kapısı şifresi: kapıyı kimin açtığını değil, hangi daireye ait şifreyle açıldığını bilirsin. Şifre sızarsa değiştirilmesi gerekir.`,
fi:`API key ile bir SMS servisini çağırmak:`,
code:[`SET API_KEY = CALL ortam_değişkeni("SMS_API_KEY")   // koda gömülmez`,
`SEND POST "https://sms-saglayici.com/v1/gonder"`,
`    WITH header X-API-Key = API_KEY`,
`    WITH body { "telefon": "5321112233", "mesaj": "Faturanız hazır" }`,
`IF cevap.status == 401 THEN`,
`    LOG "API key geçersiz ya da iptal edilmiş"`,
`END IF`],
note:`API key genelde kullanıcıyı değil, çağıran sistemi tanıtır ve token gibi kendiliğinden süresi dolmaz. Bu yüzden koda, Git'e ya da ekran görüntüsüne açık yazılmaz; sızarsa hemen yenilenir (rotate).`,
qs:[
{t:`API key genelde neyi tanıtır?`,o:[`API'yi çağıran uygulamayı ya da sistemi`,`Son kullanıcının yüz fotoğrafını`,`Sunucunun işletim sistemini`,`Bir veritabanı tablosunu`],e:`Kapı şifresi daireyi tanıtır, kişiyi değil.`},
{t:`API key'in Git'e açık şekilde gönderilmesi neden tehlikelidir?`,o:[`Repo'ya erişen herkes o anahtarla API'yi kullanabilir`,`Git'i yavaşlattığı için`,`Kodun derlenmesini engellediği için`,`Anahtarın süresini uzattığı için`],e:`Kapı şifresini panoya asmak gibidir; okuyan herkes içeri girer.`},
{t:`API key ile token arasındaki tipik fark nedir?`,o:[`API key genelde sabittir ve sistemi tanıtır; token süreli olup kullanıcı oturumunu temsil eder`,`İkisi tamamen aynıdır`,`API key her 15 dakikada kendiliğinden yenilenir`,`Token hiç süresi dolmayan bir anahtardır`],e:`Bina şifresi kalıcıdır; festival bilekliği ise süreli ve kişiseldir.`}
]},
{no:87,tr:`Session ve Cookie`,en:`Session and Cookie`,
def:`Session, sunucunun bir kullanıcıyla olan oturumu bir süre boyunca hatırlamasıdır; cookie ise tarayıcıda saklanan ve her istekle sunucuya geri gönderilen, genelde session kimliğini taşıyan küçük veri parçasıdır.`,
an:`Vestiyer fişi: paltonu bırakırsın (session sunucuda tutulur), eline numaralı fiş verilir (cookie). Her gelişinde fişi gösterirsin, görevli paltonu tanır.`,
fi:`Session'ın cookie ile taşınması:`,
code:[`// Giriş sonrası sunucu:`,
`SET session = { id: "S-91f2", kullanıcı: "ayse" }`,
`SEND header Set-Cookie = "SESSIONID=S-91f2; HttpOnly; Secure"`,
``,
`// Sonraki her istekte tarayıcı kendiliğinden gönderir:`,
`SEND header Cookie = "SESSIONID=S-91f2"`,
`// Sunucu fişe bakıp oturumu bulur`],
note:`Cookie'ler DevTools'un Application sekmesinde görülür. HttpOnly işareti JavaScript'in cookie'yi okumasını, Secure işareti HTTP üzerinden gönderilmesini engeller. Çıkış yapınca session sunucuda da sonlandırılmalıdır.`,
qs:[
{t:`Vestiyer benzetmesinde fiş neye karşılık gelir?`,o:[`Cookie`,`Session`,`Sunucu`,`Veritabanı`],e:`Palto (oturum bilgisi) içeride kalır; elinde taşıdığın numara cookie'dir.`},
{t:`Cookie nerede saklanır?`,o:[`Tarayıcıda`,`Sadece veritabanında`,`Sadece DNS sunucusunda`,`Firewall'da`],e:`Fiş senin cebinde, yani tarayıcıda durur.`},
{t:`Cookie'deki HttpOnly işareti ne sağlar?`,o:[`JavaScript'in cookie'yi okumasını engeller`,`Cookie'nin süresini sonsuz yapar`,`Cookie'yi büyütür`,`Sayfayı hızlandırır`],e:`Böylece sayfaya sızan zararlı bir script oturum kimliğini çalamaz.`}
]},
{no:88,tr:`Encryption ve Hashing`,en:`Encryption and Hashing`,
def:`Encryption (şifreleme) veriyi anahtarla okunamaz hale getirir ve doğru anahtarla geri açılabilir; hashing ise veriden geri dönüşü olmayan, sabit uzunlukta bir parmak izi üretir.`,
an:`Şifreleme kilitli kasadır: anahtarı olan açar, içindekini aynen çıkarır. Hashing kıyma makinesidir: etten köfte olur ama köfteden eti geri elde edemezsin; aynı et her zaman aynı köfteyi verir.`,
fi:`İkisinin kullanım yeri:`,
code:[`// Şifreleme: geri açılması gereken veri`,
`SET kasa = CALL şifrele("5321112233", anahtar)     // "x9#Lq2..."`,
`SET açık = CALL çöz(kasa, anahtar)                 // "5321112233"`,
``,
`// Hashing: geri açılması gerekmeyen veri (örn. şifre)`,
`SET kayıtlı = CALL hash("Sifre123!")               // "a3f9...e1"`,
`IF CALL hash(girilen_şifre) == kayıtlı THEN SHOW "Giriş başarılı"`],
note:`Şifreler veritabanında açık ya da geri çözülebilir şekilde değil, hash'lenmiş olarak saklanır. Veritabanında şifre alanını okunabilir görmek ciddi bir güvenlik bulgusudur.`,
qs:[
{t:`Encryption ile hashing arasındaki temel fark nedir?`,o:[`Şifrelenen veri anahtarla geri açılabilir, hash'lenen veri geri döndürülemez`,`İkisi de geri döndürülemez`,`İkisi de herkes tarafından okunabilir`,`Hashing anahtarla geri açılır`],e:`Kasa açılır; köfte ete dönmez.`},
{t:`Kullanıcı şifreleri veritabanında nasıl saklanmalıdır?`,o:[`Hash'lenmiş olarak`,`Açık metin olarak`,`Base64 ile kodlanarak`,`Ekran görüntüsü olarak`],e:`Şifrenin kendisine değil, sadece doğru olup olmadığını kontrol etmeye ihtiyaç vardır.`},
{t:`Kıyma makinesi benzetmesi hangisine uyar?`,o:[`Hashing`,`Encryption`,`Cookie`,`DNS`],e:`Tek yönlüdür ve aynı girdi hep aynı sonucu verir.`}
]},
{no:89,tr:`SQL Injection ve XSS`,en:`SQL Injection and Cross-Site Scripting`,
def:`SQL injection kullanıcı girdisinin veritabanı sorgusuna komut olarak sızması, XSS ise girdinin sayfaya kod olarak yerleşip başka kullanıcıların tarayıcısında çalışmasıdır; ikisi de girdinin denetlenmemesinden doğar.`,
an:`Dilekçeye "ve kasadaki tüm parayı bana verin" cümlesini ekleyip memurun bunu talimat sanması gibi: sistem, veri olması gereken şeyi komut olarak çalıştırır.`,
fi:`Açık ve korunmuş versiyon:`,
code:[`GET ad FROM arama_kutusu                  // girilen: ' OR '1'='1`,
``,
`// Açık: girdi sorgunun içine yapıştırılır`,
`SET sorgu = "SELECT * FROM musteri WHERE ad = '" + ad + "'"`,
`// Sonuç: koşul hep doğru olur, tüm müşteriler döner`,
``,
`// Korunmuş: girdi sadece veri olarak geçer (parametreli sorgu)`,
`SET sorgu = "SELECT * FROM musteri WHERE ad = ?" WITH ad`,
``,
`// XSS: yoruma <script>alert(1)<\/script> yazılıp temizlenmezse`,
`// sayfayı açan herkesin tarayıcısında bu kod çalışır`],
note:`Güvenlik testlerinde arama kutularına ve formlara tek tırnak (') ya da <script> gibi özel girdiler yazılarak sistemin bunları veri olarak işleyip işlemediği kontrol edilir. Asıl koruma, girdinin her zaman veri olarak ele alınmasıdır.`,
qs:[
{t:`SQL injection nedir?`,o:[`Kullanıcı girdisinin veritabanı sorgusuna komut olarak sızması`,`Veritabanının yedeklenmesi`,`SQL'in yeni bir sürümü`,`Sorguların hızlandırılması`],e:`Dilekçedeki cümle talimat sanılıyor.`},
{t:`SQL injection'a karşı temel koruma hangisidir?`,o:[`Parametreli sorgu kullanıp girdiyi sadece veri olarak işlemek`,`Veritabanını kapatmak`,`Şifreleri açık saklamak`,`Sayfayı responsive yapmak`],e:`Girdi sorgu metnine yapıştırılmaz; ayrı bir veri olarak gönderilir.`},
{t:`Bir yorum alanına <script>alert(1)<\/script> yazılınca, yorumu açan herkeste uyarı penceresi çıkıyor. Bu hangi açıktır?`,o:[`XSS`,`SQL injection`,`CORS`,`404 Not Found`],e:`Girdi sayfaya kod olarak yerleşip başkalarının tarayıcısında çalışıyor.`}
]}
]);

add(9,`Veri ve veritabanı`,[
{no:90,tr:`SQL`,en:`Structured Query Language`,
def:`SQL, ilişkisel veritabanlarında veriyi sorgulamak, eklemek, güncellemek ve silmek için kullanılan standart sorgu dilidir.`,
an:`Arşiv memuruna verilen standart talep formu: "Şu dolaptan, şu şartı sağlayan dosyaları, şu sırayla getir." Formun dili bütün arşivlerde aynıdır.`,
fi:`Temel SQL komutları:`,
code:[`// Oku`,
`SELECT ad, paket FROM musteri WHERE durum = 'AKTIF';`,
`// Ekle`,
`INSERT INTO odeme (musteri_no, tutar) VALUES (1002345, 249.90);`,
`// Güncelle`,
`UPDATE musteri SET paket = 'Kurumsal 50' WHERE musteri_no = 1002345;`,
`// Sil`,
`DELETE FROM odeme_talimati WHERE id = 9;`],
note:`SQL'de en tehlikeli hata WHERE'siz UPDATE ya da DELETE'tir: koşul unutulursa tablodaki tüm satırlar değişir. Oracle'ın PL/SQL'i ve PostgreSQL, SQL'in üzerine kendi özelliklerini ekler.`,
qs:[
{t:`SQL ne için kullanılır?`,o:[`İlişkisel veritabanında veriyi sorgulamak ve değiştirmek için`,`Web sayfasını renklendirmek için`,`Sunucu donanımını izlemek için`,`Kodu derlemek için`],e:`Arşive verilen standart talep formu gibidir.`},
{t:`Bir tablodan veri okumak için hangi komut kullanılır?`,o:[`SELECT`,`INSERT`,`UPDATE`,`DELETE`],e:`SELECT okur; diğerleri veriyi ekler, değiştirir ya da siler.`},
{t:`"DELETE FROM odeme;" komutu WHERE olmadan çalıştırılırsa ne olur?`,o:[`Tablodaki tüm satırlar silinir`,`Sadece ilk satır silinir`,`Hiçbir şey silinmez`,`Sadece son eklenen satır silinir`],e:`Koşul yoksa "hepsi" anlamına gelir; bu yüzden WHERE hayati önemdedir.`}
]},
{no:91,tr:`Tablo / Kolon / Satır`,en:`Table / Column / Row`,
def:`Tablo, ilişkisel veritabanında aynı türdeki kayıtların tutulduğu yapıdır; kolon her kaydın bir özelliğini, satır ise tek bir kaydı temsil eder.`,
an:`Excel sayfası gibi: sayfa tablo, sütun başlıkları kolon (ad, paket, durum), her bir satır da tek bir müşteri.`,
fi:`MUSTERI tablosu:`,
code:[`┌────────────┬─────────────┬─────────────┬───────┐`,
`│ MUSTERI_NO │ AD          │ PAKET       │ DURUM │  <- kolonlar`,
`├────────────┼─────────────┼─────────────┼───────┤`,
`│ 1002345    │ Ayşe Yılmaz │ Kurumsal 20 │ AKTIF │  <- satır`,
`│ 1002346    │ Mehmet Kaya │ Kurumsal 50 │ PASIF │  <- satır`,
`└────────────┴─────────────┴─────────────┴───────┘`],
note:`Her kolonun bir veri tipi vardır (NUMBER, VARCHAR, DATE gibi). Ekranda görünen bir alanın hangi tablonun hangi kolonundan geldiğini bilmek, veri kontrolünü çok hızlandırır.`,
qs:[
{t:`Tablodaki tek bir müşteri kaydı neye karşılık gelir?`,o:[`Satır`,`Kolon`,`Tablo`,`Veritabanı`],e:`Her satır bir kayıttır; burada bir müşteri.`},
{t:`"DURUM" neyin adıdır?`,o:[`Kolon`,`Satır`,`Tablo`,`Sorgu`],e:`Her kaydın bir özelliğini tutan sütun, yani kolondur.`},
{t:`Excel benzetmesinde sütun başlıkları neye karşılık gelir?`,o:[`Kolonlar`,`Satırlar`,`Tablolar`,`Sorgular`],e:`Sütun başlıkları her kaydın hangi bilgileri taşıyacağını tanımlar.`}
]},
{no:92,tr:`Primary Key ve Foreign Key`,en:`Primary Key and Foreign Key`,
def:`Primary key bir tablodaki her satırı benzersiz şekilde tanımlayan kolondur; foreign key ise bir satırı başka bir tablonun primary key'ine bağlayarak iki tablo arasında ilişki kuran kolondur.`,
an:`Primary key TC kimlik numarası gibidir: herkesinki farklıdır, kişiyi tek başına tanımlar. Foreign key, faturanın üzerine yazılan TC numarasıdır: faturayı doğru kişiye bağlar.`,
fi:`İki tablo arasındaki bağ:`,
code:[`// MUSTERI tablosu`,
`MUSTERI_NO    PK      // her müşteride benzersiz`,
`AD`,
``,
`// FATURA tablosu`,
`FATURA_NO     PK      // her faturada benzersiz`,
`MUSTERI_NO    FK      // MUSTERI.MUSTERI_NO'ya bağlanır`,
`TUTAR`,
``,
`// Var olmayan bir müşteriye fatura eklenemez`,
`INSERT INTO fatura VALUES (5001, 9999999, 100);    // FK hatası`],
note:`Primary key tekrar edemez ve boş olamaz. Foreign key, ilişkili kaydı olmayan "yetim" veri oluşmasını engeller; silme işlemlerinde de bağlı kayıtlar yüzünden hata alınabilir.`,
qs:[
{t:`Primary key'in temel özelliği nedir?`,o:[`Her satırı benzersiz tanımlar; tekrar edemez ve boş olamaz`,`Her satırda aynı değeri taşır`,`Sadece metin olabilir`,`Sadece başka tabloya bağlantı kurar`],e:`TC numarası gibi: tek başına bir kaydı işaret eder.`},
{t:`FATURA tablosundaki MUSTERI_NO kolonu nedir?`,o:[`Foreign key`,`Primary key`,`Index adı`,`Tablo adı`],e:`Faturayı MUSTERI tablosundaki bir satıra bağlar.`},
{t:`Var olmayan bir müşteri numarasıyla fatura eklenmeye çalışılırsa ne olur?`,o:[`Foreign key kısıtı hata verir`,`Kayıt sorunsuz eklenir`,`Yeni müşteri otomatik oluşur`,`Tüm tablo silinir`],e:`Bağlanacak bir müşteri yoksa veritabanı kaydı reddeder.`}
]},
{no:93,tr:`Query (Sorgu)`,en:`Query`,
def:`Query, veritabanından belirli koşullara uyan veriyi getirmek ya da veriyi değiştirmek için yazılan komuttur.`,
an:`Arşivciye verilen net talimat: "Ekim ayında, borcu 500 TL'nin üstünde olan ödenmemiş faturaları, tutara göre büyükten küçüğe getir."`,
fi:`Bu talimatın SQL hali:`,
code:[`SELECT musteri_no, tutar`,
`FROM fatura`,
`WHERE donem = '2026-10'`,
`  AND tutar > 500`,
`  AND durum = 'ODENMEDI'`,
`ORDER BY tutar DESC;`],
note:`Test verisi bulmak, ekrandaki değeri veritabanıyla karşılaştırmak ve bir işlemden sonra kaydın doğru yazıldığını kontrol etmek için sorgu yazılır. Büyük tablolarda koşulsuz sorgu çok yavaş çalışabilir.`,
qs:[
{t:`Query nedir?`,o:[`Veritabanından koşula uyan veriyi getirmek ya da değiştirmek için yazılan komut`,`Bir HTTP durum kodu`,`Bir CSS kuralı`,`Bir sunucu türü`],e:`Arşivciye verilen net talimattır.`},
{t:`Sorgudaki "ORDER BY tutar DESC" ne yapar?`,o:[`Sonuçları tutara göre büyükten küçüğe sıralar`,`Tutar kolonunu siler`,`Sadece ilk satırı getirir`,`Tutarı ikiyle çarpar`],e:`DESC azalan, ASC artan sıralama demektir.`},
{t:`Ekranda "Ödeme başarılı" görüldükten sonra kaydın veritabanına doğru yazıldığını nasıl doğrularsın?`,o:[`İlgili tabloya sorgu atıp kaydı kontrol ederek`,`Ekranı yenileyerek`,`Tarayıcıyı kapatıp açarak`,`DNS önbelleğini temizleyerek`],e:`Ekrandaki mesaj iddiadır; veritabanındaki kayıt kanıttır.`}
]},
{no:94,tr:`CRUD`,en:`Create, Read, Update, Delete`,
def:`CRUD, bir veri üzerinde yapılabilecek dört temel işlemin baş harfleridir: Create (oluştur), Read (oku), Update (güncelle), Delete (sil).`,
an:`Telefon rehberi: yeni kişi eklersin (Create), kişiye bakarsın (Read), numarasını değiştirirsin (Update), kişiyi silersin (Delete). Uygulamaların çoğu bu dört işlemin farklı kombinasyonudur.`,
fi:`CRUD'un SQL ve HTTP karşılıkları:`,
code:[`İşlem      SQL       HTTP`,
`Create     INSERT    POST`,
`Read       SELECT    GET`,
`Update     UPDATE    PUT / PATCH`,
`Delete     DELETE    DELETE`],
note:`Bir özelliği test ederken dört işlemi sırayla denemek iyi bir başlangıçtır: oluştur, oku, güncelle, tekrar oku, sil, silindiğini doğrula.`,
qs:[
{t:`CRUD'daki "U" neyi ifade eder?`,o:[`Update (güncelle)`,`Upload (yükle)`,`User (kullanıcı)`,`Undo (geri al)`],e:`Create, Read, Update, Delete.`},
{t:`CRUD'daki Read işleminin HTTP karşılığı hangisidir?`,o:[`GET`,`POST`,`DELETE`,`PATCH`],e:`Okumak GET ile yapılır; veriyi değiştirmez.`},
{t:`Rehber benzetmesinde "kişiyi rehberden silmek" hangi işlemdir?`,o:[`Delete`,`Create`,`Read`,`Update`],e:`Kaydı kaldırmak Delete'tir.`}
]},
{no:95,tr:`Join`,en:`Join`,
def:`Join, iki ya da daha fazla tablodaki ilişkili satırları ortak bir kolon üzerinden birleştirip tek bir sonuç olarak getiren SQL işlemidir.`,
an:`İki ayrı listeyi TC numarasından eşleştirmek: bir listede isimler, diğerinde faturalar var; ortak numara üzerinden yan yana koyup "kimin faturası ne kadar" listesini çıkarırsın.`,
fi:`Müşteri adıyla faturayı birlikte getirmek:`,
code:[`SELECT m.ad, f.donem, f.tutar`,
`FROM musteri m`,
`INNER JOIN fatura f ON f.musteri_no = m.musteri_no`,
`WHERE f.durum = 'ODENMEDI';`,
``,
`// INNER JOIN: sadece iki tarafta da eşleşenler`,
`// LEFT JOIN:  soldaki tüm müşteriler, faturası olmasa bile`],
note:`INNER JOIN eşleşmeyen satırları dışarıda bırakır; "faturası olmayan müşteriler de görünsün" deniyorsa LEFT JOIN gerekir. Yanlış join, ekranda eksik ya da tekrarlanan satırların en sık sebebidir.`,
qs:[
{t:`Join ne yapar?`,o:[`İlişkili tabloları ortak bir kolon üzerinden birleştirir`,`Tabloyu siler`,`Veritabanını yedekler`,`Kolonun veri tipini değiştirir`],e:`İki listeyi ortak numaradan eşleştirmek gibidir.`},
{t:`Faturası olmayan müşterilerin de listede görünmesi isteniyorsa hangi join kullanılır?`,o:[`LEFT JOIN`,`INNER JOIN`,`Hiçbiri, mümkün değildir`,`DELETE JOIN`],e:`LEFT JOIN soldaki tablonun tüm satırlarını, eşleşme olmasa da getirir.`},
{t:`Bu sorguda iki tablo hangi kolon üzerinden eşleşiyor?`,o:[`musteri_no`,`ad`,`tutar`,`donem`],e:`ON f.musteri_no = m.musteri_no ifadesi eşleşme kolonunu belirtir.`}
]}
]);

add(9,`Veri ve veritabanı`,[
{no:96,tr:`Index`,en:`Database Index`,
def:`Index, bir tablodaki belirli kolonlar üzerinde oluşturulan ve aramaları tüm tabloyu taramadan hızlıca yapmayı sağlayan yardımcı veri yapısıdır.`,
an:`Kitabın sonundaki dizin: "Fatura" kelimesini bulmak için 800 sayfayı tek tek çevirmezsin; dizine bakar, "s. 214" yazanı açarsın.`,
fi:`Index'li ve index'siz arama:`,
code:[`// Index yok: milyonlarca satır tek tek taranır (full table scan)`,
`SELECT * FROM fatura WHERE musteri_no = 1002345;     // yavaş`,
``,
`CREATE INDEX idx_fatura_musteri ON fatura (musteri_no);`,
``,
`// Index var: doğrudan ilgili satırlara gidilir`,
`SELECT * FROM fatura WHERE musteri_no = 1002345;     // hızlı`],
note:`Index okumayı hızlandırır ama her ekleme ve güncellemede index de güncellendiği için yazmayı biraz yavaşlatır. Ekranlardaki yavaş aramaların sebebi çoğu zaman eksik index'tir.`,
qs:[
{t:`Index ne işe yarar?`,o:[`Aramaları tüm tabloyu taramadan hızlandırır`,`Tabloyu şifreler`,`Satırları siler`,`Veritabanını yedekler`],e:`Dizin gibi: doğrudan doğru sayfaya gidersin.`},
{t:`Kitap benzetmesinde index neye karşılık gelir?`,o:[`Kitabın sonundaki dizin`,`Kitabın kapağı`,`Kitabın yazarı`,`Kitabın fiyatı`],e:`Aranan şeyin nerede olduğunu gösteren yardımcı listedir.`},
{t:`Index'in bir bedeli nedir?`,o:[`Ekleme ve güncelleme işlemlerini biraz yavaşlatması`,`Okumayı imkânsız hale getirmesi`,`Verileri silmesi`,`Sorguların yanlış sonuç döndürmesi`],e:`Kitaba yeni sayfa eklenince dizinin de güncellenmesi gerekir.`}
]},
{no:97,tr:`Transaction`,en:`Transaction · Commit / Rollback`,
def:`Transaction, birden fazla veritabanı işleminin tek bir bütün olarak ele alınmasıdır; hepsi başarılıysa commit ile kalıcı olur, biri bile başarısızsa rollback ile hepsi geri alınır.`,
an:`Para havalesi: bir hesaptan düşmek ve diğerine eklemek tek iş sayılır. Düşüldü ama eklenemediyse, düşülen para geri konur. Ya hep ya hiç.`,
fi:`Havalenin tek parça olarak işlenmesi:`,
code:[`BEGIN`,
`TRY`,
`    UPDATE hesap SET bakiye = bakiye - 250 WHERE id = 'A';`,
`    UPDATE hesap SET bakiye = bakiye + 250 WHERE id = 'B';`,
`    INSERT INTO hareket (kaynak, hedef, tutar) VALUES ('A', 'B', 250);`,
`    COMMIT                         // hepsi kalıcı`,
`CATCH hata`,
`    ROLLBACK                       // hiçbiri olmamış gibi`,
`END TRY`],
note:`Commit edilmemiş veri başka oturumlardan görünmez; SQL aracında UPDATE yapıp commit etmeyi unutmak "uygulamada değişiklik görünmüyor" şikâyetinin klasik sebebidir. Bekleyen değişiklik tabloyu kilitleyip diğer işlemleri de bekletebilir.`,
qs:[
{t:`Transaction'ın temel kuralı nedir?`,o:[`Ya hepsi başarılı olur ya da hiçbiri uygulanmaz`,`Her işlem birbirinden bağımsızdır`,`Sadece ilk işlem kaydedilir`,`İşlemler rastgele sırayla yapılır`],e:`Havale yarım kalamaz: ya para karşıya geçer ya da hiç çıkmaz.`},
{t:`Transaction içindeki bir adım hata verirse ne yapılır?`,o:[`Rollback ile tüm adımlar geri alınır`,`Commit ile hatalı adım da kaydedilir`,`Veritabanı silinir`,`Sadece hatalı adım atlanır`],e:`Bir adım bile başarısızsa bütün iş geri sarılır.`},
{t:`SQL aracında UPDATE yaptın ama uygulama değişikliği görmüyor. Olası sebep nedir?`,o:[`Değişiklik commit edilmemiş`,`Tarayıcı eski`,`CSS hatalı`,`DNS kaydı yanlış`],e:`Commit edilmeyen değişikliği sadece senin oturumun görür.`}
]},
{no:98,tr:`Stored Procedure`,en:`Stored Procedure · PL/SQL`,
def:`Stored procedure, veritabanının içinde saklanan, adıyla çağrılabilen ve birden fazla SQL işlemini mantıkla birlikte çalıştıran hazır programdır; Oracle'da bu programlar PL/SQL ile yazılır.`,
an:`Arşivde duran hazır prosedür klasörü: "Ay sonu kapanışı" dediğinde arşivci klasördeki adımları sırayla uygular; her seferinde adımları tek tek anlatmazsın.`,
fi:`Bir PL/SQL prosedürü ve çağrılması:`,
code:[`CREATE PROCEDURE gecikme_faizi_uygula(p_donem IN VARCHAR2) AS`,
`BEGIN`,
`    FOR f IN (SELECT * FROM fatura`,
`              WHERE donem = p_donem AND durum = 'ODENMEDI') LOOP`,
`        UPDATE fatura SET faiz = f.tutar * 0.02 WHERE id = f.id;`,
`    END LOOP;`,
`    COMMIT;`,
`END;`,
``,
`// Çağrı`,
`CALL gecikme_faizi_uygula('2026-10');`],
note:`İş mantığının bir kısmı uygulamada değil veritabanında olabilir; bir hatanın kaynağı bazen Java kodu değil bir prosedürdür. Test verisi hazırlamak için de sık sık prosedür çağrılır.`,
qs:[
{t:`Stored procedure nedir?`,o:[`Veritabanında saklanan ve adıyla çağrılabilen hazır program`,`Bir web sayfası`,`Bir ağ cihazı`,`Bir CSS dosyası`],e:`Hazır prosedür klasörü gibi: adını söylersin, adımlar uygulanır.`},
{t:`Oracle'da stored procedure'ler hangi dille yazılır?`,o:[`PL/SQL`,`HTML`,`CSS`,`YAML`],e:`PL/SQL, SQL'e değişken, döngü ve koşul ekleyen Oracle dilidir.`},
{t:`Bir hesaplama hatası uygulama kodunda bulunamıyor. Başka nereye bakmak gerekebilir?`,o:[`Veritabanındaki stored procedure'lere`,`Tarayıcı geçmişine`,`Klavye ayarlarına`,`Ekran kartına`],e:`İş kuralının bir kısmı veritabanında yaşıyor olabilir.`}
]},
{no:99,tr:`NoSQL`,en:`NoSQL`,
def:`NoSQL, veriyi ilişkisel tablolar yerine doküman, anahtar-değer ya da grafik gibi daha esnek yapılarda saklayan veritabanı türlerinin genel adıdır.`,
an:`İlişkisel veritabanı herkesin aynı formu doldurduğu dosya dolabıdır. NoSQL ise her müşterinin kendi zarfına istediği belgeleri koyduğu arşivdir: biri iki sayfa, diğeri on sayfa olabilir.`,
fi:`Aynı müşteri, tek bir doküman olarak (MongoDB):`,
code:[`{`,
`  "_id": "1002345",`,
`  "ad": "Ayşe Yılmaz",`,
`  "hatlar": [`,
`    { "no": "5321112233", "paket": "Kurumsal 20" },`,
`    { "no": "5334445566", "paket": "Kurumsal 50" }`,
`  ]`,
`}`,
`// İlişkisel modelde bu veri en az iki tabloya bölünürdü`],
note:`MongoDB (doküman), Redis (anahtar-değer), Cassandra ve Elasticsearch bilinen NoSQL örnekleridir. Esnek ve kolay ölçeklenir; karşılığında ilişkisel veritabanlarının bazı tutarlılık garantilerinden vazgeçilebilir.`,
qs:[
{t:`NoSQL'in ilişkisel veritabanından temel farkı nedir?`,o:[`Veriyi tablolar yerine doküman, anahtar-değer gibi esnek yapılarda saklaması`,`Hiç veri saklamaması`,`Sadece SQL ile sorgulanabilmesi`,`Sadece frontend'de çalışması`],e:`Herkes aynı formu doldurmak zorunda değildir.`},
{t:`Hangisi bir NoSQL veritabanıdır?`,o:[`MongoDB`,`Oracle`,`PostgreSQL`,`MySQL`],e:`Diğer üçü ilişkisel (SQL) veritabanıdır.`},
{t:`Zarf benzetmesinde "her zarfta farklı sayıda belge olması" neyi anlatır?`,o:[`NoSQL'deki esnek, sabit olmayan veri yapısını`,`Primary key'i`,`Foreign key kısıtını`,`SQL injection'ı`],e:`Dokümanların hepsinin aynı alanlara sahip olması gerekmez.`}
]},
{no:100,tr:`Cache`,en:`Cache · Önbellek`,
def:`Cache, sık kullanılan verinin her seferinde asıl kaynaktan çekilmemesi için daha hızlı erişilen bir yerde geçici olarak tutulmasıdır.`,
an:`Sık kullandığın baharatları dolaptan değil ocağın yanındaki raftan alırsın. Hızlıdır; ama dolaptaki baharat değiştiyse raftaki eski kalabilir.`,
fi:`Cache'li veri okuma:`,
code:[`SET anahtar = "paketler:kurumsal"`,
`IF cache.var_mı(anahtar) THEN`,
`    RETURN cache.al(anahtar)                     // hızlı: cache hit`,
`ELSE`,
`    SET veri = CALL veritabanından_oku()         // yavaş: cache miss`,
`    CALL cache.koy(anahtar, veri, 600)           // 10 dakika tut`,
`    RETURN veri`,
`END IF`],
note:`Cache'in en bilinen yan etkisi bayat veridir: veritabanında güncellenen bilgi, cache süresi dolana kadar ekranda eski haliyle görünebilir. "Düzelttim ama hâlâ eskisi görünüyor" durumunda cache ilk şüphelidir.`,
qs:[
{t:`Cache'in amacı nedir?`,o:[`Sık kullanılan veriye daha hızlı erişmek için onu geçici olarak saklamak`,`Veriyi kalıcı olarak silmek`,`Kullanıcıyı doğrulamak`,`Kodu derlemek`],e:`Baharat rafı gibi: el altında, hızlı.`},
{t:`Veritabanında bir paket fiyatı güncellendi ama ekranda eski fiyat görünüyor. İlk şüpheli nedir?`,o:[`Cache'te tutulan bayat veri`,`Klavye ayarı`,`Firewall kuralı`,`CSS rengi`],e:`Raftaki eski baharat hâlâ kullanılıyor; cache süresi dolunca ya da temizlenince düzelir.`},
{t:`Aranan veri cache'te yoksa buna ne denir?`,o:[`Cache miss`,`Cache hit`,`Rollback`,`Deploy`],e:`Rafta yoksa dolaba gidilir; buna cache miss denir.`}
]}
]);

add(10,`Mimari ve entegrasyon`,[
{no:101,tr:`Senkron / Asenkron`,en:`Synchronous / Asynchronous`,
def:`Senkron iletişimde çağıran taraf cevap gelene kadar bekler; asenkron iletişimde ise isteği bırakıp işine devam eder ve sonucu daha sonra alır.`,
an:`Senkron telefon görüşmesidir: karşı taraf cevap verene kadar hatta beklersin. Asenkron WhatsApp mesajıdır: yazarsın, işine dönersin, cevap gelince bakarsın.`,
fi:`İki yaklaşımla fatura PDF'i üretmek:`,
code:[`// Senkron: kullanıcı bekler`,
`SET pdf = CALL pdf_üret(fatura)         // 8 saniye boyunca ekran kilitli`,
`SHOW pdf`,
``,
`// Asenkron: kullanıcı beklemez`,
`SEND pdf_üret_isteği TO kuyruk`,
`SHOW "PDF hazırlanıyor, hazır olunca bildirim gelecek"`,
`ON pdf_hazır DO`,
`    SEND bildirim TO kullanıcı`,
`END`],
note:`Kısa ve sonucu hemen gereken işler (bakiye sorgulama) senkron, uzun süren ya da sonucu beklenmeyen işler (toplu SMS, rapor üretimi) asenkron yapılır. Asenkron akışlarda test, sonucun gelmesini beklemeyi de içerir.`,
qs:[
{t:`Senkron iletişimin özelliği nedir?`,o:[`Çağıran taraf cevap gelene kadar bekler`,`Çağıran taraf cevabı hiç beklemez`,`Cevap her zaman e-postayla gelir`,`İstek hiç gönderilmez`],e:`Telefonda hatta beklemek gibi.`},
{t:`Telefon ve WhatsApp benzetmesinde WhatsApp neye karşılık gelir?`,o:[`Asenkron`,`Senkron`,`Timeout`,`Firewall`],e:`Mesajı bırakıp işine dönersin; cevap sonra gelir.`},
{t:`50.000 müşteriye kampanya SMS'i gönderilecek. Hangi yaklaşım daha uygundur?`,o:[`Asenkron`,`Senkron`,`Hiçbiri`,`Sadece frontend'de yapmak`],e:`Kimse binlerce SMS'in bitmesini ekranda beklememeli; iş arka planda yürür.`}
]},
{no:102,tr:`Message Queue`,en:`Message Queue · Kafka, JMS`,
def:`Message queue, sistemlerin birbirine doğrudan değil, mesajları bir kuyruğa bırakıp kuyruktan okuyarak asenkron haberleşmesini sağlayan ara katmandır.`,
an:`Postane kutusu: gönderen mektubu kutuya atar ve gider; alıcı müsait olduğunda kutuyu açıp sırayla okur. Alıcı tatildeyse mektuplar kaybolmaz, kutuda bekler.`,
fi:`Ödeme sonrası işlerin kuyrukla yürümesi:`,
code:[`// Üretici (producer): ödeme servisi`,
`SEND { "odemeId": "OD-778", "tutar": 249.90 } TO kuyruk "odeme-alindi"`,
``,
`// Tüketiciler (consumer): her biri kendi hızında okur`,
`ON mesaj FROM "odeme-alindi" DO`,
`    CALL fatura_kapat(mesaj)            // fatura servisi`,
`END`,
`ON mesaj FROM "odeme-alindi" DO`,
`    CALL sms_gönder(mesaj)              // bildirim servisi`,
`END`],
note:`Kafka, RabbitMQ, IBM MQ ve JMS tabanlı kuyruklar yaygın örneklerdir. Tüketici kapalıysa mesajlar birikir; kuyruktaki mesaj sayısının hiç azalmaması bir şeyin takıldığını gösterir.`,
qs:[
{t:`Message queue'nun sağladığı temel fayda nedir?`,o:[`Sistemlerin birbirini beklemeden mesajları kuyruk üzerinden iletmesi`,`Veritabanını şifrelemesi`,`Sayfayı responsive yapması`,`Alan adını IP'ye çevirmesi`],e:`Postane kutusu gibi: gönderen ve alıcı aynı anda müsait olmak zorunda değildir.`},
{t:`Mesajı kuyruğa bırakan tarafa ne denir?`,o:[`Producer (üretici)`,`Consumer (tüketici)`,`Gateway`,`Load balancer`],e:`Üreten producer, okuyan consumer'dır.`},
{t:`Bildirim servisi bir saat kapalı kaldı. Kuyruktaki mesajlara ne olur?`,o:[`Kuyrukta bekler, servis açılınca işlenir`,`Hepsi kalıcı olarak kaybolur`,`Ödeme servisi de durur`,`Mesajlar otomatik silinir`],e:`Mektuplar kutuda bekler; alıcı döndüğünde sırayla okunur.`}
]},
{no:103,tr:`Event-Driven Mimari`,en:`Event-Driven Architecture`,
def:`Event-driven mimari, sistemlerin birbirini doğrudan çağırmak yerine "şu oldu" şeklindeki olayları yayınladığı ve ilgilenen sistemlerin bu olaylara tepki verdiği tasarım yaklaşımıdır.`,
an:`Okul zili: zil çalar (olay), öğrenciler bahçeye çıkar, kantinci tezgâhı açar, öğretmenler çay koyar. Zil kimseye ne yapacağını söylemez; herkes kendi tepkisini bilir.`,
fi:`"Müşteri paket değiştirdi" olayı:`,
code:[`// Yayıncı sadece olayı duyurur`,
`CALL yayınla("PaketDegisti", { musteriNo: 1002345, yeni: "Kurumsal 50" })`,
``,
`// Dinleyiciler kendi işini yapar`,
`ON "PaketDegisti" DO CALL fatura_servisi.ücret_güncelle()`,
`ON "PaketDegisti" DO CALL bildirim_servisi.sms_gönder()`,
`ON "PaketDegisti" DO CALL raporlama.kayıt_ekle()`],
note:`Yeni bir sistem eklemek için yayıncıyı değiştirmeye gerek kalmaz; sadece yeni bir dinleyici eklenir. Bedeli: bir olayın kimleri tetiklediğini izlemek ve sıralama sorunlarını test etmek zorlaşır.`,
qs:[
{t:`Event-driven mimarinin temel fikri nedir?`,o:[`Sistemlerin olay yayınlaması ve ilgilenenlerin bu olaylara tepki vermesi`,`Tüm sistemlerin birbirini doğrudan çağırması`,`Tek bir büyük uygulama yazılması`,`Veritabanının kaldırılması`],e:`Zil çalar, herkes kendi işini bilir.`},
{t:`Okul zili benzetmesinde zil neye karşılık gelir?`,o:[`Olay (event)`,`Dinleyici`,`Veritabanı`,`Firewall`],e:`Zil "teneffüs başladı" olayının duyurusudur.`},
{t:`Paket değişikliğinden yeni bir sistemin de haberdar olması isteniyor. Ne yapılır?`,o:[`Yeni sistem olayı dinleyen bir tüketici olarak eklenir; yayıncı değişmez`,`Yayıncının kodu baştan yazılır`,`Tüm sistem kapatılıp açılır`,`Veritabanı silinir`],e:`Zile yeni bir dinleyici eklemek, zili değiştirmeyi gerektirmez.`}
]},
{no:104,tr:`ESB / Entegrasyon Katmanı`,en:`Enterprise Service Bus`,
def:`ESB, kurumdaki çok sayıda sistemin birbirine doğrudan değil ortak bir entegrasyon omurgası üzerinden bağlandığı; dönüşüm, yönlendirme ve protokol çevirisinin bu omurgada yapıldığı mimaridir.`,
an:`Şehrin ana otobüs terminali: her şehirden her şehre ayrı yol yapmak yerine herkes terminale gelir; terminal yolcuyu doğru otobüse aktarır. Yeni bir şehir eklemek için tek yol yeter.`,
fi:`Entegrasyon katmanında bir istek:`,
code:[`RECEIVE rest_istek FROM backend           // JSON, REST`,
`SET soap = CALL dönüştür(rest_istek)      // mapping: JSON'dan XML'e`,
`SEND soap TO crm                          // SOAP, eski sistem`,
`RECEIVE soap_cevap FROM crm`,
`SET json = CALL dönüştür(soap_cevap)      // mapping: XML'den JSON'a`,
`LOG istek, cevap, süre                    // merkezi izleme`,
`RETURN json`],
note:`TIBCO BusinessWorks, MuleSoft ve IBM App Connect bu katmanda kullanılan ürünlerdir. Sistemleri birbirinden bağımsızlaştırır; ama omurga yavaşlarsa ya da bir mapping hatalıysa birçok akış birden etkilenir.`,
qs:[
{t:`ESB'nin temel amacı nedir?`,o:[`Sistemleri ortak bir omurga üzerinden bağlayıp dönüşüm ve yönlendirmeyi merkezde yapmak`,`Kullanıcı arayüzünü çizmek`,`Veritabanını yedeklemek`,`Kodu derlemek`],e:`Terminal gibi: herkes merkeze gelir, merkez doğru yere aktarır.`},
{t:`Otobüs terminali benzetmesinde terminal neye karşılık gelir?`,o:[`ESB / entegrasyon katmanı`,`Veritabanı`,`Tarayıcı`,`Firewall`],e:`Sistemlerin buluşup birbirine aktarıldığı merkez ESB'dir.`},
{t:`ESB'deki bir mapping hatası neden geniş etki yaratabilir?`,o:[`Birçok sistemin akışı aynı omurgadan geçtiği için`,`ESB sadece tek bir sisteme hizmet verdiği için`,`Mapping hataları hiçbir zaman etki etmediği için`,`ESB frontend'de çalıştığı için`],e:`Terminalde bir aksaklık, oradan geçen tüm yolcuları etkiler.`}
]}
]);

add(10,`Mimari ve entegrasyon`,[
{no:105,tr:`Batch Job`,en:`Batch Job`,
def:`Batch job, çok sayıda kaydı kullanıcı etkileşimi olmadan, genellikle belirli bir zamanda toplu halde işleyen arka plan işidir.`,
an:`Gece çalışan bulaşık makinesi: gün boyu biriken bulaşıklar tek tek yıkanmaz; gece hepsi birden makineye konur ve sabah temiz çıkar.`,
fi:`Her gece 02:00'de çalışan fatura kesim işi:`,
code:[`ON zamanlama "0 2 * * *" DO              // cron: her gün 02:00`,
`    LOAD müşteriler FROM veritabanı WHERE dönem_sonu = bugün`,
`    FOR EACH müşteri IN müşteriler`,
`        TRY`,
`            CALL fatura_oluştur(müşteri)`,
`        CATCH hata`,
`            LOG müşteri.no, hata          // biri patlarsa diğerleri durmaz`,
`        END TRY`,
`    END FOR`,
`    SEND rapor TO operasyon_ekibi         // kaç başarılı, kaç hatalı`,
`END`],
note:`Batch job'ları test etmek için genelde zamanı beklemek yerine iş elle tetiklenir. Yarıda kalan bir job tekrar çalıştırıldığında aynı kayıtları iki kez işlememesi kritik bir kontroldür.`,
qs:[
{t:`Batch job nedir?`,o:[`Çok sayıda kaydı toplu halde, kullanıcı etkileşimi olmadan işleyen arka plan işi`,`Kullanıcının tek tıkla yaptığı işlem`,`Bir CSS animasyonu`,`Bir HTTP durum kodu`],e:`Bulaşık makinesi gibi: biriktirilir, toplu yıkanır.`},
{t:`"0 2 * * *" ifadesi bu job için ne anlatır?`,o:[`Her gün saat 02:00'de çalışacağını`,`Her 2 dakikada bir çalışacağını`,`Sadece 2 Ocak'ta çalışacağını`,`Hiç çalışmayacağını`],e:`Cron sırası dakika, saat, gün, ay, haftanın günüdür: 0. dakika, 2. saat, her gün.`},
{t:`Yarıda kalan bir batch job yeniden çalıştırılırsa hangi risk kontrol edilmelidir?`,o:[`Aynı kayıtların iki kez işlenmesi`,`Ekran renginin değişmesi`,`Tarayıcının kapanması`,`DNS kaydının silinmesi`],e:`Yarısı kesilmiş faturalar yeniden kesilirse müşteri iki fatura alır.`}
]},
{no:106,tr:`Retry ve Idempotency`,en:`Retry and Idempotency`,
def:`Retry, başarısız olan bir isteğin belirli kurallarla tekrar denenmesidir; idempotency ise aynı isteğin bir ya da birden fazla kez gönderilmesinin sonucu değiştirmemesi, yani tekrarın zarar vermemesidir.`,
an:`Asansör düğmesi idempotent'tir: bir kere de bassan on kere de bassan asansör bir kere gelir. Para çekme düğmesi öyle değildir: her basış ayrı para çeker.`,
fi:`Güvenli tekrar deneme:`,
code:[`SET istek_id = "OD-REQ-5512"              // her ödeme isteğine tek kimlik`,
`SET deneme = 0`,
`WHILE deneme < 3`,
`    SET cevap = CALL ödeme_al(tutar, istek_id)`,
`    IF cevap.başarılı THEN RETURN cevap`,
`    SET deneme = deneme + 1`,
`    WAIT 2 ^ deneme                       // giderek artan bekleme (saniye)`,
`END WHILE`,
``,
`// Sunucu: aynı istek_id ikinci kez gelirse yeni ödeme açmaz`,
`IF daha_önce_işlendi(istek_id) THEN RETURN önceki_sonuç`],
note:`GET, PUT ve DELETE doğası gereği idempotent olmalıdır; POST değildir. Timeout sonrası retry yapılan ödemelerde idempotency yoksa çift tahsilat oluşur; bu, test edilmesi gereken en kritik senaryolardandır.`,
qs:[
{t:`Idempotency ne demektir?`,o:[`Aynı isteğin tekrar gönderilmesinin sonucu değiştirmemesi`,`İsteğin hiç gönderilememesi`,`İsteğin her seferinde farklı sonuç vermesi`,`İsteğin şifrelenmesi`],e:`Asansör düğmesi gibi: kaç kere basarsan bas, sonuç aynı.`},
{t:`Asansör ve para çekme benzetmesinde idempotent olmayan hangisidir?`,o:[`Para çekme düğmesi`,`Asansör düğmesi`,`İkisi de idempotenttir`,`İkisi de idempotent değildir`],e:`Her basış yeni bir para çekme işlemi başlatır.`},
{t:`Ödeme isteği timeout aldı ve sistem otomatik retry yaptı. Idempotency yoksa ne olabilir?`,o:[`Müşteriden iki kez tahsilat yapılabilir`,`Hiçbir şey olmaz`,`Ödeme kendiliğinden iptal edilir`,`Müşterinin şifresi değişir`],e:`İlk istek aslında işlenmiş olabilir; tekrar, ikinci bir ödeme yaratır.`}
]},
{no:107,tr:`Rate Limiting`,en:`Rate Limiting`,
def:`Rate limiting, bir istemcinin belirli bir sürede yapabileceği istek sayısını sınırlayarak sistemi aşırı yüke ve kötüye kullanıma karşı koruma yöntemidir.`,
an:`Otoyol gişesindeki şerit sayısı: aynı anda geçebilecek araç sayısı bellidir; fazlası sıraya girer ya da geri çevrilir. Böylece gişe tıkanmaz.`,
fi:`İstemci bazlı sınır:`,
code:[`SET kurallar = { "mobil-app": 100, "partner-x": 20 }    // dakikada istek`,
`SET sayaç = CALL dakikalık_sayaç(istemci)`,
`IF sayaç >= kurallar[istemci] THEN`,
`    RETURN 429 WITH header Retry-After = 60`,
`ELSE`,
`    CALL sayacı_artır(istemci)`,
`    CALL isteği_işle()`,
`END IF`],
note:`Genelde API Gateway üzerinde tanımlanır. Kaba kuvvet (brute force) şifre denemelerine karşı da kullanılır: aynı hesaba dakikada 5'ten fazla giriş denemesi engellenebilir.`,
qs:[
{t:`Rate limiting'in amacı nedir?`,o:[`Belirli sürede yapılabilecek istek sayısını sınırlayıp sistemi korumak`,`Sayfayı hızlandırmak için önbellek oluşturmak`,`Veritabanı tablolarını birleştirmek`,`Kodu derlemek`],e:`Gişe kapasitesi gibi: fazlası bekler ya da geri döner.`},
{t:`Limit aşıldığında genelde hangi HTTP kodu döner?`,o:[`429 Too Many Requests`,`200 OK`,`404 Not Found`,`301 Moved Permanently`],e:`429, "çok fazla istek, biraz bekle" demektir.`},
{t:`Bir hesaba dakikada yüzlerce şifre denemesi yapılmasını engellemek için hangisi kullanılır?`,o:[`Rate limiting`,`Cache`,`Join`,`Responsive tasarım`],e:`Deneme sayısı sınırlanınca kaba kuvvet saldırısı pratikte imkânsızlaşır.`}
]},
{no:108,tr:`Dependency`,en:`Dependency · Bağımlılık`,
def:`Dependency, bir yazılımın çalışabilmek için ihtiyaç duyduğu başka bir kütüphane, servis ya da sistemdir; o parça yoksa ya da bozuksa yazılım da düzgün çalışmaz.`,
an:`Bir yemeğin malzemeleri: tarif ne kadar iyi olursa olsun, un bayatsa ya da süt yoksa kek olmaz. Malzemeyi başkası üretir, sen kullanırsın.`,
fi:`İki tür bağımlılık:`,
code:[`// 1) Kod bağımlılığı (pom.xml)`,
`<dependency>`,
`  <artifactId>selenium-java</artifactId>`,
`  <version>4.21.0</version>`,
`</dependency>`,
``,
`// 2) Servis bağımlılığı (çalışma anında)`,
`CALL fatura_ekranı_aç()      // ihtiyaç: müşteri ve fatura servisi, CRM`,
`IF crm_erişilemiyor THEN SHOW "Fatura bilgisi alınamadı"`],
note:`"Bizim servis çalışıyor ama ekran açılmıyor" durumunun sebebi çoğu zaman bağımlı olunan başka bir sistemin kapalı olmasıdır. Kütüphane sürümlerinin uyumsuzluğu da build hatalarının sık sebebidir.`,
qs:[
{t:`Dependency nedir?`,o:[`Bir yazılımın çalışmak için ihtiyaç duyduğu başka kütüphane, servis ya da sistem`,`Bir HTTP metodu`,`Bir CSS özelliği`,`Bir veritabanı satırı`],e:`Kekin malzemeleri gibi: biri eksikse sonuç çıkmaz.`},
{t:`Kendi servisin ayakta ama ekran hata veriyor. Olası sebep nedir?`,o:[`Bağımlı olunan başka bir servis ya da sistem kapalı`,`Ekranın rengi yanlış`,`Klavye bozuk`,`Kullanıcı çok hızlı tıklıyor`],e:`Zincirin herhangi bir halkası koparsa uçtaki ekran da çalışmaz.`},
{t:`Maven kullanan Java projelerinde kütüphane bağımlılıkları hangi dosyada tanımlanır?`,o:[`pom.xml`,`index.html`,`style.css`,`README.md`],e:`pom.xml, projenin hangi kütüphanelerin hangi sürümlerine ihtiyaç duyduğunu listeler.`}
]}
]);

add(11,`Geliştirme süreci`,[
{no:109,tr:`Versiyon Kontrol`,en:`Version Control · Git`,
def:`Versiyon kontrol, kodda yapılan her değişikliği kim, ne zaman, neden yaptı bilgisiyle kaydeden ve istenen eski hale dönmeyi sağlayan sistemdir; Git bunun en yaygın aracıdır.`,
an:`Oyundaki kayıt noktaları: her önemli adımda kayıt alırsın; işler kötü giderse son iyi kayda dönersin. Üstelik herkes kendi kaydıyla oynayıp sonra birleştirebilir.`,
fi:`Bir değişikliğin Git'teki yolculuğu:`,
code:[`git clone https://github.com/ekip/fatura-api.git   // projeyi indir`,
`git checkout -b feature/PRJ-1234-pdf               // yeni dal aç`,
`// ... kod değişikliği ...`,
`git add .`,
`git commit -m "Fatura PDF indirme eklendi"         // kayıt noktası`,
`git push origin feature/PRJ-1234-pdf               // sunucuya gönder`,
`git log                                            // kim, ne, ne zaman`],
note:`GitHub, GitLab ve Bitbucket, Git depolarını barındıran platformlardır. Bir hatanın hangi değişiklikle geldiğini bulmak için commit geçmişi ve "git blame" kullanılır.`,
qs:[
{t:`Versiyon kontrolün temel faydası nedir?`,o:[`Değişiklikleri geçmişiyle kaydedip gerektiğinde eski hale dönebilmek`,`Kodu otomatik test etmek`,`Sunucuyu hızlandırmak`,`Veritabanını şifrelemek`],e:`Kayıt noktaları gibi: her şey izlenir ve geri alınabilir.`},
{t:`Oyun benzetmesinde kayıt noktası Git'te neye karşılık gelir?`,o:[`Commit`,`Branch`,`Merge conflict`,`Repository`],e:`Her commit, projenin o anki halinin kaydıdır.`},
{t:`Hangisi bir Git barındırma platformudur?`,o:[`GitHub`,`Jenkins`,`Kibana`,`Postman`],e:`Jenkins CI/CD, Kibana log görüntüleme, Postman API test aracıdır.`}
]},
{no:110,tr:`Repository`,en:`Repository`,
def:`Repository (repo), bir projenin tüm dosyalarının ve bu dosyaların değişiklik geçmişinin birlikte saklandığı depodur.`,
an:`Projenin arşiv klasörü: içinde sadece bugünkü dosyalar değil, her dosyanın tüm eski halleri ve kimin neyi değiştirdiği de durur.`,
fi:`Tipik bir repo'nun içi:`,
code:[`fatura-api/                  // repository`,
`├── src/                     // kaynak kod`,
`├── src/test/                // test kodları`,
`├── pom.xml                  // bağımlılıklar`,
`├── Jenkinsfile              // CI/CD tarifi`,
`├── README.md                // projeyi anlatan doküman`,
`└── .git/                    // tüm değişiklik geçmişi (gizli klasör)`],
note:`Uzak repo (remote) GitHub gibi bir sunucuda, yerel repo kendi bilgisayarında durur; clone, push ve pull ikisini senkronize eder. Test otomasyon kodları da genelde kendi repo'sunda tutulur.`,
qs:[
{t:`Repository neyi saklar?`,o:[`Projenin dosyalarını ve değişiklik geçmişini`,`Sadece kullanıcı şifrelerini`,`Sadece canlı ortam loglarını`,`Sadece ekran görüntülerini`],e:`Arşiv klasörü gibi: bugünkü hal ve tüm geçmiş birlikte.`},
{t:`Uzak repodaki projeyi ilk kez kendi bilgisayarına indirmek için hangi komut kullanılır?`,o:[`git clone`,`git merge`,`git commit`,`git log`],e:`clone, repo'nun tamamını geçmişiyle birlikte kopyalar.`},
{t:`Repo içindeki .git klasörü ne tutar?`,o:[`Tüm değişiklik geçmişini`,`Sadece CSS dosyalarını`,`Veritabanı yedeğini`,`Kullanıcı şifrelerini`],e:`Git'in kayıt noktaları ve dalları bu gizli klasörde saklanır.`}
]},
{no:111,tr:`Branch`,en:`Branch`,
def:`Branch (dal), ana koddan ayrılıp bağımsız olarak geliştirme yapılabilen paralel bir kod kopyasıdır; iş bitince ana dala geri birleştirilir.`,
an:`Ana yoldan ayrılan servis yolu: ana yoldaki trafiği (çalışan kodu) etkilemeden kendi yolunda çalışırsın, işin bitince ana yola geri bağlanırsın.`,
fi:`Dallarla çalışma:`,
code:[`main                                 // canlıya çıkan kararlı kod`,
` ├── develop                         // birleştirilip test edilen kod`,
` │    ├── feature/PRJ-1234-pdf       // yeni özellik`,
` │    └── feature/PRJ-1240-filtre    // başka bir özellik`,
` └── hotfix/PRJ-1301-tutar           // canlıdaki acil hata düzeltmesi`],
note:`Dal isimlerinde genelde Jira kaydının numarası bulunur; böylece hangi değişikliğin hangi işle ilgili olduğu izlenir. Test ederken hangi dalın hangi ortama deploy edildiğini bilmek önemlidir.`,
qs:[
{t:`Branch ne sağlar?`,o:[`Ana kodu etkilemeden bağımsız geliştirme yapmayı`,`Kodu silmeyi`,`Veritabanını yedeklemeyi`,`Sunucuyu yeniden başlatmayı`],e:`Servis yolu gibi: ana trafik akmaya devam eder.`},
{t:`Canlıdaki acil bir hatayı düzeltmek için açılan dala genelde ne denir?`,o:[`hotfix`,`feature`,`develop`,`release-notes`],e:`hotfix, canlıdaki sorunu hızla düzeltmek için açılan daldır.`},
{t:`Servis yolu benzetmesinde ana yol neye karşılık gelir?`,o:[`Ana dal (main)`,`Feature dalı`,`Commit mesajı`,`Merge conflict`],e:`Canlıya çıkan kararlı kod ana yoldur.`}
]},
{no:112,tr:`Commit / Push / Pull`,en:`Commit / Push / Pull`,
def:`Commit yerel repoda bir kayıt noktası oluşturur; push bu kayıtları uzak repoya gönderir; pull ise uzak repodaki yeni kayıtları yerel repoya çeker.`,
an:`Commit fotoğraf çekip telefonuna kaydetmektir; push fotoğrafları ortak buluta yüklemek; pull ise başkalarının buluta yüklediklerini kendi telefonuna indirmektir.`,
fi:`Günlük döngü:`,
code:[`git pull                                    // önce başkalarının işini al`,
`// ... kendi değişikliğini yap ...`,
`git add LoginTest.java`,
`git commit -m "Hatalı şifre senaryosu eklendi"   // yerel kayıt`,
`git push                                    // ortak repoya gönder`],
note:`Commit edilen ama push edilmeyen değişiklik sadece senin bilgisayarında durur; başkası göremez, pipeline da çalıştıramaz. İyi bir commit mesajı ne yapıldığını kısa ve net söyler.`,
qs:[
{t:`Commit ne yapar?`,o:[`Yerel repoda değişikliklerin kayıt noktasını oluşturur`,`Değişiklikleri uzak repoya gönderir`,`Uzak repodan değişiklik çeker`,`Dalı siler`],e:`Fotoğrafı telefona kaydetmek gibi: henüz kimseyle paylaşılmadı.`},
{t:`Uzak repodaki yeni değişiklikleri kendi bilgisayarına almak için hangi komut kullanılır?`,o:[`git pull`,`git push`,`git commit`,`git add`],e:`pull buluttan indirir, push buluta yükler.`},
{t:`Değişikliğini commit ettin ama push etmedin. Ekip arkadaşın değişikliği görebilir mi?`,o:[`Hayır, sadece senin bilgisayarında durur`,`Evet, commit anında herkese gider`,`Evet, ama sadece main dalında`,`Hayır, çünkü commit değişikliği siler`],e:`Buluta yüklenmeyen fotoğrafı kimse göremez.`}
]},
{no:113,tr:`Merge ve Merge Conflict`,en:`Merge and Merge Conflict`,
def:`Merge, bir daldaki değişikliklerin başka bir dalla birleştirilmesidir; merge conflict ise iki dalda aynı dosyanın aynı satırları farklı değiştirildiği için Git'in hangisini alacağına karar verememesidir.`,
an:`Aynı belgeyi iki kişinin ayrı ayrı düzenlemesi: biri ikinci paragrafı, diğeri beşinci paragrafı değiştirdiyse birleştirmek kolaydır. İkisi de aynı cümleyi farklı yazdıysa birinin oturup karar vermesi gerekir.`,
fi:`Bir çakışmanın görünümü:`,
code:[`git merge feature/PRJ-1234-pdf`,
`// CONFLICT (content): Merge conflict in FaturaService.java`,
``,
`<<<<<<< HEAD`,
`SET kdv_orani = 0.18`,
`=======`,
`SET kdv_orani = 0.20`,
`>>>>>>> feature/PRJ-1234-pdf`,
``,
`// Çözüm: doğru satır seçilir, işaretler silinir, tekrar commit edilir`],
note:`Conflict bir hata değil, bir karar anıdır. Yanlış çözülen conflict bir özelliğin kaybolmasına ya da eski bir hatanın geri gelmesine yol açabilir; merge sonrası regresyon testi bu yüzden önemlidir.`,
qs:[
{t:`Merge conflict ne zaman oluşur?`,o:[`İki dalda aynı satırlar farklı şekilde değiştirildiğinde`,`Her merge işleminde`,`Sadece bir dosya silindiğinde`,`İnternet bağlantısı koptuğunda`],e:`Aynı cümle iki farklı şekilde yazıldıysa hangisinin kalacağına insan karar verir.`},
{t:`Conflict çıktığında Git ne yapar?`,o:[`Çakışan kısımları işaretleyip kararı geliştiriciye bırakır`,`Değişikliklerden birini rastgele seçer`,`Tüm repoyu siler`,`Hatayı görmezden gelir`],e:`<<<<<<<, ======= ve >>>>>>> işaretleri iki versiyonu yan yana gösterir.`},
{t:`Merge sonrası neden regresyon testi önemlidir?`,o:[`Yanlış çözülen conflict eski hataları geri getirebilir ya da özellikleri kaybettirebilir`,`Merge her zaman veritabanını değiştirir`,`Merge sonrası CSS dosyaları silinir`,`Sadece formalite olduğu için`],e:`Birleştirme sırasında yanlış satırın seçilmesi, çalışan bir şeyi bozabilir.`}
]},
{no:114,tr:`Pull Request ve Code Review`,en:`Pull Request and Code Review`,
def:`Pull request (PR), bir daldaki değişikliklerin ana dala birleştirilmeden önce ekibin incelemesine sunulmasıdır; code review ise bu değişikliklerin başka geliştiriciler tarafından okunup değerlendirilmesidir.`,
an:`Yayına gitmeden önce editör kontrolü: yazar metni teslim eder, editör okur, düzeltme ister, onay verince metin basılır.`,
fi:`Bir PR'ın yaşam döngüsü:`,
code:[`CALL pr_aç("feature/PRJ-1234-pdf" TO "develop")`,
`RUN pipeline                              // otomatik build ve testler`,
`IF testler_başarısız THEN SHOW "PR birleştirilemez"`,
`FOR EACH reviewer IN ekip`,
`    CALL kodu_incele()                    // yorum, öneri, soru`,
`END FOR`,
`IF onay_sayısı >= 2 AND testler_geçti THEN`,
`    CALL merge()`,
`END IF`],
note:`PR açıklamasına ilgili Jira kaydının bağlantısı ve nasıl test edileceği yazılırsa hem review hem test hızlanır. Kod incelemesi, hataları test aşamasına gelmeden yakalamanın en ucuz yollarından biridir.`,
qs:[
{t:`Pull request nedir?`,o:[`Değişikliklerin ana dala birleştirilmeden önce incelemeye sunulması`,`Uzak repodan kod çekme komutu`,`Bir veritabanı sorgusu`,`Bir HTTP metodu`],e:`Adı "pull" içerse de git pull komutuyla aynı şey değildir.`},
{t:`Editör benzetmesinde editörün yaptığı iş neye karşılık gelir?`,o:[`Code review`,`Deploy`,`Build`,`Rollback`],e:`Başka birinin gözüyle okumak, yazarın kaçırdığını yakalar.`},
{t:`PR açıldığında pipeline'daki testler başarısız oldu. Doğru davranış nedir?`,o:[`PR, testler düzelene kadar birleştirilmez`,`PR hemen birleştirilir`,`Başarısız testler silinir`,`Pipeline kapatılır`],e:`Kırmızı testle birleştirmek, hatayı bilerek ana dala taşımaktır.`}
]}
]);

add(11,`Geliştirme süreci`,[
{no:115,tr:`Build`,en:`Build`,
def:`Build, kaynak kodun derlenip bağımlılıklarıyla birlikte paketlenerek çalıştırılabilir bir uygulama dosyasına dönüştürülmesi sürecidir.`,
an:`Hamuru fırına verip ekmek çıkarmak: tarif (kaynak kod) ve malzemeler (bağımlılıklar) hazır; fırından çıkan ekmek (paket) artık dağıtılabilir.`,
fi:`Bir Java projesinin build adımları:`,
code:[`RUN "mvn clean package"`,
`    // 1) Bağımlılıkları indir`,
`    // 2) Kodu derle (compile)`,
`    // 3) Unit testleri çalıştır`,
`    // 4) Paketle: fatura-api-1.4.2.jar`,
`IF herhangi_bir_adım_başarısız THEN`,
`    SHOW "BUILD FAILURE"          // paket oluşmaz, deploy yapılamaz`,
`END IF`],
note:`"Build kırıldı" demek, kodun derlenemediği ya da testlerin geçmediği anlamına gelir. Build çıktısına artifact denir; bir sonraki adımda bu artifact deploy edilir.`,
qs:[
{t:`Build ne yapar?`,o:[`Kaynak kodu derleyip çalıştırılabilir bir pakete dönüştürür`,`Kodu canlı ortama yükler`,`Veritabanını yedekler`,`Kullanıcıları doğrular`],e:`Hamurdan ekmek çıkarmak gibi: tariften dağıtılabilir ürüne.`},
{t:`"BUILD FAILURE" görüldüğünde ne olur?`,o:[`Paket oluşmaz ve deploy yapılamaz`,`Uygulama yine canlıya çıkar`,`Sadece uyarı verilir`,`Veritabanı silinir`],e:`Fırından ekmek çıkmadıysa vitrine konacak bir şey yoktur.`},
{t:`Fırın benzetmesinde fırından çıkan ekmek neye karşılık gelir?`,o:[`Build çıktısı (artifact)`,`Kaynak kod`,`Bağımlılıklar`,`Veritabanı`],e:`Derlenmiş ve paketlenmiş uygulama dosyası artifact'tir.`}
]},
{no:116,tr:`Deploy`,en:`Deploy`,
def:`Deploy, build edilmiş uygulama paketinin bir ortama (test, UAT, canlı) yüklenip çalışır hale getirilmesidir.`,
an:`Fırından çıkan ekmeği dükkânın vitrinine koymak: ekmek hazırdı ama müşteri ancak vitrine konunca alabilir.`,
fi:`Bir ortama deploy:`,
code:[`SET paket = "fatura-api-1.4.2.jar"`,
`SET ortam = "TEST"`,
`CALL eski_versiyonu_durdur(ortam)`,
`CALL yeni_paketi_yükle(paket, ortam)`,
`CALL başlat(ortam)`,
`IF health_check(ortam) == "UP" THEN`,
`    SHOW "Deploy başarılı"`,
`ELSE`,
`    CALL rollback(ortam)                // eski versiyona dön`,
`END IF`],
note:`Deploy sonrası ilk iş, doğru versiyonun gerçekten yayında olduğunu kontrol etmektir. "Düzeltme deploy edildi ama hata devam ediyor" durumlarının bir kısmı yanlış ortam ya da eski versiyondur.`,
qs:[
{t:`Deploy nedir?`,o:[`Build edilmiş paketin bir ortama yüklenip çalışır hale getirilmesi`,`Kaynak kodun yazılması`,`Bir veritabanı sorgusu`,`Kodun derlenmesi`],e:`Ekmeği vitrine koymak: artık kullanılabilir.`},
{t:`Vitrin benzetmesinde "ekmeği vitrine koymak" neye karşılık gelir?`,o:[`Deploy`,`Build`,`Commit`,`Code review`],e:`Hazır paketin ortama çıkması deploy'dur.`},
{t:`Deploy edildiği söylenen düzeltme test ortamında görünmüyor. İlk ne kontrol edilir?`,o:[`Ortamdaki versiyonun gerçekten yeni versiyon olup olmadığı`,`Klavye dili`,`Ekran parlaklığı`,`Tarayıcı teması`],e:`Vitrinde hâlâ dünkü ekmek olabilir; önce doğru paketin yayında olduğundan emin olunur.`}
]},
{no:117,tr:`Release ve Versiyonlama`,en:`Release and Versioning`,
def:`Release, bir yazılımın belirli özellikleri içeren sürümünün kullanıma sunulmasıdır; versiyonlama ise bu sürümleri 2.4.1 gibi numaralarla anlamlı şekilde adlandırmaktır.`,
an:`Bir kitabın baskıları: 2. baskı yeni bölümler içerir, 2. baskının düzeltilmiş hali sadece yazım hatalarını giderir. Numaraya bakıp ne kadar değiştiğini anlarsın.`,
fi:`Semantik versiyonlama (MAJOR.MINOR.PATCH):`,
code:[`SET versiyon = "2.4.1"`,
`// 2 = MAJOR: geriye uyumsuz büyük değişiklik`,
`// 4 = MINOR: geriye uyumlu yeni özellik`,
`// 1 = PATCH: sadece hata düzeltmesi`,
``,
`IF yeni_özellik_eklendi THEN SET versiyon = "2.5.0"`,
`IF sadece_hata_düzeltildi THEN SET versiyon = "2.4.2"`,
`IF eski_istemcileri_bozan_değişiklik THEN SET versiyon = "3.0.0"`],
note:`Release notları sürümde neyin değiştiğini, hangi hataların kapandığını ve bilinen sorunları listeler. Bug kaydına hatanın görüldüğü versiyon numarasını yazmak takibi çok kolaylaştırır.`,
qs:[
{t:`2.4.1 sürümünde sadece bir hata düzeltilirse yeni versiyon ne olur?`,o:[`2.4.2`,`2.5.0`,`3.0.0`,`2.4.1`],e:`Sadece hata düzeltmesi PATCH numarasını artırır.`},
{t:`Semantik versiyonlamada MAJOR numaranın artması neyi anlatır?`,o:[`Geriye uyumsuz büyük bir değişikliği`,`Sadece yazım hatası düzeltmesini`,`Hiçbir değişiklik olmadığını`,`Sadece rengin değiştiğini`],e:`Eski istemcilerin bozulabileceği değişikliklerde ilk numara artar.`},
{t:`Bug kaydına neden versiyon numarası yazılır?`,o:[`Hatanın hangi sürümde görüldüğünü ve hangi sürümde düzeldiğini takip etmek için`,`Kaydı uzatmak için`,`Sadece Jira zorunlu tuttuğu için`,`Versiyon numarası bir şifre olduğu için`],e:`"Hangi baskıda hata vardı, hangisinde düzeldi" sorusunun cevabıdır.`}
]},
{no:118,tr:`Ortamlar`,en:`Environments · Dev / Test / UAT / Prod`,
def:`Ortamlar, yazılımın geliştirmeden canlıya kadar geçtiği birbirinden ayrı kopyalarıdır: Dev geliştirme, Test doğrulama, UAT iş biriminin kabul testi, Prod ise gerçek kullanıcıların kullandığı canlı ortamdır.`,
an:`Tiyatro prodüksiyonu: Dev mutfak çalışması, Test kostümsüz prova, UAT yapımcıların izlediği genel prova, Prod seyircili gala gecesi. Hata provalarda yakalanmalı, galada değil.`,
fi:`Bir değişikliğin ortamlardaki yolculuğu:`,
code:[`CALL deploy(TO dev)                               // geliştirici dener`,
`IF dev_testleri_geçti THEN CALL deploy(TO test)    // QA test eder`,
`IF test_onaylandı THEN CALL deploy(TO uat)         // iş birimi kabul testi`,
`IF uat_onaylandı THEN CALL deploy(TO prod)         // gerçek müşteriler`],
note:`Her ortamın kendi veritabanı, kendi config'i ve kendi adresi vardır; test verisi canlıda, canlı verisi testte olmaz. Bir hatanın hangi ortamda görüldüğü bug kaydının en temel bilgisidir.`,
qs:[
{t:`Prod ortamı nedir?`,o:[`Gerçek kullanıcıların kullandığı canlı ortam`,`Geliştiricinin kendi bilgisayarı`,`Sadece test verisi olan ortam`,`Bir tasarım aracı`],e:`Gala gecesi: seyirci gerçek, hata da gerçek etki yaratır.`},
{t:`UAT ortamında genelde kim test eder?`,o:[`İş birimi ya da son kullanıcı temsilcileri`,`Sadece veritabanı`,`Sadece derleyici`,`Hiç kimse`],e:`UAT, "bu gerçekten bizim istediğimiz şey mi?" sorusunun cevaplandığı yerdir.`},
{t:`Tiyatro benzetmesinde gala gecesi neye karşılık gelir?`,o:[`Prod`,`Dev`,`Test`,`UAT`],e:`Seyircinin, yani gerçek kullanıcıların olduğu tek ortam canlıdır.`}
]},
{no:119,tr:`Config ve Environment Variable`,en:`Configuration and Environment Variable`,
def:`Config, uygulamanın koda dokunmadan değiştirilebilen ayarlarıdır; environment variable ise bu ayarların ortama göre farklı değer alabilmesi için işletim sistemi seviyesinde tanımlanan değişkenlerdir.`,
an:`Aynı arabanın farklı sürücüleri: araba (kod) aynı, ama koltuk ve ayna ayarları (config) sürücüye göre değişir. Arabayı yeniden üretmeden ayarı değiştirirsin.`,
fi:`Aynı kod, farklı ortamlar:`,
code:[`// Kod her ortamda aynı`,
`SET crm_adresi  = CALL ortam_değişkeni("CRM_URL")`,
`SET zaman_aşımı = CALL ortam_değişkeni("CRM_TIMEOUT")`,
``,
`// TEST ortamı                 PROD ortamı`,
`// CRM_URL=crm-test.local      CRM_URL=crm.local`,
`// CRM_TIMEOUT=30              CRM_TIMEOUT=10`],
note:`Şifre ve API key gibi gizli bilgiler koda değil, ortam değişkenlerine ya da güvenli kasa (secret) sistemlerine konur. "Testte çalışıyor, UAT'de çalışmıyor" durumunun sık sebeplerinden biri farklı config değerleridir.`,
qs:[
{t:`Config'in temel amacı nedir?`,o:[`Ayarları koda dokunmadan değiştirebilmek`,`Kodu derlemek`,`Veritabanı tablosu oluşturmak`,`Ekranı çizmek`],e:`Araba aynı, ayar sürücüye göre.`},
{t:`Aynı kod test ortamında test CRM'ine, canlıda canlı CRM'ine nasıl bağlanır?`,o:[`Ortama göre farklı değer alan environment variable ile`,`Her ortam için ayrı kod yazarak`,`Kullanıcıya sorarak`,`Rastgele seçerek`],e:`Kod "CRM_URL'e bağlan" der; adresin ne olduğunu ortam söyler.`},
{t:`Bir özellik test ortamında çalışıyor, UAT'de çalışmıyor; kod aynı. Olası sebep nedir?`,o:[`Ortamların config değerleri farklı`,`Kullanıcının klavyesi bozuk`,`Kodun rengi farklı`,`Git silinmiş`],e:`Kod aynıysa fark büyük ihtimalle ayarlarda ya da veridedir.`}
]},
{no:120,tr:`Hotfix ve Rollback`,en:`Hotfix and Rollback`,
def:`Hotfix, canlıdaki acil bir hatayı normal sürüm takvimini beklemeden düzelten hızlı yamadır; rollback ise sorunlu bir deploy'un geri alınıp önceki çalışan versiyona dönülmesidir.`,
an:`Yangında iki seçenek: hızla müdahale edip yangını söndürmek (hotfix) ya da sistemi yangından önceki son güvenli haline geri almak (rollback).`,
fi:`Canlıda kritik hata görüldüğünde:`,
code:[`IF canlıda_kritik_hata THEN`,
`    IF hata_yeni_deploy_ile_geldi AND hızlı_düzeltme_yok THEN`,
`        CALL rollback(önceki_versiyon)        // önce durumu kurtar`,
`    ELSE`,
`        CALL dal_aç("hotfix/PRJ-1301")`,
`        CALL düzelt_test_et_deploy_et()       // dar ama odaklı test`,
`    END IF`,
`    CALL birleştir(hotfix TO develop)         // düzeltme ana koda da girer`,
`END IF`],
note:`Hotfix aceleyle yapıldığı için yeni hata riski taşır; kısa ama odaklı bir regresyon testi şarttır. Veritabanı değişikliği içeren deploy'larda rollback her zaman kolay değildir; geri dönüş planı deploy'dan önce yapılır.`,
qs:[
{t:`Hotfix nedir?`,o:[`Canlıdaki acil hatayı normal takvimi beklemeden düzelten hızlı yama`,`Yeni bir özellik`,`Bir veritabanı tablosu`,`Bir tasarım dosyası`],e:`Yangını yerinde söndürmek gibi.`},
{t:`Rollback nedir?`,o:[`Sorunlu deploy'u geri alıp önceki çalışan versiyona dönmek`,`Yeni versiyonu canlıya almak`,`Kodu derlemek`,`Testleri silmek`],e:`Son güvenli hale geri dönmektir.`},
{t:`Yeni deploy sonrası canlıda ödeme alınamıyor ve hızlı bir düzeltme yok. İlk mantıklı adım nedir?`,o:[`Önceki versiyona rollback yapmak`,`Hiçbir şey yapmamak`,`Sonraki sprinti beklemek`,`Veritabanını silmek`],e:`Önce müşteri etkisini durdurmak gerekir; kalıcı düzeltme sonra yapılır.`}
]}
]);

add(12,`DevOps ve altyapı`,[
{no:121,tr:`CI/CD`,en:`Continuous Integration / Continuous Delivery`,
def:`CI/CD, kod değişikliklerinin otomatik olarak birleştirilip build ve test edilmesini (CI), ardından otomatik olarak ortamlara yayınlanmasını (CD) sağlayan yaklaşımdır.`,
an:`Otomobil fabrikasının montaj hattı: her parça hatta girdiği anda kontrol edilir, monte edilir ve kalite kontrolden geçip otoparka çıkar. Elle taşıma yok, her adım otomatik ve hep aynı.`,
fi:`Bir push'un otomatik yolculuğu:`,
code:[`ON push TO "develop" DO`,
`    RUN build                      // CI: derle`,
`    RUN unit_testler               // CI: hızlı testler`,
`    IF başarısız THEN SEND "Build kırıldı" TO ekip`,
`    RUN deploy TO test             // CD: test ortamına çıkar`,
`    RUN otomasyon_testleri         // API ve UI testleri`,
`    SEND rapor TO ekip             // örn. Allure raporu`,
`END`],
note:`CI'ın amacı hatayı erken ve küçükken yakalamaktır; bu yüzden günde birçok kez küçük birleştirmeler yapılır. Otomasyon testleri bu hattın kalite kontrol istasyonudur.`,
qs:[
{t:`CI (Continuous Integration) neyi ifade eder?`,o:[`Değişikliklerin sık sık birleştirilip otomatik build ve test edilmesini`,`Kodun elle canlıya kopyalanmasını`,`Veritabanının yedeklenmesini`,`Tasarımların çizilmesini`],e:`Her parça hatta girer girmez kontrol edilir.`},
{t:`Montaj hattı benzetmesinde kalite kontrol istasyonu neye karşılık gelir?`,o:[`Otomatik testler`,`Kaynak kod`,`Veritabanı`,`DNS`],e:`Hattan geçen her değişiklik otomatik testlerle kontrol edilir.`},
{t:`CI/CD'nin en büyük faydası nedir?`,o:[`Hataları erken yakalayıp yayını hızlı ve tekrarlanabilir yapmak`,`Testleri tamamen gereksiz kılmak`,`Kodu daha uzun yazmak`,`Sunucu sayısını azaltmak`],e:`Aynı adımlar her seferinde aynı şekilde çalışır; insan hatası azalır.`}
]},
{no:122,tr:`Pipeline`,en:`Pipeline`,
def:`Pipeline, build, test ve deploy gibi adımların belirli bir sırayla otomatik çalıştırıldığı iş akışı tanımıdır; Jenkins'te genelde Jenkinsfile ile kod olarak yazılır.`,
an:`Bir yemek tarifinin otomatikleştirilmiş hali: malzemeyi hazırla, pişir, tadına bak, tabağa koy. Bir adımda sorun çıkarsa sonraki adımlara geçilmez.`,
fi:`Basitleştirilmiş bir Jenkinsfile:`,
code:[`pipeline {`,
`    stages {`,
`        stage('Build')  { steps { sh 'mvn clean package' } }`,
`        stage('Test')   { steps { sh 'mvn test' } }`,
`        stage('Deploy') { steps { sh './deploy.sh test' } }`,
`        stage('E2E')    { steps { sh 'mvn verify -Pkarate' } }`,
`    }`,
`    post { always { allure results: 'target/allure-results' } }`,
`}`],
note:`Pipeline'ın her adımı (stage) Jenkins arayüzünde yeşil ya da kırmızı görünür; kırmızı adımın logu hatanın sebebini söyler. Test otomasyonu pipeline'a bağlandığında her deploy sonrası testler kendiliğinden çalışır.`,
qs:[
{t:`Pipeline nedir?`,o:[`Build, test ve deploy adımlarının sırayla otomatik çalıştığı iş akışı`,`Bir veritabanı tablosu`,`Bir CSS dosyası`,`Bir HTTP durum kodu`],e:`Otomatik çalışan tarif: adım adım, sırayla.`},
{t:`Pipeline'da Test adımı kırmızı oldu. Deploy adımı ne olur?`,o:[`Çalışmaz; pipeline o adımda durur`,`Yine de çalışır`,`İki kez çalışır`,`Testleri siler`],e:`Tadı kötü olan yemek tabağa konmaz.`},
{t:`Jenkins'te pipeline genelde hangi dosyada tanımlanır?`,o:[`Jenkinsfile`,`pom.xml`,`index.html`,`README.md`],e:`Jenkinsfile, pipeline'ın adımlarını kod olarak repoda tutar.`}
]},
{no:123,tr:`Container`,en:`Container · Docker`,
def:`Container, bir uygulamayı ihtiyaç duyduğu tüm kütüphane ve ayarlarla birlikte paketleyip her ortamda aynı şekilde çalışmasını sağlayan hafif ve izole çalışma birimidir; Docker en yaygın container aracıdır.`,
an:`Gemi konteyneri: içinde ne olursa olsun, her limandaki her vinç onu aynı şekilde taşır. "Bende çalışıyordu" sorununu çözen de budur: uygulama kendi ortamıyla birlikte taşınır.`,
fi:`Dockerfile ile bir uygulamayı paketlemek:`,
code:[`FROM eclipse-temurin:21-jre            // temel: Java 21 çalışma ortamı`,
`COPY target/fatura-api.jar /app.jar    // uygulamayı kopyala`,
`ENV CRM_URL=crm-test.local             // ayar`,
`EXPOSE 8080                            // dinleyeceği port`,
`CMD ["java", "-jar", "/app.jar"]       // başlatma komutu`],
note:`Image tarif ve paketin kendisidir; container ise o image'dan çalışan örnektir. Aynı image test ve canlıda çalıştırıldığı için ortamlar arası farkın kaynağı kod değil, config ve veri olur.`,
qs:[
{t:`Container'ın temel faydası nedir?`,o:[`Uygulamayı bağımlılıklarıyla paketleyip her ortamda aynı şekilde çalıştırmak`,`Veritabanını şifrelemek`,`Sayfayı responsive yapmak`,`Kodu otomatik yazmak`],e:`Konteyner gibi: içerik her limanda aynı kalır.`},
{t:`Image ile container arasındaki ilişki nedir?`,o:[`Image paket ve tariftir, container ondan çalışan örnektir`,`İkisi tamamen aynıdır`,`Container, image'ın yedeğidir`,`Image sadece Windows'ta çalışır`],e:`Sınıf ve nesne ilişkisine benzer: tek image'dan birçok container çalışabilir.`},
{t:`Gemi konteyneri benzetmesi hangi sorunu çözmeyi anlatır?`,o:[`Uygulamanın farklı ortamlarda farklı davranmasını`,`Şifrelerin unutulmasını`,`Ekranın yavaş açılmasını`,`Veritabanının dolmasını`],e:`Uygulama kendi ortamıyla taşındığı için "bende çalışıyordu" azalır.`}
]},
{no:124,tr:`Kubernetes / OpenShift`,en:`Kubernetes / OpenShift`,
def:`Kubernetes, çok sayıda container'ı sunucular üzerinde otomatik dağıtan, ölçekleyen ve çökeni yeniden başlatan bir container orkestrasyon platformudur; OpenShift ise Red Hat'in Kubernetes üzerine kurumsal özellikler ekleyen sürümüdür.`,
an:`Liman işletmesi: binlerce konteyneri hangi gemiye, hangi rafa koyacağını planlar; bir vinç bozulursa yükü diğerine aktarır, yoğunlukta ek vinç devreye alır.`,
fi:`Kubernetes'e istenen durumu söylersin, gerisini o yönetir:`,
code:[`SET istenen = { app: "fatura-api", kopya: 3, image: "fatura-api:1.4.2" }`,
`WHILE true                                     // sürekli kontrol`,
`    IF çalışan_kopya < istenen.kopya THEN CALL yeni_pod_başlat()`,
`    IF pod_sağlıksız THEN CALL pod_yeniden_başlat()`,
`    IF cpu_kullanımı > 80 THEN CALL kopya_artır()`,
`END WHILE`],
note:`OpenShift arayüzünden pod'ların durumu, logları ve yeniden başlama sayıları görülür. Bir pod sürekli yeniden başlıyorsa (CrashLoopBackOff) uygulama ayağa kalkarken hata alıyordur; sebebi pod logundadır.`,
qs:[
{t:`Kubernetes'in temel görevi nedir?`,o:[`Container'ları dağıtmak, ölçeklemek ve çökeni yeniden başlatmak`,`Kaynak kod yazmak`,`Tasarım yapmak`,`Veritabanı sorgusu çalıştırmak`],e:`Liman işletmesi gibi: yerleştirir, izler, gerekirse yeniden düzenler.`},
{t:`OpenShift ile Kubernetes arasındaki ilişki nedir?`,o:[`OpenShift, Kubernetes üzerine kurulu kurumsal bir platformdur`,`İkisi rakip veritabanlarıdır`,`OpenShift bir programlama dilidir`,`Kubernetes, OpenShift'in tarayıcı eklentisidir`],e:`OpenShift'in altında Kubernetes çalışır.`},
{t:`Bir pod sürekli yeniden başlıyor (CrashLoopBackOff). Sebebi ilk nerede aranır?`,o:[`Pod'un loglarında`,`Tarayıcı geçmişinde`,`CSS dosyasında`,`DNS önbelleğinde`],e:`Uygulama açılırken neden düştüğünü kendi logunda yazar.`}
]},
{no:125,tr:`Pod`,en:`Pod`,
def:`Pod, Kubernetes ve OpenShift'te çalışan en küçük birimdir; içinde bir (bazen birkaç) container barındırır ve kendi IP adresine sahiptir.`,
an:`Limanda konteynerin konduğu numaralı park yeri: uygulamanın 3 kopyası demek, 3 ayrı park yerinde 3 konteyner demektir.`,
fi:`Bir uygulamanın pod'ları:`,
code:[`// oc get pods`,
`NAME                      STATUS             RESTARTS`,
`fatura-api-7d9f-x2k4p     Running            0`,
`fatura-api-7d9f-m8n1q     Running            0`,
`fatura-api-7d9f-q5z7w     CrashLoopBackOff   12`,
``,
`// Sorunlu pod'un logunu oku`,
`oc logs fatura-api-7d9f-q5z7w`],
note:`Pod'lar geçicidir: silinip yeniden oluşturulabilir ve her seferinde adı değişir. Bu yüzden loglar genelde Elasticsearch gibi merkezi bir sisteme de gönderilir; aksi halde pod silinince logu da kaybolur.`,
qs:[
{t:`Pod nedir?`,o:[`Kubernetes/OpenShift'te container barındıran en küçük çalışma birimi`,`Bir veritabanı tablosu`,`Bir HTTP metodu`,`Bir CSS kuralı`],e:`Konteynerin park yeri: uygulamanın her kopyası bir pod'da çalışır.`},
{t:`Yukarıdaki listede hangi pod sorunludur?`,o:[`CrashLoopBackOff durumundaki ve 12 kez yeniden başlayan pod`,`İlk Running pod`,`İkinci Running pod`,`Hiçbiri`],e:`Sürekli çöküp yeniden başlayan pod ayağa kalkamıyor demektir.`},
{t:`Loglar neden merkezi bir sisteme de gönderilir?`,o:[`Pod'lar geçicidir; pod silinince içindeki log da kaybolur`,`Pod'lar hiç log üretmez`,`Merkezi sistem logları siler`,`Tarayıcı bunu zorunlu tutar`],e:`Park yeri boşaltılınca içindeki kayıtlar da gider.`}
]},
{no:126,tr:`Cloud`,en:`Cloud · Bulut`,
def:`Cloud, sunucu, depolama, veritabanı ve ağ gibi kaynakların kendi veri merkezini kurmadan, internet üzerinden ihtiyaç kadar kiralanıp kullanılmasıdır.`,
an:`Elektrik şebekesi: evine kendi jeneratörünü kurmazsın; prize takarsın, kullandığın kadar ödersin. Bulut da bilgi işlem gücünü şebekeden çekmek gibidir.`,
fi:`Kendi sunucun ile bulut arasındaki fark:`,
code:[`// Kendi veri merkezi (on-premise)`,
`CALL sunucu_satın_al()                    // haftalar sürer`,
`CALL kur_ve_yönet()                       // donanım arızası senin sorunun`,
``,
`// Bulut`,
`CALL sunucu_iste(cpu = 4, ram = 16)       // dakikalar sürer`,
`IF trafik_arttı THEN CALL sunucu_ekle()   // ihtiyaç kadar büyü`,
`IF trafik_azaldı THEN CALL sunucu_azalt() // kullandığın kadar öde`],
note:`AWS, Microsoft Azure ve Google Cloud en büyük sağlayıcılardır. Bankalar ve telekom şirketleri gibi kurumlar, veri düzenlemeleri nedeniyle sıklıkla kendi veri merkezlerini ya da şirkete özel (private) bulutları kullanır.`,
qs:[
{t:`Cloud'un temel fikri nedir?`,o:[`Bilgi işlem kaynaklarını ihtiyaç kadar internet üzerinden kiralayıp kullanmak`,`Tüm donanımı satın alıp ofiste tutmak`,`İnternetsiz çalışmak`,`Sadece e-posta göndermek`],e:`Şebeke gibi: kullandığın kadar.`},
{t:`Hangisi bir bulut sağlayıcısıdır?`,o:[`AWS`,`Jenkins`,`Selenium`,`Figma`],e:`AWS, Amazon'un bulut platformudur.`},
{t:`Şebeke benzetmesinde "kendi jeneratörünü kurmak" neye karşılık gelir?`,o:[`Kendi veri merkezini kurmak (on-premise)`,`Bulut kullanmak`,`Cache kullanmak`,`Rollback yapmak`],e:`Donanımı kendin alır, kendin işletirsin.`}
]}
]);

add(12,`DevOps ve altyapı`,[
{no:127,tr:`Log`,en:`Log`,
def:`Log, bir uygulamanın çalışırken ne yaptığını, hangi isteği aldığını ve hangi hatayla karşılaştığını zaman damgasıyla kaydettiği metin kayıtlarıdır.`,
an:`Uçağın kara kutusu: uçuş boyunca her şeyi kaydeder; bir sorun olduğunda ne olduğunu anlamak için ilk açılan şeydir.`,
fi:`Tipik log satırları ve seviyeleri:`,
code:[`2026-11-01 14:32:07 INFO  [7f3a-91bc] GET /faturalar/77 alındı`,
`2026-11-01 14:32:07 DEBUG [7f3a-91bc] CRM'e istek gönderiliyor`,
`2026-11-01 14:32:37 WARN  [7f3a-91bc] CRM 30 saniyede cevap vermedi`,
`2026-11-01 14:32:37 ERROR [7f3a-91bc] TimeoutException at FaturaService:84`,
``,
`// Seviyeler: DEBUG < INFO < WARN < ERROR`],
note:`Köşeli parantezdeki correlation id, aynı isteğe ait satırları farklı servislerde bulmayı sağlar. Loglara şifre, token ya da kart bilgisi yazılmamalıdır; bu bir güvenlik bulgusudur.`,
qs:[
{t:`Log nedir?`,o:[`Uygulamanın yaptıklarını ve hatalarını zaman damgasıyla kaydettiği kayıtlar`,`Bir veritabanı tablosu`,`Bir tasarım dosyası`,`Bir HTTP metodu`],e:`Kara kutu gibi: ne oldu, ne zaman oldu.`},
{t:`Hangi log seviyesi bir hatayı gösterir?`,o:[`ERROR`,`DEBUG`,`INFO`,`TRACE`],e:`ERROR, işlemin başarısız olduğunu bildirir; WARN ise dikkat edilmesi gereken bir durumu.`},
{t:`Bir isteğin farklı servislerdeki log satırlarını birbirine bağlamak için ne kullanılır?`,o:[`Correlation id`,`CSS sınıfı`,`Port numarası`,`Commit mesajı`],e:`Aynı kimlik isteğin geçtiği her serviste loga yazılır; arayınca hepsi bulunur.`}
]},
{no:128,tr:`Monitoring ve Alert`,en:`Monitoring and Alerting`,
def:`Monitoring, sistemlerin sağlık durumunu (cevap süresi, hata oranı, CPU, bellek) sürekli ölçüp izlemektir; alert ise ölçülen değer belirlenen eşiği aştığında ilgililere otomatik uyarı gönderilmesidir.`,
an:`Arabanın gösterge paneli ve uyarı ışıkları: hızı, yakıtı, motor ısısını sürekli gösterir; yağ azalınca kırmızı ışık yanar. Sorun büyümeden haberdar olursun.`,
fi:`Basit bir alarm kuralı:`,
code:[`ON her_dakika DO`,
`    SET hata_oranı = CALL son_5_dk_5xx_oranı("fatura-api")`,
`    SET p95_süre   = CALL son_5_dk_p95_süresi("fatura-api")`,
`    IF hata_oranı > 5 OR p95_süre > 3000 THEN     // yüzde, milisaniye`,
`        SEND alarm TO nöbetçi_ekip                // SMS, e-posta, Slack`,
`    END IF`,
`END`],
note:`Grafana, Kibana, Prometheus ve Dynatrace bu alanda bilinen araçlardır. İyi bir monitoring, müşteri şikâyet etmeden önce sorunu fark etmeyi sağlar.`,
qs:[
{t:`Monitoring'in amacı nedir?`,o:[`Sistemlerin sağlık durumunu sürekli ölçüp izlemek`,`Kaynak kod yazmak`,`Tasarım çizmek`,`Veritabanı silmek`],e:`Gösterge paneli gibi: her an ne durumda olduğunu gösterir.`},
{t:`Alert ne zaman tetiklenir?`,o:[`Ölçülen değer belirlenen eşiği aştığında`,`Her saat başı rastgele`,`Sadece kod commit edildiğinde`,`Hiçbir zaman`],e:`Yağ seviyesi eşik altına inince ışık yanar.`},
{t:`Gösterge paneli benzetmesinde yağ uyarı ışığı neye karşılık gelir?`,o:[`Alert`,`Log satırı`,`Commit`,`Branch`],e:`Eşik aşılınca kendiliğinden gelen uyarıdır.`}
]},
{no:129,tr:`Latency`,en:`Latency · Gecikme`,
def:`Latency (gecikme), bir isteğin gönderilmesiyle cevabın gelmesi arasında geçen süredir.`,
an:`Uzaktaki birine seslenmek: bağırdığın an ile cevabının sana dönmesi arasındaki süre. Mesafe ve aradaki engeller arttıkça süre uzar.`,
fi:`Bir isteğin süresinin parçaları:`,
code:[`SET başlangıç = CALL şimdi()`,
`SEND GET /faturalar/77 TO api`,
`    // ağ                  ~ 20 ms`,
`    // gateway             ~ 10 ms`,
`    // backend mantığı     ~ 40 ms`,
`    // CRM çağrısı         ~ 900 ms    <- darboğaz burada`,
`RECEIVE cevap`,
`SHOW CALL şimdi() - başlangıç          // toplam ~ 970 ms`],
note:`Ortalama süre yanıltıcı olabilir; bu yüzden genelde p95 ya da p99 değerine bakılır: p95 = 800 ms, isteklerin yüzde 95'inin 800 ms'den kısa sürdüğünü söyler. Kullanıcıların hissettiği yavaşlık çoğu zaman en yavaş isteklerden gelir.`,
qs:[
{t:`Latency nedir?`,o:[`İstek ile cevap arasında geçen süre`,`Saniyede işlenen istek sayısı`,`Sunucunun disk boyutu`,`Bir hata kodu`],e:`Seslenip cevap alana kadar geçen süredir.`},
{t:`Yukarıdaki dağılımda toplam süreyi en çok ne artırıyor?`,o:[`CRM çağrısı`,`Ağ`,`Gateway`,`Backend mantığı`],e:`970 ms'nin 900 ms'i tek bir çağrıdan geliyor; iyileştirme oraya odaklanmalı.`},
{t:`p95 süresinin 800 ms olması ne anlama gelir?`,o:[`İsteklerin yüzde 95'i 800 ms'den kısa sürüyor`,`Tüm istekler tam 800 ms sürüyor`,`Ortalama süre 95 ms`,`95 istek hata aldı`],e:`En yavaş yüzde 5'lik dilimi dışarıda bırakan eşik değeridir.`}
]},
{no:130,tr:`Scalability`,en:`Scalability · Ölçeklenebilirlik`,
def:`Scalability, bir sistemin artan yük karşısında kaynak ekleyerek performansını koruyabilme yeteneğidir; daha güçlü makine eklemek dikey, daha fazla makine eklemek yatay ölçeklemedir.`,
an:`Kalabalıklaşan restoran: ya aşçıya daha büyük bir ocak alırsın (dikey) ya da mutfağa yeni aşçılar eklersin (yatay). İkincisinin sınırı daha uzaktır ama aşçıların uyumlu çalışması gerekir.`,
fi:`Yük arttığında iki seçenek:`,
code:[`IF anlık_istek > kapasite THEN`,
`    // Dikey (scale up): aynı sunucuyu büyüt`,
`    CALL ram_ayarla(64)                  // 16 GB'tan 64 GB'a`,
`    // Yatay (scale out): kopya ekle`,
`    CALL pod_sayısı_ayarla(8)            // 3 kopyadan 8 kopyaya`,
`END IF`],
note:`Yatay ölçeklenebilmek için uygulamanın durumsuz (stateless) olması gerekir; kullanıcı oturumu sadece bir sunucuda tutuluyorsa diğer kopyalar o kullanıcıyı tanımaz. Kampanya dönemleri ölçeklenebilirliğin en çok sınandığı anlardır.`,
qs:[
{t:`Yatay ölçekleme nedir?`,o:[`Aynı uygulamanın daha fazla kopyasını ekleyip yükü dağıtmak`,`Sunucuya daha fazla RAM eklemek`,`Kodu silmek`,`Veritabanını küçültmek`],e:`Mutfağa yeni aşçılar eklemek gibi.`},
{t:`Restoran benzetmesinde "daha büyük ocak almak" neye karşılık gelir?`,o:[`Dikey ölçekleme`,`Yatay ölçekleme`,`Rollback`,`Cache`],e:`Aynı makineyi güçlendirmek dikey ölçeklemedir.`},
{t:`Yatay ölçekleme için uygulamanın hangi özelliği önemlidir?`,o:[`Durumsuz (stateless) olması`,`Oturumu tek bir sunucuda tutması`,`Hiç log yazmaması`,`Sadece gece çalışması`],e:`Hangi kopyaya düşerse düşsün istek aynı şekilde işlenebilmelidir.`}
]},
{no:131,tr:`SLA ve Downtime`,en:`Service Level Agreement and Downtime`,
def:`SLA, bir hizmetin ne kadar erişilebilir olacağını ve sorunların ne kadar sürede çözüleceğini taahhüt eden anlaşmadır; downtime ise sistemin kullanılamadığı süredir.`,
an:`Kargo şirketinin "24 saatte teslim, yoksa ücret iadesi" sözü: söz verilen hizmet seviyesi SLA'dır. Teslimatın yapılamadığı süre de downtime'dır.`,
fi:`Yüzde 99,9 erişilebilirlik ne demek:`,
code:[`SET yıllık_dakika = 365 * 24 * 60              // 525.600 dakika`,
`SET izinli_kesinti = yıllık_dakika * 0.001      // yüzde 0,1`,
`SHOW izinli_kesinti                             // ~ 526 dakika: ~ 8,8 saat`,
``,
`// Yüzde 99,99 olsaydı: yılda ~ 53 dakika`],
note:`Planlı bakım genelde SLA hesabının dışında tutulur ve önceden duyurulur. Bir sorunun önceliği belirlenirken SLA süresi esas alınır: kritik bir hatanın çözüm süresi saatlerle ölçülür.`,
qs:[
{t:`SLA nedir?`,o:[`Hizmetin erişilebilirlik ve çözüm sürelerine dair taahhüt edilen anlaşma`,`Bir veritabanı sorgusu`,`Bir HTML etiketi`,`Bir test aracı`],e:`Kargo şirketinin teslim sözü gibi.`},
{t:`Downtime nedir?`,o:[`Sistemin kullanılamadığı süre`,`Sistemin en hızlı çalıştığı süre`,`Deploy'un bitiş zamanı`,`Bir log seviyesi`],e:`Hizmetin verilemediği zaman dilimidir.`},
{t:`Yüzde 99,9 erişilebilirlik yılda yaklaşık ne kadar kesintiye izin verir?`,o:[`Yaklaşık 8,8 saat`,`Yaklaşık 5 dakika`,`Yaklaşık 3 gün`,`Hiç kesintiye izin vermez`],e:`525.600 dakikanın binde biri yaklaşık 526 dakikadır.`}
]},
{no:132,tr:`Incident`,en:`Incident`,
def:`Incident, canlı ortamda hizmetin kesilmesine ya da kalitesinin düşmesine yol açan ve hızlı müdahale gerektiren beklenmedik olaydır.`,
an:`Acil servis vakası: önce hastanın hayati durumu stabilize edilir (hizmet geri getirilir), sonra hastalığın asıl sebebi araştırılır (kök neden).`,
fi:`Bir incident'ın yaşam döngüsü:`,
code:[`ON alarm("Ödeme hata oranı yüzde 40") DO`,
`    SET öncelik = "P1"                      // en kritik seviye`,
`    CALL nöbetçi_ekibi_çağır()`,
`    CALL etkiyi_belirle()                   // kaç müşteri, hangi kanal`,
`    CALL geçici_çözüm_uygula()              // rollback, yeniden başlatma`,
`    CALL durum_duyur(iş_birimi)             // düzenli bilgilendirme`,
`    CALL kök_neden_analizi()                // hizmet döndükten sonra`,
`END`],
note:`Incident yönetiminde öncelik sırası bellidir: önce müşteri etkisini durdur, sonra kalıcı çözümü bul. Olay sonrası yazılan postmortem raporu, aynı sorunun tekrar etmemesi için yapılacakları listeler.`,
qs:[
{t:`Incident nedir?`,o:[`Canlıda hizmetin kesilmesine ya da bozulmasına yol açan beklenmedik olay`,`Planlı bir yeni özellik`,`Bir kod incelemesi`,`Bir tasarım toplantısı`],e:`Acil servis vakası gibi: hızlı müdahale gerekir.`},
{t:`Incident sırasında ilk öncelik nedir?`,o:[`Müşteri etkisini durdurup hizmeti geri getirmek`,`Kök nedeni bulmadan hiçbir şey yapmamak`,`Sonraki sprinti planlamak`,`Yeni özellik eklemek`],e:`Önce hasta stabilize edilir, teşhis sonra konur.`},
{t:`Olay kapandıktan sonra aynı sorunun tekrarlanmaması için hazırlanan rapora ne denir?`,o:[`Postmortem`,`Release notu`,`Swagger`,`Pull request`],e:`Ne oldu, neden oldu, bir daha olmaması için ne yapılacak sorularını cevaplar.`}
]}
]);

add(13,`Test ve kalite`,[
{no:133,tr:`Bug / Defect`,en:`Bug / Defect`,
def:`Bug (defect), yazılımın beklenen davranıştan farklı davranmasına yol açan hatadır; beklenen ile gerçekleşen arasındaki farktır.`,
an:`Tarifte "1 kaşık tuz" yazarken yemeğe 1 kâse tuz konması: tarif (gereksinim) belli, sonuç (davranış) farklı. Aradaki fark bug'dır.`,
fi:`İyi bir bug kaydının iskeleti:`,
code:[`SET bug = {`,
`  başlık:      "Ödemesi alınan fatura 'Ödenmedi' görünüyor",`,
`  ortam:       "TEST · v1.4.2",`,
`  adımlar:     ["Giriş yap", "Faturayı öde", "Listeye dön"],`,
`  beklenen:    "Fatura durumu 'Ödendi' olmalı",`,
`  gerçekleşen: "Durum 'Ödenmedi' kalıyor; DB'de güncellenmiş",`,
`  kanıt:       ["ekran.png", "network.har", "correlation-id 7f3a-91bc"]`,
`}`],
note:`Beklenen ile gerçekleşen arasındaki fark net yazılamıyorsa ortada henüz bir bug değil, bir soru vardır. Tekrar üretilebilen adımlar, bug'ın hızlı çözülmesinin en önemli şartıdır.`,
qs:[
{t:`Bug için en doğru tanım hangisidir?`,o:[`Beklenen davranış ile gerçekleşen davranış arasındaki fark`,`Sadece sistemin çökmesi`,`Yeni bir özellik isteği`,`Kodun uzun olması`],e:`Çökme bir bug türüdür ama tek türü değildir; yanlış hesaplanan bir tutar da bug'dır.`},
{t:`Bir bug kaydında hangisi mutlaka olmalıdır?`,o:[`Tekrar üretme adımları, beklenen ve gerçekleşen sonuç`,`Sadece başlık`,`Sadece geliştiricinin adı`,`Sadece ekran görüntüsü`],e:`Geliştirici hatayı kendi gözüyle görebilmeli ve neyin doğru olduğunu bilmelidir.`},
{t:`Tarif benzetmesinde tarifin kendisi neye karşılık gelir?`,o:[`Gereksinim (beklenen davranış)`,`Bug`,`Log`,`Deploy`],e:`Neyin olması gerektiğini söyleyen şey gereksinimdir.`}
]},
{no:134,tr:`Test Case ve Test Senaryosu`,en:`Test Case and Test Scenario`,
def:`Test senaryosu neyin test edileceğini anlatan üst seviye durumdur; test case ise bu durumu ön koşul, adım, test verisi ve beklenen sonuçla tarif eden uygulanabilir testtir.`,
an:`Senaryo "misafire akşam yemeği hazırla" hedefidir; test case'ler ise "çorbayı 20 dakika kaynat, tadına bak, tuzu kontrol et" gibi adım adım tariflerdir.`,
fi:`Bir senaryodan test case'lere:`,
code:[`// Senaryo: Kullanıcı faturasını ödeyebilmeli`,
`TC-01 "Geçerli kartla tam ödeme"`,
`    ön koşul: ödenmemiş fatura var`,
`    adımlar:  faturayı seç, kartı gir, öde`,
`    beklenen: "Ödeme alındı" mesajı, fatura durumu ODENDI`,
`TC-02 "Yetersiz bakiyeli kart"`,
`    beklenen: "Bakiye yetersiz" mesajı, fatura durumu değişmez`,
`TC-03 "Ödeme sırasında timeout"`,
`    beklenen: çift tahsilat olmaz, durum tutarlı kalır`],
note:`İyi bir test case başkası tarafından okunduğunda aynı şekilde uygulanabilir ve sonucu tartışmasız değerlendirilebilir. Pozitif senaryolar kadar negatif ve sınır durumlar da yazılmalıdır.`,
qs:[
{t:`Test case ile test senaryosu arasındaki fark nedir?`,o:[`Senaryo neyin, test case nasıl test edileceğini adım adım anlatır`,`İkisi tamamen aynıdır`,`Test case sadece otomasyonda kullanılır`,`Senaryo sadece canlıda çalıştırılır`],e:`Senaryo hedef, test case tariftir.`},
{t:`Bir test case'de mutlaka bulunması gereken bilgi hangisidir?`,o:[`Beklenen sonuç`,`Geliştiricinin doğum tarihi`,`Sunucunun rengi`,`Commit mesajı`],e:`Beklenen sonuç yoksa testin geçip geçmediğine karar verilemez.`},
{t:`"Yetersiz bakiyeli kartla ödeme" ne tür bir test durumudur?`,o:[`Negatif test`,`Pozitif test`,`Performans testi`,`Smoke test`],e:`Sistemin hatalı ya da beklenmeyen durumda doğru tepki verdiğini kontrol eder.`}
]},
{no:135,tr:`Unit Test`,en:`Unit Test`,
def:`Unit test, kodun en küçük parçalarını (genellikle tek bir fonksiyonu) diğer parçalardan izole şekilde, kodla yazılmış otomatik testlerle doğrulamaktır.`,
an:`Arabanın fren balatasını, arabaya takmadan önce tezgâhta test etmek: hızlı, ucuz ve sorunu tam yerinde bulur.`,
fi:`kdv_hesapla fonksiyonunun unit testleri:`,
code:[`TEST "100 TL'ye yüzde 20 KDV eklenir"`,
`    SET sonuç = CALL kdv_hesapla(100)`,
`    ASSERT sonuç == 120                  // beklenen değer`,
``,
`TEST "Negatif tutar hata fırlatır"`,
`    TRY`,
`        CALL kdv_hesapla(-5)`,
`        FAIL "Hata bekleniyordu"`,
`    CATCH GeçersizTutarHatası`,
`        PASS`,
`    END TRY`],
note:`Unit testler genelde JUnit ya da TestNG gibi araçlarla geliştiriciler tarafından yazılır ve her build'de saniyeler içinde çalışır. Test piramidinin tabanıdır: sayıca en çok, en hızlı ve en ucuz testlerdir.`,
qs:[
{t:`Unit test neyi test eder?`,o:[`Kodun en küçük parçasını, genellikle tek bir fonksiyonu, izole şekilde`,`Tüm sistemi uçtan uca`,`Sadece kullanıcı arayüzünü`,`Sadece veritabanı yedeklerini`],e:`Tezgâhta tek parça testi gibi.`},
{t:`Unit testler genelde kim tarafından yazılır?`,o:[`Geliştiriciler`,`Sadece iş birimi`,`Sadece son kullanıcılar`,`Müşteriler`],e:`Kodu yazan, en küçük parçaların davranışını da kodla doğrular.`},
{t:`Test piramidinde unit testlerin yeri neresidir?`,o:[`Taban: en çok, en hızlı ve en ucuz testler`,`Tepe: en az ve en yavaş testler`,`Piramidin dışında`,`Sadece canlı ortamda`],e:`Yukarı çıktıkça testler azalır, yavaşlar ve pahalılaşır.`}
]},
{no:136,tr:`Integration Test`,en:`Integration Test`,
def:`Integration test, birbiriyle konuşan iki ya da daha fazla bileşenin (servis, veritabanı, dış sistem) birlikte doğru çalıştığını doğrulayan testtir.`,
an:`Tezgâhta tek tek sağlam çıkan balata ile diskin, birlikte takıldığında da düzgün fren yaptığını kontrol etmek. Parçalar sağlam olabilir ama birbirine uymayabilir.`,
fi:`Backend ile entegrasyon katmanı arasındaki test:`,
code:[`TEST "Fatura servisi CRM verisini doğru dönüştürür"`,
`    SEND GET /faturalar/77 TO fatura_api       // gerçek CRM'e gider`,
`    ASSERT cevap.status == 200`,
`    ASSERT cevap.body.tutar == crm_kaydı.AMT / 100    // mapping doğru mu?`,
`    ASSERT cevap.body.durum IN ["ODENDI", "ODENMEDI"]`],
note:`Unit testler geçse bile parçaların birleşim noktalarında (alan adı farkı, format farkı, timeout) hata çıkabilir. API testleri çoğu zaman entegrasyon testi niteliğindedir.`,
qs:[
{t:`Integration test neyi doğrular?`,o:[`Birden fazla bileşenin birlikte doğru çalıştığını`,`Tek bir fonksiyonun doğru hesapladığını`,`Butonun rengini`,`Kodun okunaklı olduğunu`],e:`Parçalar arasındaki bağlantı noktalarını sınar.`},
{t:`Unit testleri geçen iki servis birlikte çalıştırıldığında hata veriyor. Bu hangi test türünün yakalayacağı bir hatadır?`,o:[`Integration test`,`Unit test`,`Statik kod analizi`,`Yazım denetimi`],e:`Sorun parçaların kendisinde değil, birleşim noktasındadır.`},
{t:`Fren benzetmesinde "balata ile diskin birlikte denenmesi" neye karşılık gelir?`,o:[`Integration test`,`Unit test`,`Deploy`,`Code review`],e:`Sağlam parçaların birlikte de uyumlu çalıştığını doğrular.`}
]},
{no:137,tr:`E2E Test`,en:`End-to-End Test`,
def:`E2E (uçtan uca) test, bir iş akışını kullanıcının gözünden, arayüzden başlayıp arkadaki tüm katmanlardan geçerek baştan sona gerçeğe en yakın koşullarda doğrulayan testtir.`,
an:`Arabayı tezgâhta değil, yolda test sürüşüne çıkarmak: motor, fren, direksiyon, lastik hepsi birlikte, gerçek yolda çalışıyor mu?`,
fi:`Fatura ödeme akışı uçtan uca:`,
code:[`CALL aç("https://test-portal.ornek.com")`,
`CALL giriş_yap(test_kullanıcısı)`,
`CALL tıkla("Faturalarım")`,
`CALL tıkla("Ekim 2026 · Öde")`,
`CALL kart_bilgisi_gir(test_kartı)`,
`CALL tıkla("Ödemeyi Onayla")`,
`ASSERT ekranda("Ödemeniz alındı")`,
`ASSERT veritabanında(fatura.durum == "ODENDI")     // arayüzden DB'ye kadar`],
note:`E2E testler en gerçekçi ama en yavaş ve kırılgan testlerdir; bir ortam ya da veri sorunu tüm testi düşürebilir. Bu yüzden sayıca az ama kritik iş akışlarını kapsayacak şekilde seçilir ve Selenium gibi araçlarla otomatikleştirilir.`,
qs:[
{t:`E2E test neyi doğrular?`,o:[`Bir iş akışının arayüzden veritabanına kadar baştan sona çalıştığını`,`Tek bir fonksiyonu`,`Sadece CSS'i`,`Sadece ağ hızını`],e:`Test sürüşü gibi: her şey birlikte, gerçek yolda.`},
{t:`E2E testlerin dezavantajı nedir?`,o:[`Yavaş ve kırılgan olmaları; bir ortam sorunu tüm testi düşürebilir`,`Hiç gerçekçi olmamaları`,`Sadece tek fonksiyonu test etmeleri`,`Hata bulamamaları`],e:`Çok katmandan geçtiği için herhangi bir katmandaki sorun testi kırar.`},
{t:`Araba benzetmesinde E2E test neye karşılık gelir?`,o:[`Gerçek yolda test sürüşü`,`Tezgâhta tek parça testi`,`Arabayı boyamak`,`Arabayı satmak`],e:`Tüm parçalar gerçek koşullarda birlikte denenir.`}
]},
{no:138,tr:`Regression Test`,en:`Regression Test`,
def:`Regression (regresyon) test, yapılan bir değişikliğin daha önce çalışan özellikleri bozmadığını doğrulamak için mevcut testlerin yeniden çalıştırılmasıdır.`,
an:`Musluğu tamir ettikten sonra sadece musluğa değil, diğer odalardaki suya, ısıtıcıya da bakmak: tamir bir yeri düzeltirken başka bir yeri bozmuş olabilir.`,
fi:`Bir değişiklik sonrası regresyon:`,
code:[`ON yeni_deploy DO`,
`    RUN yeni_özellik_testleri          // değişen yer`,
`    FOR EACH test IN regresyon_seti    // önceden geçen testler`,
`        RUN test`,
`        IF test.önceden_geçiyordu AND test.şimdi_kaldı THEN`,
`            LOG "Regresyon hatası: " + test.adı`,
`        END IF`,
`    END FOR`,
`END`],
note:`Regresyon setleri her sürümde tekrar çalıştırıldığı için otomasyona en uygun testlerdir. "Daha önce çalışıyordu, şimdi çalışmıyor" cümlesi bir regresyon hatasını anlatır.`,
qs:[
{t:`Regression test'in amacı nedir?`,o:[`Yeni değişikliğin daha önce çalışan özellikleri bozmadığını doğrulamak`,`Sadece yeni özelliği test etmek`,`Kodu derlemek`,`Performansı ölçmek`],e:`Tamirin başka bir yeri bozmadığından emin olmak.`},
{t:`"Geçen sürümde çalışıyordu, bu sürümde bozuldu" hangi hata türüdür?`,o:[`Regresyon hatası`,`Yeni özellik talebi`,`Tasarım önerisi`,`Performans iyileştirmesi`],e:`Geriye doğru bir kayıp olduğu için regresyon denir.`},
{t:`Regresyon testleri neden otomasyona çok uygundur?`,o:[`Her sürümde aynı testler tekrar tekrar çalıştırıldığı için`,`Hiç değişmeyen kodu test ettikleri için`,`Sadece bir kez çalıştırıldıkları için`,`Manuel yapılamadıkları için`],e:`Tekrar eden iş, otomasyonun en çok kazandırdığı yerdir.`}
]},
{no:139,tr:`Smoke ve Sanity Test`,en:`Smoke and Sanity Test`,
def:`Smoke test, yeni bir build'in temel işlevlerinin çalışıp çalışmadığını hızlıca kontrol eden geniş ve yüzeysel testtir; sanity test ise küçük bir değişiklik sonrası o alanın mantıklı çalıştığını doğrulayan dar ve odaklı testtir.`,
an:`Smoke test yeni cihaza ilk kez elektrik verip duman çıkıyor mu diye bakmaktır; çıkmıyorsa detaylı teste geçilir. Sanity test ise tamir edilen musluğu açıp suyun akıp akmadığına bakmaktır.`,
fi:`Deploy sonrası ilk dakikalar:`,
code:[`// Smoke: sistem genel olarak ayakta mı?`,
`ASSERT giriş_sayfası_açılıyor`,
`ASSERT giriş_yapılabiliyor`,
`ASSERT ana_menüler_açılıyor`,
`ASSERT kritik_api_health == "UP"`,
`IF smoke_başarısız THEN SHOW "Build reddedildi, detaylı test yapılmaz"`,
``,
`// Sanity: düzeltilen hata gerçekten düzelmiş mi?`,
`ASSERT ödeme_sonrası_durum == "ODENDI"      // sadece ilgili alan`],
note:`Smoke testi geçmeyen bir build üzerinde detaylı test yapmak zaman kaybıdır; build geri gönderilir. İki terim günlük dilde sık karıştırılır; asıl fark smoke'un geniş ve yüzeysel, sanity'nin dar ve odaklı olmasıdır.`,
qs:[
{t:`Smoke test'in amacı nedir?`,o:[`Yeni build'in temel işlevlerinin çalıştığını hızlıca kontrol etmek`,`Tüm detayları tek tek test etmek`,`Performans sınırını bulmak`,`Kod incelemesi yapmak`],e:`Duman çıkıyor mu, çıkmıyor mu: önce bu.`},
{t:`Smoke test başarısız olursa genelde ne yapılır?`,o:[`Build reddedilir, detaylı teste geçilmez`,`Detaylı teste devam edilir`,`Canlıya alınır`,`Testler silinir`],e:`Temeli çalışmayan bir build'de detay aramak zaman kaybıdır.`},
{t:`Smoke ile sanity arasındaki temel fark nedir?`,o:[`Smoke geniş ve yüzeysel, sanity dar ve odaklıdır`,`İkisi tamamen aynıdır`,`Smoke sadece canlıda yapılır`,`Sanity sadece performans ölçer`],e:`Biri genel sağlık kontrolü, diğeri belirli bir noktanın kontrolüdür.`}
]}
]);

add(13,`Test ve kalite`,[
{no:140,tr:`Mock ve Stub`,en:`Mock and Stub`,
def:`Mock ve stub, test sırasında gerçek bir bağımlılığın yerine geçen sahte bileşenlerdir; stub önceden belirlenmiş sabit cevaplar döner, mock ise ayrıca kendisine nasıl çağrı yapıldığını da doğrular.`,
an:`Film çekimindeki dublör: tehlikeli sahnede gerçek oyuncunun yerine geçer. Stub sadece sahnede durur; mock ise ayrıca "bana doğru zamanda doğru replikle mi seslendiler?" diye de kontrol eder.`,
fi:`CRM test ortamı kapalıyken fatura servisini test etmek:`,
code:[`// Stub: sabit cevap döner`,
`STUB crm.müşteri_getir(1002345) RETURNS { ad: "Ayşe", durum: "A" }`,
``,
`// Mock: cevap döner ve çağrıyı doğrular`,
`MOCK sms_servisi.gönder`,
`CALL ödeme_al(1002345, 249.90)`,
`VERIFY sms_servisi.gönder CALLED 1 TIMES WITH telefon = "5321112233"`],
note:`WireMock ve Mockito bilinen araçlardır. Mock'lar testi bağımlılıklardan kurtarır ama gerçeği birebir yansıtmayabilir; gerçek sistemle entegrasyon testi yine gereklidir.`,
qs:[
{t:`Mock ve stub'ın amacı nedir?`,o:[`Test sırasında gerçek bağımlılıkların yerine geçmek`,`Canlı ortamı yönetmek`,`Kodu derlemek`,`Kullanıcı şifrelerini saklamak`],e:`Dublör gibi: gerçeğin yerine geçer.`},
{t:`Stub ile mock arasındaki fark nedir?`,o:[`Stub sabit cevap döner; mock ayrıca nasıl çağrıldığını da doğrular`,`İkisi tamamen aynıdır`,`Mock sadece canlıda çalışır`,`Stub gerçek sistemin kendisidir`],e:`Mock, etkileşimin kendisini de test eder.`},
{t:`CRM test ortamı sık sık kapalı olduğu için fatura servisi testleri kırılıyor. Geçici çözüm ne olabilir?`,o:[`CRM'i mock'lamak`,`Testleri silmek`,`Canlı CRM'i kullanmak`,`Fatura servisini kapatmak`],e:`Bağımlılığın yerine sahtesi konur; asıl entegrasyon ayrıca test edilir.`}
]},
{no:141,tr:`Test Datası`,en:`Test Data`,
def:`Test datası, bir testi çalıştırmak için gereken, belirli koşulları sağlayan ve testin sonucunu tekrarlanabilir kılan veridir.`,
an:`Tarifi denemek için doğru malzeme: "bayat ekmekle tost" tarifini taze ekmekle deneyemezsin. Test de doğru durumdaki veriyle anlamlıdır.`,
fi:`Bir test için doğru müşteriyi bulmak ya da üretmek:`,
code:[`// Aranan: aktif, borçlu, kurumsal müşteri`,
`SELECT m.musteri_no FROM musteri m`,
`JOIN fatura f ON f.musteri_no = m.musteri_no`,
`WHERE m.tip = 'KURUMSAL' AND m.durum = 'AKTIF'`,
`  AND f.durum = 'ODENMEDI'`,
`FETCH FIRST 1 ROWS ONLY;`,
``,
`// Bulunamazsa: test verisini kendin oluştur`,
`CALL test_müşterisi_oluştur("KURUMSAL", borç = 500)`],
note:`Bir testin kullandığı veri başka bir test tarafından değiştirilirse sonuçlar tutarsız olur; bu yüzden test verisi testler arasında paylaşılmamaya çalışılır. Canlı müşteri verisi test ortamında maskelenmeden kullanılmaz.`,
qs:[
{t:`Test datası neden önemlidir?`,o:[`Testin doğru koşullarda ve tekrarlanabilir çalışmasını sağlar`,`Kodu daha hızlı derler`,`Ekranı renklendirir`,`Sunucu sayısını artırır`],e:`Doğru malzeme olmadan tarif denenemez.`},
{t:`İki otomasyon testi aynı müşteri kaydını kullanıyor ve biri kaydı değiştiriyor. Ne olur?`,o:[`Diğer testin sonucu tutarsızlaşabilir`,`Hiçbir şey olmaz`,`İki test birden hızlanır`,`Veritabanı kendiliğinden düzelir`],e:`Biri malzemeyi kullandıysa diğerine bayat malzeme kalır.`},
{t:`Canlı müşteri verisi test ortamında nasıl kullanılmalıdır?`,o:[`Maskelenerek ya da anonimleştirilerek`,`Olduğu gibi`,`Ekran görüntüsüyle paylaşılarak`,`E-postayla gönderilerek`],e:`Gerçek kişisel veriler test ortamına korumasız taşınmaz.`}
]},
{no:142,tr:`Test Otomasyonu`,en:`Test Automation`,
def:`Test otomasyonu, test adımlarının ve beklenen sonuç kontrollerinin kodla yazılıp araçlar aracılığıyla insan müdahalesi olmadan tekrar tekrar çalıştırılmasıdır.`,
an:`Her sabah aynı yolu kendin sürmek yerine otomatik pilotu açmak: rota bir kere tanımlanır, sonra her gün aynı şekilde, yorulmadan gider. Ama yeni bir yol keşfetmek hâlâ insanın işidir.`,
fi:`Bir UI testinin otomasyonu (Selenium ile, sadeleştirilmiş):`,
code:[`driver.get("https://test-portal.ornek.com/login")`,
`driver.findElement(By.id("username")).sendKeys("ayse")`,
`driver.findElement(By.id("password")).sendKeys(şifre)`,
`driver.findElement(By.id("loginBtn")).click()`,
`WAIT UNTIL görünür(By.id("dashboard"))      // sabit sleep yerine`,
`ASSERT driver.getTitle() == "Ana Sayfa"`],
note:`Otomasyon tekrar eden testleri (regresyon, smoke) hızlandırır; keşif ve kullanıcı deneyimi odaklı testlerin yerini tutmaz. Kırılgan seçiciler ve sabit beklemeler (sleep) otomasyon testlerinin en sık bozulma sebepleridir.`,
qs:[
{t:`Test otomasyonunun en büyük faydası nedir?`,o:[`Tekrar eden testleri hızlı ve aynı şekilde defalarca çalıştırabilmek`,`Manuel testi tamamen gereksiz kılmak`,`Kod yazmayı gereksiz kılmak`,`Hataları imkânsız hale getirmek`],e:`Otomatik pilot aynı rotayı yorulmadan tekrarlar.`},
{t:`Hangi test türü otomasyon için en az uygundur?`,o:[`Keşif odaklı (exploratory) test`,`Regresyon testi`,`Smoke test`,`API kontrat testi`],e:`Yeni yol keşfetmek insan sezgisi ister.`},
{t:`Otomasyon testi sayfa geç yüklendiğinde bazen geçiyor bazen kalıyor. Olası sebep nedir?`,o:[`Sabit ya da eksik bekleme kullanılması`,`Testin çok kısa olması`,`Tarayıcının teması`,`Veritabanının çok hızlı olması`],e:`Eleman gelmeden tıklanmaya çalışılırsa test kararsızlaşır (flaky); koşula bağlı bekleme gerekir.`}
]},
{no:143,tr:`BDD ve Gherkin`,en:`Behavior Driven Development and Gherkin`,
def:`BDD, yazılımın davranışını iş birimi, geliştirici ve testçinin ortak anladığı bir dille tanımlayıp testleri bu tanımdan üretme yaklaşımıdır; Gherkin ise bu davranışların Given-When-Then kalıbıyla yazıldığı dildir.`,
an:`Ortak bir sözleşme metni: iş birimi okur ve onaylar, geliştirici koda döker, testçi aynı metni otomatik teste çevirir. Herkes aynı cümleyi okur.`,
fi:`Gherkin ile bir senaryo:`,
code:[`Feature: Fatura ödeme`,
`  Scenario: Geçerli kartla ödeme`,
`    Given müşterinin "Ekim 2026" dönemine ait ödenmemiş faturası var`,
`    When müşteri faturayı geçerli bir kartla öder`,
`    Then "Ödemeniz alındı" mesajı görünür`,
`    And fatura durumu "ODENDI" olur`],
note:`Cucumber, Gherkin cümlelerini Java koduna (step definition) bağlar; Karate ise Gherkin benzeri sözdizimiyle doğrudan API testi yazmayı sağlar. Given ön koşulu, When eylemi, Then beklenen sonucu anlatır.`,
qs:[
{t:`Gherkin'de "When" neyi anlatır?`,o:[`Kullanıcının ya da sistemin yaptığı eylemi`,`Ön koşulu`,`Beklenen sonucu`,`Testin adını`],e:`Given ön koşul, When eylem, Then sonuçtur.`},
{t:`BDD'nin temel faydası nedir?`,o:[`İş birimi, geliştirici ve testçinin aynı davranış tanımı üzerinde anlaşması`,`Kodun daha uzun olması`,`Testlerin gereksiz hale gelmesi`,`Sadece veritabanı testlerini hızlandırması`],e:`Ortak sözleşme gibi: herkes aynı cümleyi okur.`},
{t:`Gherkin cümlelerini Java koduna bağlayan araç hangisidir?`,o:[`Cucumber`,`Jenkins`,`Kibana`,`Docker`],e:`Cucumber her Gherkin adımını bir step definition metoduna eşler.`}
]},
{no:144,tr:`Performans / Load / Stress Test`,en:`Performance / Load / Stress Test`,
def:`Performans testi sistemin hızını ve kaynak kullanımını ölçer; load test beklenen kullanıcı yükü altındaki davranışı, stress test ise kapasitenin üstüne çıkıldığında sistemin nerede ve nasıl kırıldığını ölçer.`,
an:`Bir köprü: performans testi tek aracın geçiş süresini ölçer, load test günlük trafiği taşıyıp taşımadığına bakar, stress test ise köprünün hangi yükte çatlamaya başladığını bulur.`,
fi:`JMeter benzeri bir yük senaryosu:`,
code:[`SET kullanıcı_sayısı = 500              // eş zamanlı sanal kullanıcı`,
`SET süre = 15                           // dakika`,
`FOR EACH kullanıcı IN sanal_kullanıcılar`,
`    REPEAT`,
`        SEND GET /faturalar/{rastgele_müşteri}`,
`        WAIT 2                          // düşünme süresi (saniye)`,
`    UNTIL süre_doldu`,
`END FOR`,
`ASSERT p95_süre < 1000 AND hata_oranı < 1     // milisaniye, yüzde`],
note:`Load test "beklenen yükte kabul edilebilir mi?", stress test "nerede kırılıyor ve kırılınca düzgün toparlanıyor mu?" sorusunu cevaplar. Test ortamının kapasitesi canlıdan küçükse sonuçlar oranlanarak yorumlanır.`,
qs:[
{t:`Load test'in sorusu nedir?`,o:[`Sistem beklenen kullanıcı yükü altında kabul edilebilir çalışıyor mu?`,`Sistem hangi yükte tamamen kırılıyor?`,`Buton rengi doğru mu?`,`Kod okunaklı mı?`],e:`Köprü günlük trafiği taşıyor mu?`},
{t:`Stress test neyi bulmayı amaçlar?`,o:[`Sistemin kapasitesinin üstünde nerede ve nasıl kırıldığını`,`Tek bir fonksiyonun doğruluğunu`,`Yazım hatalarını`,`Tasarım uyumunu`],e:`Sınırın nerede olduğunu ve sınırı aşınca ne olduğunu gösterir.`},
{t:`Köprü benzetmesinde "köprünün hangi yükte çatladığını bulmak" hangi test türüdür?`,o:[`Stress test`,`Load test`,`Smoke test`,`Unit test`],e:`Bilerek kapasitenin üstüne çıkılır.`}
]},
{no:145,tr:`Severity ve Priority`,en:`Severity and Priority`,
def:`Severity bir hatanın sisteme ve kullanıcıya etkisinin ne kadar ağır olduğunu, priority ise hatanın ne kadar acil düzeltilmesi gerektiğini gösterir; ikisi farklı şeyleri ölçer.`,
an:`Hastanede iki ayrı soru: "Hastalık ne kadar ağır?" (severity) ve "Bu hastaya kaçıncı sırada bakmalıyız?" (priority). Ağır ama yavaş ilerleyen bir hastalık bekleyebilir, hafif ama acil bir kanama önce ele alınır.`,
fi:`Severity ve priority'nin ayrıştığı örnekler:`,
code:[`// Yüksek severity, düşük priority`,
`SET bug1 = "Yılda bir kullanılan rapor ekranı çöküyor"`,
``,
`// Düşük severity, yüksek priority`,
`SET bug2 = "Ana sayfada şirket adı yanlış yazılmış"     // herkes görüyor`,
``,
`// Yüksek severity, yüksek priority`,
`SET bug3 = "Ödeme alınamıyor"                          // hemen düzeltilmeli`],
note:`Severity genelde teknik etkiye göre testçi tarafından, priority ise iş önceliğine göre product owner ve iş birimiyle belirlenir. İkisinin ayrı ayrı doğru girilmesi, hangi hatanın önce ele alınacağını netleştirir.`,
qs:[
{t:`Severity neyi ifade eder?`,o:[`Hatanın sisteme ve kullanıcıya etkisinin ağırlığını`,`Hatanın düzeltilme sırasını`,`Hatayı bulan kişiyi`,`Hatanın bulunduğu tarihi`],e:`Hastalığın ne kadar ağır olduğu sorusudur.`},
{t:`Ana sayfadaki şirket adının yanlış yazılması genelde nasıl sınıflandırılır?`,o:[`Düşük severity, yüksek priority`,`Yüksek severity, düşük priority`,`Düşük severity, düşük priority`,`Hata sayılmaz`],e:`Sistemi bozmaz ama herkes görür ve kurum imajını etkiler; hızla düzeltilir.`},
{t:`Priority'yi belirlemede genelde kimin söz hakkı en fazladır?`,o:[`Product owner ve iş birimi`,`Sadece veritabanı yöneticisi`,`Sadece tasarımcı`,`Kimse; otomatik belirlenir`],e:`Neyin önce yapılacağı iş önceliğine göre belirlenir.`}
]}
]);

add(14,`Agile ve iş dili`,[
{no:146,tr:`Agile`,en:`Agile · Çevik`,
def:`Agile, yazılımı tek seferde büyük bir teslimat yerine kısa döngülerle, küçük parçalar halinde geliştirip her döngüde geri bildirim alarak yönü düzelten çalışma yaklaşımıdır.`,
an:`Uzun yolculukta navigasyonla gitmek: rota baştan kilitlenmez, her kavşakta trafiğe göre yeniden hesaplanır. Waterfall ise yola çıkmadan basılmış kâğıt haritayla gitmektir.`,
fi:`Waterfall ile Agile'ın akışı:`,
code:[`// Waterfall: her aşama bir kez, sırayla`,
`analiz -> tasarım -> kod -> test -> canlı    // geri bildirim aylar sonra`,
``,
`// Agile: kısa döngülerin tekrarı`,
`REPEAT`,
`    CALL planla(küçük_parça)`,
`    CALL geliştir_ve_test_et()`,
`    CALL göster_ve_geri_bildirim_al()        // örn. 2 haftada bir`,
`    CALL yönü_düzelt()`,
`UNTIL ürün_yeterli`],
note:`Agile bir yaklaşımdır; Scrum ve Kanban bu yaklaşımı uygulamak için kullanılan çerçevelerdir. Değişime açık olmak plansız çalışmak demek değildir; plan kısa aralıklarla güncellenir.`,
qs:[
{t:`Agile'ın temel fikri nedir?`,o:[`Kısa döngülerle küçük parçalar teslim edip geri bildirime göre yönü düzeltmek`,`Tüm projeyi baştan sona tek seferde teslim etmek`,`Hiç plan yapmamak`,`Test yapmamak`],e:`Navigasyon gibi: her kavşakta yeniden hesapla.`},
{t:`Navigasyon benzetmesinde "basılı kâğıt haritayla gitmek" hangi yaklaşımı anlatır?`,o:[`Waterfall`,`Agile`,`Scrum`,`Kanban`],e:`Plan baştan yapılır ve yol boyunca pek değişmez.`},
{t:`Agile ile Scrum arasındaki ilişki nedir?`,o:[`Agile bir yaklaşım, Scrum onu uygulayan bir çerçevedir`,`İkisi rakip yaklaşımlardır`,`Scrum bir programlama dilidir`,`Agile bir test aracıdır`],e:`Agile "ne", Scrum "nasıl" sorusuna cevap verir.`}
]},
{no:147,tr:`Scrum`,en:`Scrum`,
def:`Scrum, Agile yaklaşımını sabit süreli sprintler, belirli roller (Product Owner, Scrum Master, geliştirme ekibi) ve düzenli toplantılarla uygulayan çalışma çerçevesidir.`,
an:`Bir futbol takımının düzeni: maç takvimi (sprint) belli, teknik direktör ve kaptanın rolleri belli; her maç öncesi taktik toplantısı, sonrası değerlendirme var.`,
fi:`Bir Scrum döngüsü:`,
code:[`REPEAT                                   // her 2 haftada bir`,
`    CALL sprint_planning()               // bu sprintte ne yapılacak?`,
`    FOR EACH gün IN sprint`,
`        CALL daily_standup()             // 15 dakika: dün, bugün, engel`,
`        CALL çalış()`,
`    END FOR`,
`    CALL sprint_review()                 // yapılanı göster, geri bildirim al`,
`    CALL retrospective()                 // nasıl çalıştık, ne iyileşmeli?`,
`UNTIL proje_bitti`],
note:`Product Owner neyin yapılacağını ve önceliğini, Scrum Master sürecin sağlıklı işlemesini, geliştirme ekibi ise nasıl yapılacağını sahiplenir. Test, sprintin sonunda değil içinde sürekli yapılır.`,
qs:[
{t:`Scrum'da neyin yapılacağına ve önceliğine kim karar verir?`,o:[`Product Owner`,`Scrum Master`,`Sadece testçi`,`Rastgele bir kullanıcı`],e:`Ürünün yönü ve öncelikler Product Owner'ın sorumluluğundadır.`},
{t:`Scrum Master'ın temel görevi nedir?`,o:[`Sürecin sağlıklı işlemesini sağlamak ve engelleri kaldırmak`,`Tüm kodu yazmak`,`Tüm testleri yapmak`,`Fiyatları belirlemek`],e:`Ekibin önündeki taşları temizleyen kişidir.`},
{t:`Futbol benzetmesinde maç takvimi neye karşılık gelir?`,o:[`Sprint`,`Backlog`,`Bug`,`Deploy`],e:`Belirli aralıklarla tekrar eden, sonu belli dönemlerdir.`}
]},
{no:148,tr:`Sprint`,en:`Sprint`,
def:`Sprint, Scrum'da genelde 1-4 hafta süren, başında hedefi belirlenen ve sonunda çalışan bir ürün parçası teslim edilmesi beklenen sabit süreli çalışma döngüsüdür.`,
an:`Haftalık market listesi: hafta başında ne alınacağı belirlenir, hafta içinde alınır, hafta sonunda neyin alınıp neyin alınamadığına bakılır. Hafta ortasında liste keyfi değişmez.`,
fi:`Bir sprintin akışı:`,
code:[`SET sprint = { süre: 14, hedef: "Fatura PDF indirme canlıda" }   // gün`,
`SET sprint_backlog = CALL planlamada_seç(product_backlog)`,
`FOR EACH gün IN sprint`,
`    CALL işleri_ilerlet(sprint_backlog)`,
`END FOR`,
`FOR EACH iş IN sprint_backlog`,
`    IF iş.done_kriterleri_karşılandı THEN SHOW "Tamamlandı"`,
`    ELSE CALL sonraki_sprinte_taşı(iş)`,
`END FOR`],
note:`Sprint süresince kapsam değişmemeye çalışılır; acil bir iş gelirse bilinçli olarak başka bir iş çıkarılır. Sprint sonunda biten işin test edilmiş ve kabul edilmiş olması beklenir.`,
qs:[
{t:`Sprint nedir?`,o:[`Başında hedefi belirlenen, sonunda çalışan bir parça teslim edilen sabit süreli döngü`,`Bir test aracı`,`Bir veritabanı tablosu`,`Bir HTTP hatası`],e:`Haftalık liste gibi: başı ve sonu belli.`},
{t:`Scrum'da bir sprint genelde ne kadar sürer?`,o:[`1-4 hafta`,`1 saat`,`1 yıl`,`Süresi belirsizdir`],e:`En yaygın süre 2 haftadır.`},
{t:`Sprint sonunda biten bir işten ne beklenir?`,o:[`Test edilmiş ve kabul kriterlerini karşılamış olması`,`Sadece kodunun yazılmış olması`,`Sadece tasarımının yapılmış olması`,`Hiçbir şey beklenmez`],e:`"Bitti" demek, kullanılabilir ve doğrulanmış demektir.`}
]},
{no:149,tr:`Backlog`,en:`Backlog`,
def:`Backlog, üründe yapılması planlanan tüm iş, özellik ve düzeltmelerin öncelik sırasına göre dizildiği listedir; sprint backlog ise bu listeden o sprintte yapılmak üzere seçilen kısımdır.`,
an:`Restoranın sipariş defteri: tüm siparişler sırayla yazılı (product backlog); mutfak bu akşam pişireceği siparişleri alıp tezgâha koyar (sprint backlog).`,
fi:`Backlog'dan sprint'e:`,
code:[`SET product_backlog = [`,
`    "PRJ-1234 Fatura PDF indirme",        // öncelik 1`,
`    "PRJ-1240 Fatura listesi filtresi",   // öncelik 2`,
`    "PRJ-1188 Eski ekran iyileştirmesi",  // öncelik 3`,
`    ...`,
`]`,
`SET kapasite = 30                          // story point`,
`SET sprint_backlog = CALL üstten_seç(product_backlog, kapasite)`],
note:`Backlog'u önceliklendirmek Product Owner'ın sorumluluğudur. İyi bakılmış bir backlog'da üstteki işler net, detaylı ve tahmin edilmiştir; alttakiler daha kaba olabilir.`,
qs:[
{t:`Product backlog nedir?`,o:[`Üründe yapılması planlanan işlerin öncelikli listesi`,`Bir log dosyası`,`Bir veritabanı yedeği`,`Bir tasarım aracı`],e:`Sipariş defteri gibi: her şey sıralı yazılı.`},
{t:`Sprint backlog nedir?`,o:[`Product backlog'dan o sprintte yapılmak üzere seçilen işler`,`Biten tüm projelerin listesi`,`Kapatılan bug'ların arşivi`,`Canlıdaki hata kayıtları`],e:`Bu akşam tezgâha konan siparişlerdir.`},
{t:`Backlog'un önceliklendirilmesi kimin sorumluluğundadır?`,o:[`Product Owner`,`Sadece testçinin`,`Sadece DevOps mühendisinin`,`Hiç kimsenin`],e:`Hangi işin önce yapılacağı ürün sahibinin kararıdır.`}
]},
{no:150,tr:`User Story`,en:`User Story`,
def:`User story, bir özelliği kullanıcının gözünden "kim, ne istiyor, neden istiyor" şeklinde kısa ve sade anlatan gereksinim formatıdır.`,
an:`Müşterinin garsona söylediği cümle: "Vejetaryen biri olarak etsiz bir ana yemek istiyorum, çünkü et yemiyorum." Teknik tarif değil, ihtiyacın kendisidir; nasıl pişirileceğine mutfak karar verir.`,
fi:`Bir user story'nin kalıbı:`,
code:[`// Kalıp: [Rol] olarak, [ihtiyaç] istiyorum, böylece [fayda]`,
``,
`ROL:      mobil uygulama kullanıcısı`,
`İHTİYAÇ:  son 6 aylık faturalarımı tek ekranda görmek`,
`FAYDA:    harcamamı kolayca takip edebilmek`,
`KABUL:    acceptance criteria'da tanımlı`],
note:`User story ne istendiğini anlatır, nasıl yapılacağını değil. Jira'da genelde bir story kaydı olarak açılır ve altına geliştirme ve test görevleri bağlanır.`,
qs:[
{t:`User story neyi anlatır?`,o:[`Kullanıcının ne istediğini ve nedenini`,`Kodun nasıl yazılacağını satır satır`,`Sunucunun donanımını`,`Veritabanı şemasını`],e:`İhtiyacı anlatır; çözümü ekibe bırakır.`},
{t:`User story kalıbındaki "böylece" kısmı neyi ifade eder?`,o:[`Kullanıcıya sağlanacak faydayı`,`Kullanıcının rolünü`,`Teknik çözümü`,`Test verisini`],e:`"Neden" sorusunun cevabıdır; önceliği belirlemede de işe yarar.`},
{t:`Garson benzetmesinde "nasıl pişirileceğine mutfak karar verir" ne anlatır?`,o:[`Story ihtiyacı anlatır, çözümü ekibe bırakır`,`Story kodu da içerir`,`Mutfak müşteriyi hiç dinlemez`,`Yemeği garson pişirir`],e:`Kullanıcı ne istediğini söyler; nasıl yapılacağı ekibin uzmanlığıdır.`}
]},
{no:151,tr:`Acceptance Criteria`,en:`Acceptance Criteria · Kabul Kriterleri`,
def:`Acceptance criteria, bir user story'nin tamamlanmış ve kabul edilmiş sayılması için karşılanması gereken ölçülebilir ve test edilebilir koşullardır.`,
an:`Terziden takım elbise siparişinin şartları: "Ceket omuzdan tam oturmalı, pantolon boyu ayakkabıya değmeli, teslim cuma." Teslimatta bu maddeler tek tek kontrol edilir.`,
fi:`Önceki story'nin kabul kriterleri:`,
code:[`Given kullanıcı giriş yapmış ve son 6 ayda 6 faturası var`,
`When "Faturalarım" ekranını açar`,
`Then 6 fatura en yeniden eskiye sıralı listelenir`,
`And her satırda dönem, tutar ve durum görünür`,
`And ödenmemiş faturalar kırmızı etiketle işaretlenir`,
`And fatura yoksa "Görüntülenecek fatura bulunmuyor" mesajı çıkar`],
note:`Kabul kriterleri test case'lerin doğrudan kaynağıdır: her kriter en az bir testle doğrulanır. Belirsiz kriterler ("hızlı açılmalı") yerine ölçülebilir olanlar ("2 saniyede açılmalı") yazılmalıdır.`,
qs:[
{t:`Acceptance criteria nedir?`,o:[`Story'nin kabul edilmesi için karşılanması gereken ölçülebilir koşullar`,`Kodun derlenme süresi`,`Bir veritabanı tablosu`,`Bir sprint toplantısının adı`],e:`Terzinin teslimatta kontrol edeceği maddeler gibi.`},
{t:`Hangisi iyi yazılmış bir kabul kriteridir?`,o:[`Fatura listesi 2 saniye içinde açılmalı`,`Ekran hızlı olmalı`,`Kullanıcı memnun olmalı`,`Her şey düzgün çalışmalı`],e:`Ölçülebilir olanı test edilebilir; diğerleri yoruma açıktır.`},
{t:`Kabul kriterleri ile test case'ler arasındaki ilişki nedir?`,o:[`Her kriter en az bir test case ile doğrulanır`,`Aralarında hiçbir ilişki yoktur`,`Test case'ler kriterlerin yerine geçer`,`Kriterler sadece canlıda kontrol edilir`],e:`Kriter "ne doğru olmalı" der, test case bunu nasıl kontrol edeceğini.`}
]},
{no:152,tr:`Estimation / Story Point`,en:`Estimation / Story Point`,
def:`Estimation, bir işin büyüklüğünün ekip tarafından önceden tahmin edilmesidir; story point ise bu büyüklüğü saat yerine iş miktarı, karmaşıklık ve belirsizliği birlikte yansıtan göreli bir puanla ifade eder.`,
an:`Taşınırken eşyaları "küçük, orta, büyük koli" diye ayırmak: tam ağırlığını tartmazsın ama hangisinin daha zor taşınacağını bilirsin. Story point de saat değil, göreli zorluktur.`,
fi:`Planning poker ile tahminleme:`,
code:[`SET puanlar = [1, 2, 3, 5, 8, 13]          // Fibonacci benzeri ölçek`,
`FOR EACH üye IN ekip`,
`    SET kart = CALL gizlice_puan_seç(story)`,
`END FOR`,
`CALL kartları_aç()`,
`IF en_yüksek - en_düşük > 3 THEN`,
`    CALL farklı_düşünenler_anlatsın()      // gizli efor burada çıkar`,
`    CALL tekrar_oyla()`,
`END IF`],
note:`Story point bir kişinin hızını değil ekibin ortak görüşünü ölçer; test, entegrasyon ve belirsizlik eforu da puana dahildir. Ekibin bir sprintte tamamladığı ortalama puana velocity (hız) denir.`,
qs:[
{t:`Story point neyi ifade eder?`,o:[`İşin miktar, karmaşıklık ve belirsizliğini yansıtan göreli büyüklüğü`,`Kesin saat cinsinden süreyi`,`Geliştiricinin maaşını`,`Sunucu sayısını`],e:`Koli boyutu gibi: kesin ağırlık değil, göreli zorluk.`},
{t:`Planning poker'da puanlar arasında büyük fark çıkarsa ne yapılır?`,o:[`Farklı düşünenler gerekçesini anlatır ve tekrar oylanır`,`En yüksek puan otomatik seçilir`,`Story silinir`,`Ortalama alınıp konu kapatılır`],e:`Fark genelde birinin gördüğü ama diğerlerinin kaçırdığı bir efordan kaynaklanır.`},
{t:`Bir story'nin puanı belirlenirken test eforu dahil edilmeli midir?`,o:[`Evet, puan işin tamamlanması için gereken tüm eforu kapsar`,`Hayır, sadece geliştirme sayılır`,`Sadece canlıda ölçülür`,`Hayır, test ayrı projede yapılır`],e:`İş test edilip kabul edilmeden bitmiş sayılmaz; eforu da puandadır.`}
]}
]);

add(14,`Agile ve iş dili`,[
{no:153,tr:`Daily Standup`,en:`Daily Standup`,
def:`Daily standup, ekibin her gün aynı saatte yaklaşık 15 dakika toplanıp dün ne yaptığını, bugün ne yapacağını ve önünde bir engel olup olmadığını paylaştığı kısa senkronizasyon toplantısıdır.`,
an:`Ralli takımının etap öncesi kısa brifingi: herkes nerede olduğunu, sıradaki etapta ne yapacağını ve bir sorun olup olmadığını söyler; detay tartışması sonra yapılır.`,
fi:`Her üyenin üç cevabı:`,
code:[`FOR EACH üye IN ekip`,
`    SHOW "Dün: ödeme ekranının validasyonlarını bitirdim"`,
`    SHOW "Bugün: fatura listesi filtresine başlayacağım"`,
`    SHOW "Engel: test ortamında CRM kapalı"     // ekip burada devreye girer`,
`END FOR`,
`IF bir_konu_uzuyor THEN CALL toplantı_sonrasına_taşı()   // 15 dk'yı aşma`],
note:`Standup bir durum raporu değil, ekibin birbirine yardım etmesi için yapılır; asıl değerli kısım engellerdir. Detaylı problem çözme toplantıdan sonra ilgili kişilerle yapılır.`,
qs:[
{t:`Daily standup'ta her üye hangi üç soruyu cevaplar?`,o:[`Dün ne yaptım, bugün ne yapacağım, önümde engel var mı`,`Maaşım ne, tatilim ne zaman, kim geç kaldı`,`Hatayı kim yaptı, kim cezalı, kim haklı`,`Proje ne zaman biter, bütçe ne, müşteri kim`],e:`Kısa ve ileriye dönük: ne yaptım, ne yapacağım, neye takıldım.`},
{t:`Standup'ta bir konu uzun tartışmaya dönüşürse ne yapılır?`,o:[`İlgili kişilerle toplantı sonrasına taşınır`,`Toplantı saatlerce uzatılır`,`Konu tamamen unutulur`,`Herkes konuyu tartışmak zorundadır`],e:`Brifing kısa kalır; detay ayrı konuşulur.`},
{t:`Standup'ın en değerli çıktısı nedir?`,o:[`Engellerin görünür olması ve birlikte çözülmesi`,`Yöneticiye ayrıntılı rapor`,`Herkesin çalışma saatinin kaydı`,`Kodun yeniden yazılması`],e:`Bir kişinin takıldığı yeri erken duymak, günlerce kaybı önler.`}
]},
{no:154,tr:`Retrospective`,en:`Retrospective`,
def:`Retrospective, sprint sonunda ekibin nasıl çalıştığını değerlendirip neyin iyi gittiğini, neyin geliştirilmesi gerektiğini ve bir sonraki sprintte neyi farklı yapacağını konuştuğu toplantıdır.`,
an:`Maç sonrası soyunma odası değerlendirmesi: skora değil oyunun kendisine bakılır: "pas trafiği iyiydi, savunma geçişlerinde geç kaldık, gelecek maç şunu deneyelim."`,
fi:`Bir retrospective'in çıktısı:`,
code:[`SET iyi_gidenler = ["Testler sprint içinde bitti", "Daily'ler kısa sürdü"]`,
`SET geliştirilecekler = [`,
`    "Test ortamı 3 gün kapalıydı",`,
`    "Story'ler geç netleşti"`,
`]`,
`SET aksiyonlar = [`,
`    { iş: "Ortam kesintisi için mock hazırla", sahibi: "QA" },`,
`    { iş: "Story'leri sprint öncesi gözden geçir", sahibi: "PO" }`,
`]`,
`CALL sonraki_retroda_kontrol_et(aksiyonlar)`],
note:`Retrospective'in amacı suçlu bulmak değil, süreci iyileştirmektir. Somut ve sahibi belli aksiyonlarla bitmeyen bir retro, aynı sorunların her sprintte tekrar konuşulmasına yol açar.`,
qs:[
{t:`Retrospective'in amacı nedir?`,o:[`Ekibin çalışma şeklini değerlendirip iyileştirmek`,`Suçlu bulmak`,`Yeni özellik tasarlamak`,`Kodu derlemek`],e:`Skora değil oyuna bakılır.`},
{t:`Bir retro'nun en önemli çıktısı nedir?`,o:[`Sahibi belli, somut iyileştirme aksiyonları`,`Uzun bir şikâyet listesi`,`Kimsenin sorumlu olmadığı genel dilekler`,`Yeni bir logo`],e:`Aksiyon yoksa değişim de olmaz.`},
{t:`Maç benzetmesinde retro neye karşılık gelir?`,o:[`Maç sonrası oyunun değerlendirilmesi`,`Maçın kendisi`,`Bilet satışı`,`Stadyum temizliği`],e:`Bir sonraki maçı daha iyi oynamak için geriye bakmaktır.`}
]},
{no:155,tr:`Definition of Done`,en:`Definition of Done · DoD`,
def:`Definition of Done, ekibin bir işi "bitti" sayabilmesi için tüm işlerde geçerli olan, önceden üzerinde anlaşılmış ortak kontrol listesidir.`,
an:`Pilotun kalkış öncesi kontrol listesi: her uçuşta aynı maddeler tek tek işaretlenir; biri bile eksikse uçak kalkmaz. "Bence hazır" yeterli değildir.`,
fi:`Örnek bir DoD:`,
code:[`SET dod = [`,
`    "Kod review'dan geçti",`,
`    "Unit testler yazıldı ve geçti",`,
`    "Kabul kriterleri test edildi",`,
`    "Açık kritik bug kalmadı",`,
`    "Otomasyon senaryoları eklendi",`,
`    "Test ortamına deploy edildi",`,
`    "Dokümantasyon güncellendi"`,
`]`,
`IF NOT tümü_karşılandı(dod) THEN SHOW "Bu iş henüz bitmedi"`],
note:`Acceptance criteria tek bir story'ye özeldir; DoD ise tüm işler için geçerli ortak standarttır. DoD sayesinde "geliştirme bitti ama test edilmedi" gibi yarım işler bitmiş sayılmaz.`,
qs:[
{t:`Definition of Done nedir?`,o:[`Bir işin bitti sayılması için tüm işlerde geçerli ortak kontrol listesi`,`Tek bir story'nin özel kabul kriterleri`,`Sprintin bitiş tarihi`,`Bir test aracı`],e:`Pilotun kontrol listesi gibi: her uçuşta aynı maddeler.`},
{t:`DoD ile acceptance criteria arasındaki fark nedir?`,o:[`DoD tüm işler için ortaktır, acceptance criteria tek bir story'ye özeldir`,`İkisi tamamen aynıdır`,`DoD sadece canlıda kullanılır`,`Acceptance criteria tüm projeler için ortaktır`],e:`Biri genel kalite standardı, diğeri o işe özel şartlardır.`},
{t:`Kodu yazılmış ama test edilmemiş bir iş DoD'ye göre nedir?`,o:[`Bitmemiştir`,`Bitmiştir`,`Canlıya çıkabilir`,`İptal edilmiştir`],e:`Listedeki tek bir madde eksikse uçak kalkmaz.`}
]},
{no:156,tr:`MVP`,en:`Minimum Viable Product`,
def:`MVP, bir ürünün gerçek kullanıcıya değer verebilecek ve geri bildirim toplanabilecek en küçük, en temel versiyonudur.`,
an:`Araba isteyen birine önce kaykay, sonra bisiklet, sonra motosiklet vermek: her aşamada kişi bir yere gidebilir. Önce tekerleği, sonra kasayı vermek MVP değildir; tek başına hiçbir işe yaramaz.`,
fi:`Bir fatura modülünün MVP ile planlanması:`,
code:[`SET mvp = ["Son faturayı görüntüle", "Faturayı kartla öde"]`,
`SET sonraki_sürümler = [`,
`    "PDF indir", "Geçmişi filtrele", "Otomatik ödeme talimatı"`,
`]`,
`CALL canlıya_al(mvp)`,
`CALL kullanıcı_geri_bildirimi_topla()`,
`CALL yeniden_önceliklendir(sonraki_sürümler)    // gerçek kullanıma göre`],
note:`MVP "yarım ürün" değil, küçük ama kendi başına işe yarayan üründür. Kapsam dar olsa da içindeki özelliklerin kalitesi tam olmalıdır.`,
qs:[
{t:`MVP nedir?`,o:[`Gerçek kullanıcıya değer verebilen en küçük ürün versiyonu`,`Ürünün tüm özellikleriyle bitmiş hali`,`Hiç çalışmayan bir taslak`,`Bir test aracı`],e:`Kaykay gibi: küçük ama gerçekten götürür.`},
{t:`Kaykay, bisiklet, araba benzetmesi neyi anlatır?`,o:[`Her aşamada kendi başına işe yarayan bir ürün sunmayı`,`Önce parçaları tek tek teslim etmeyi`,`Hiç teslimat yapmamayı`,`Sadece tasarım yapmayı`],e:`Tekerlek tek başına bir yere götürmez; kaykay götürür.`},
{t:`MVP'deki özelliklerin kalitesi için hangisi doğrudur?`,o:[`Kapsam dar olsa da kalite tam olmalıdır`,`MVP olduğu için hatalar önemsizdir`,`MVP hiç test edilmez`,`Sadece tasarım kalitesine bakılır`],e:`Az özellik, düşük kalite demek değildir.`}
]},
{no:157,tr:`Technical Debt`,en:`Technical Debt · Teknik Borç`,
def:`Technical debt, kısa vadede hızlı ilerlemek için seçilen kolay ama ideal olmayan çözümlerin, ileride kodu değiştirmeyi zorlaştırarak biriken ek maliyetidir.`,
an:`Kredi kartıyla alışveriş: bugün hızlıca alırsın ama ödemeyi ertelediğin her ay faiz biner. Teknik borç da ödenmedikçe her yeni geliştirmeyi biraz daha yavaşlatır.`,
fi:`Borcun nasıl biriktiği:`,
code:[`// Sprint 3: "Şimdilik kopyala yapıştır, sonra düzeltiriz"`,
`CALL kopyala(kdv_hesapla TO fatura, ödeme, rapor servisleri)`,
``,
`// Sprint 9: KDV oranı değişti`,
`CALL değiştir(fatura_servisi)          // 1. yer`,
`CALL değiştir(ödeme_servisi)           // 2. yer`,
`// rapor servisi unutuldu: raporda eski oran kaldı, bug`],
note:`Teknik borç her zaman kötü değildir; bir teslim tarihine yetişmek için bilinçli alınabilir. Sorun, borcun görünmez kalması ve hiç ödenmemesidir; bu yüzden backlog'a ayrı iş olarak yazılır ve refactor ile kapatılır.`,
qs:[
{t:`Technical debt nedir?`,o:[`Hızlı ilerlemek için seçilen ideal olmayan çözümlerin ileride yarattığı ek maliyet`,`Şirketin bankaya borcu`,`Sunucu kira bedeli`,`Kullanıcının fatura borcu`],e:`Kod içinde biriken, ileride ödenecek bir bedeldir.`},
{t:`Kredi kartı benzetmesinde "faiz" neye karşılık gelir?`,o:[`Borç ödenmedikçe her yeni geliştirmenin yavaşlaması`,`Kodu derleme süresi`,`Testlerin hızlanması`,`Sunucu sayısının azalması`],e:`Her değişiklik, karmaşık kod yüzünden biraz daha pahalıya gelir.`},
{t:`Teknik borç nasıl yönetilmelidir?`,o:[`Görünür yapılıp backlog'a yazılmalı ve planlı şekilde refactor ile kapatılmalı`,`Hiç konuşulmamalı`,`Sadece canlıda hata çıkınca düşünülmeli`,`Tüm kod silinmeli`],e:`Görünmeyen borç büyür; görünen borç planlanıp ödenebilir.`}
]},
{no:158,tr:`Scope ve Requirement`,en:`Scope and Requirement`,
def:`Requirement (gereksinim), yazılımın neyi yapması ya da hangi koşulu sağlaması gerektiğini tanımlayan ihtiyaçtır; scope (kapsam) ise bir proje ya da sprintte hangi gereksinimlerin yapılıp hangilerinin yapılmayacağını belirleyen sınırdır.`,
an:`Ev tadilatı: "Mutfakta ada tezgâh olsun" bir gereksinimdir. Scope ise "Bu tadilatta mutfak ve banyo var, salon yok" diye çizilen sınırdır. Sınır çizilmezse tadilat bitmez.`,
fi:`Kapsam içi ve dışı:`,
code:[`SET requirement = "Kullanıcı faturasını PDF olarak indirebilmeli"`,
`SET scope_içi  = ["Son 12 ayın faturaları", "Tek tek indirme"]`,
`SET scope_dışı = ["Toplu ZIP indirme", "E-postayla gönderme"]`,
`IF yeni_istek NOT IN scope_içi THEN`,
`    CALL change_request_aç(yeni_istek)     // kapsam bilinçli değişir`,
`END IF`],
note:`Fonksiyonel gereksinimler sistemin ne yapacağını (PDF indir), fonksiyonel olmayanlar nasıl yapacağını (2 saniyede, şifreli) anlatır. Kontrolsüz büyüyen kapsama scope creep denir; teslim tarihlerinin kaymasının en yaygın sebeplerindendir.`,
qs:[
{t:`Requirement nedir?`,o:[`Yazılımın neyi yapması ya da hangi koşulu sağlaması gerektiğini tanımlayan ihtiyaç`,`Bir veritabanı tablosu`,`Bir sunucu türü`,`Bir test aracı`],e:`"Mutfakta ada tezgâh olsun" gibi bir istektir.`},
{t:`"Fatura sayfası 2 saniye içinde açılmalı" ne tür bir gereksinimdir?`,o:[`Fonksiyonel olmayan (performans) gereksinim`,`Fonksiyonel gereksinim`,`Scope dışı istek`,`Bug kaydı`],e:`Ne yapılacağını değil, nasıl (ne hızda) yapılacağını anlatır.`},
{t:`Projenin kapsamının plansız şekilde sürekli genişlemesine ne denir?`,o:[`Scope creep`,`Rollback`,`Cache miss`,`Hotfix`],e:`Sınır çizilmeyen tadilat gibi: hiç bitmez.`}
]}
]);

add(15,`Günlük jargon`,[
{no:159,tr:`Refactor`,en:`Refactoring`,
def:`Refactor, kodun dışarıdan görünen davranışını değiştirmeden iç yapısını daha okunur, sade ve bakımı kolay hale getirmek için yeniden düzenlenmesidir.`,
an:`Mutfak dolaplarını yeniden düzenlemek: yemeğin tadı değişmez, ama malzemeyi bulmak ve yeni yemek yapmak çok kolaylaşır.`,
fi:`Tekrar eden kodun refactor edilmesi:`,
code:[`// Önce: aynı hesap üç yerde kopyalanmış`,
`SET fatura_kdv = tutar * 0.20`,
`SET ödeme_kdv  = tutar * 0.20`,
`SET rapor_kdv  = tutar * 0.20`,
``,
`// Sonra: tek bir fonksiyonda toplandı`,
`FUNCTION kdv_hesapla(tutar)`,
`    RETURN tutar * KDV_ORANI`,
`END FUNCTION`,
`SET fatura_kdv = CALL kdv_hesapla(tutar)     // davranış aynı, yapı daha iyi`],
note:`Refactor sonrası davranış değişmediği için yeni özellik testi gerekmez ama regresyon testi şarttır. "Sadece refactor yaptım" denen değişikliklerde de istemeden davranış değişebilir.`,
qs:[
{t:`Refactor nedir?`,o:[`Kodun davranışını değiştirmeden iç yapısını iyileştirmek`,`Yeni özellik eklemek`,`Kodu silmek`,`Kodu canlıya almak`],e:`Dolabı düzenlemek: tat aynı, düzen daha iyi.`},
{t:`Refactor sonrası en önemli test hangisidir?`,o:[`Regresyon testi`,`Yeni özellik kabul testi`,`Tasarım testi`,`Hiçbir test gerekmez`],e:`Amaç "hiçbir şey değişmedi" demek olduğu için mevcut davranış doğrulanır.`},
{t:`Dolap benzetmesinde "yemeğin tadının değişmemesi" neyi anlatır?`,o:[`Kullanıcının gördüğü davranışın aynı kalmasını`,`Kodun silinmesini`,`Yeni özellik eklenmesini`,`Sunucunun değişmesini`],e:`Dışarıdan bakan için hiçbir şey değişmemelidir.`}
]},
{no:160,tr:`Legacy`,en:`Legacy System`,
def:`Legacy, hâlâ kullanılan ve işi sürdüren ama eski teknolojilerle yazılmış, değiştirilmesi zor ve çoğu zaman belgesi eksik sistemdir.`,
an:`Eski ama sağlam bir binanın tesisatı: su akıyor, elektrik yanıyor; ama bir prizi değiştirmek isteyince duvarın arkasından ne çıkacağını kimse tam bilmiyor.`,
fi:`Legacy ile yaşamak:`,
code:[`// Yeni sistem eski CRM'e doğrudan dokunmaz`,
`SEND istek TO entegrasyon_katmanı       // araya bir katman koy`,
`CALL entegrasyon_katmanı.dönüştür()     // yeni formatı eskisine çevir`,
`SEND soap_istek TO legacy_crm           // yıllardır ayakta olan sistem`,
`IF legacy_crm_değişikliği_gerekli THEN`,
`    CALL dikkatli_planla()              // belge eksik, test ortamı kısıtlı`,
`END IF`],
note:`Legacy sistemler çoğu zaman şirketin en kritik verisini (müşteri, fatura) taşır; bu yüzden bir anda değiştirilemez. Yeni sistemler genelde onların önüne konan entegrasyon katmanlarıyla kurulur.`,
qs:[
{t:`Legacy sistem nedir?`,o:[`Hâlâ kullanılan ama eski teknolojiyle yazılmış, değiştirilmesi zor sistem`,`Yeni yazılmış modern bir servis`,`Silinmiş bir uygulama`,`Bir test aracı`],e:`Eski bina gibi: çalışıyor ama dokunmak riskli.`},
{t:`Legacy sistemler neden hemen değiştirilemez?`,o:[`Kritik veriyi ve iş süreçlerini taşırlar; değişiklik riski yüksektir`,`Hiç kullanılmadıkları için`,`Çok yeni oldukları için`,`Sadece testte çalıştıkları için`],e:`Duvarın arkasında ne olduğu tam bilinmeden yıkım yapılmaz.`},
{t:`Yeni sistemler legacy sistemlerle genelde nasıl konuşur?`,o:[`Araya konan entegrasyon katmanı üzerinden`,`Legacy sistemin kodunu baştan yazarak`,`Hiç konuşmazlar`,`Kullanıcı veriyi elle taşır`],e:`Katman, eski sistemin karmaşıklığını yeni sistemlerden saklar.`}
]},
{no:161,tr:`Deprecated`,en:`Deprecated`,
def:`Deprecated, bir fonksiyonun, API'nin ya da özelliğin hâlâ çalıştığını ama artık önerilmediğini ve ileriki bir sürümde kaldırılacağını belirten işarettir.`,
an:`"Bu köprü 1 Ocak'ta kapanacak, lütfen yeni köprüyü kullanın" tabelası: köprü bugün hâlâ açık ama ona güvenerek yeni plan yapmamalısın.`,
fi:`Deprecated bir endpoint:`,
code:[`GET /v1/faturalar/{id}`,
`// Response header: Deprecation: true`,
`// Response header: Sunset: Sun, 31 Jan 2027 00:00:00 GMT`,
`// Uyarı: v1 kaldırılacak, /v2/faturalar kullanın`,
``,
`IF istemci_v1_kullanıyor THEN`,
`    CALL v2_geçişini_planla()          // kaldırılmadan önce`,
`END IF`],
note:`IDE'ler deprecated fonksiyonların üstünü çizer; derleme uyarı verir ama hata vermez. Deprecated bir API kaldırıldığında ona bağımlı sistemler bir anda kırılır; bu yüzden geçiş takvimi önemlidir.`,
qs:[
{t:`Deprecated ne anlama gelir?`,o:[`Hâlâ çalışıyor ama önerilmiyor ve ileride kaldırılacak`,`Tamamen silinmiş`,`Yeni eklenmiş`,`Sadece testte çalışıyor`],e:`Köprü açık ama kapanma tarihi belli.`},
{t:`Köprü tabelası benzetmesinde doğru davranış nedir?`,o:[`Kapanmadan önce yeni köprüye geçişi planlamak`,`Eski köprüyü kullanmaya devam edip hiçbir şey yapmamak`,`Köprüyü hemen yıkmak`,`Tabelayı kaldırmak`],e:`Uyarı, zaman varken geçiş yapılsın diye verilir.`},
{t:`Deprecated bir API belirtilen tarihte kaldırılırsa, hâlâ onu kullanan sistemlere ne olur?`,o:[`Bir anda kırılırlar`,`Hiçbir şey olmaz`,`Kendiliğinden yeni API'ye geçerler`,`Daha hızlı çalışırlar`],e:`Köprü kapandığında hâlâ oradan geçmeye çalışan herkes yolda kalır.`}
]},
{no:162,tr:`Workaround`,en:`Workaround`,
def:`Workaround, bir sorunun kalıcı çözümü gelene kadar işin aksamaması için kullanılan geçici ve dolambaçlı çözüm yoludur.`,
an:`Asansör bozukken merdiveni kullanmak: sorunu çözmez ama kata çıkmanı sağlar. Asansör tamir edilene kadar herkes bunu bilir ve uygular.`,
fi:`Bir hata için workaround tanımlamak:`,
code:[`SET bug = "Fatura PDF butonu Safari'de çalışmıyor"`,
`SET kalıcı_çözüm = "Frontend düzeltmesi, 2 sprint sonra"`,
`SET workaround = "Chrome ya da Edge kullanılması"       // geçici yol`,
`CALL bug_kaydına_yaz(workaround)`,
`CALL kullanıcıları_bilgilendir(workaround)`,
`IF kalıcı_çözüm_canlıda THEN CALL workaround_kaldır()`],
note:`Bir hatanın önceliği belirlenirken "workaround var mı?" diye sorulur; makul bir workaround varsa öncelik düşebilir. Workaround'lar kalıcılaşırsa teknik borca dönüşür.`,
qs:[
{t:`Workaround nedir?`,o:[`Kalıcı çözüm gelene kadar kullanılan geçici çözüm yolu`,`Hatanın kalıcı düzeltmesi`,`Yeni bir özellik`,`Bir test aracı`],e:`Merdiven gibi: asansörü onarmaz ama işini görür.`},
{t:`Asansör benzetmesinde workaround neye karşılık gelir?`,o:[`Merdiveni kullanmak`,`Asansörü tamir etmek`,`Binayı yıkmak`,`Asansörü boyamak`],e:`Kalıcı çözüm asansörün tamiridir; merdiven geçici yoldur.`},
{t:`Bir hatanın makul bir workaround'u olması önceliğini nasıl etkileyebilir?`,o:[`Önceliği düşebilir`,`Önceliği her zaman en yükseğe çıkar`,`Hata kendiliğinden kapanır`,`Önceliği hiçbir şekilde etkilemez`],e:`Kullanıcı işini yapabiliyorsa düzeltme biraz bekleyebilir.`}
]},
{no:163,tr:`Edge Case`,en:`Edge Case · Uç Durum`,
def:`Edge case (uç durum), sistemin normal kullanım dışında kalan, sınır değerlerde ya da nadir koşullarda nasıl davrandığını gösteren durumdur.`,
an:`Asansörün tam taşıma kapasitesine yüklenmesi ya da kapı kapanırken birinin elini uzatması: günlük kullanımda nadir görülür ama sistemin sağlamlığı burada anlaşılır.`,
fi:`Bir tutar alanı için uç durumlar (kural: 1 ile 50.000 TL arası):`,
code:[`SET denemeler = [`,
`    0,          // alt sınırın altı`,
`    1,          // alt sınır`,
`    50000,      // üst sınır`,
`    50000.01,   // üst sınırın hemen üstü`,
`    -1,         // negatif`,
`    null,       // boş`,
`    "abc",      // tip hatası`,
`    0.001       // kuruştan küçük`,
`]`],
note:`Hataların büyük kısmı ortada değil kenarlarda çıkar: sınır değerler, boş listeler, ay sonu, artık yıl, gece yarısı, özel karakterli isimler. Sınır değer analizi bu durumları sistemli şekilde bulmanın yoludur.`,
qs:[
{t:`Edge case nedir?`,o:[`Sistemin sınır değerlerde ya da nadir koşullardaki davranışını gösteren durum`,`Sistemin en sık kullanılan akışı`,`Bir veritabanı tablosu`,`Bir tasarım aracı`],e:`Asansörün tam kapasitedeki hali gibi.`},
{t:`Tutar alanı 1 ile 50.000 TL arasında olmalıysa hangisi bir uç durum denemesidir?`,o:[`50.000,01 TL girmek`,`250 TL girmek`,`1.000 TL girmek`,`5.000 TL girmek`],e:`Üst sınırın hemen üstü, kuralın doğru uygulandığını en iyi sınayan değerdir.`},
{t:`Hataların büyük kısmı genelde nerede çıkar?`,o:[`Sınırlarda ve nadir koşullarda`,`Sadece en sık kullanılan akışta`,`Sadece tasarım dosyalarında`,`Hiçbir zaman`],e:`Geliştirici çoğunlukla ortadaki normal akışı düşünür; kenarlar gözden kaçar.`}
]}
]);

add(15,`Günlük jargon`,[
{no:164,tr:`Root Cause`,en:`Root Cause · Kök Neden`,
def:`Root cause (kök neden), bir sorunun görünen belirtisinin arkasındaki, düzeltildiğinde sorunun tekrar etmesini engelleyen asıl sebeptir.`,
an:`Tavandan su damlıyor: kova koymak belirtiyle uğraşmaktır. Kök neden üst kattaki çatlak borudur; boru tamir edilmezse kova hep dolar.`,
fi:`"5 Neden" ile kök nedene inmek:`,
code:[`SET sorun = "Müşteri faturasını göremiyor"`,
`// Neden? API 504 dönüyor`,
`// Neden? CRM 30 saniyede cevap vermiyor`,
`// Neden? Fatura sorgusu tüm tabloyu tarıyor`,
`// Neden? Yeni eklenen kolon için index oluşturulmamış`,
`// Neden? Veritabanı değişiklikleri review sürecine dahil değil`,
`SET kök_neden = "DB değişikliklerinin review'dan geçmemesi"`,
`SET çözüm = ["Index ekle", "DB değişikliklerini review'a dahil et"]`],
note:`Belirtiyi düzeltmek (sunucuyu yeniden başlatmak gibi) sorunu geçici olarak giderir; kök neden düzeltilmezse sorun geri gelir. Incident sonrası postmortem raporunun ana konusu kök nedendir.`,
qs:[
{t:`Root cause nedir?`,o:[`Sorunun görünen belirtisinin arkasındaki asıl sebep`,`Ekranda görünen hata mesajı`,`Sorunu ilk fark eden kişi`,`Sorunun çözüldüğü tarih`],e:`Damlayan su belirtidir; çatlak boru kök nedendir.`},
{t:`Damlayan tavan benzetmesinde "kova koymak" neye karşılık gelir?`,o:[`Belirtiyle uğraşmak`,`Kök nedeni düzeltmek`,`Kök neden analizi`,`Kalıcı çözüm`],e:`Kova suyu toplar ama damlamayı durdurmaz.`},
{t:`"5 Neden" tekniğinin amacı nedir?`,o:[`Art arda "neden" sorarak belirtiden kök nedene inmek`,`Beş farklı test aracı kullanmak`,`Beş kişiye görev vermek`,`Beş gün beklemek`],e:`Her cevap bir alt katmana iner; son cevap genelde süreçte ya da tasarımdadır.`}
]},
{no:165,tr:`Bottleneck`,en:`Bottleneck · Darboğaz`,
def:`Bottleneck (darboğaz), bir sistemin ya da sürecin tamamının hızını sınırlayan en yavaş ya da en kısıtlı noktadır.`,
an:`Şişenin boğazı: şişe ne kadar geniş olursa olsun su ancak boğazın izin verdiği hızda akar. Gövdeyi büyütmek işe yaramaz; boğazı genişletmek gerekir.`,
fi:`Darboğazı bulmak:`,
code:[`SET adımlar = {                  // milisaniye`,
`    frontend:     50,`,
`    gateway:      10,`,
`    backend:      40,`,
`    crm_sorgusu:  2400,            // darboğaz`,
`    pdf_üretimi:  300`,
`}`,
`SET darboğaz = CALL en_yavaş(adımlar)        // crm_sorgusu`,
`// Backend'i 2 kat hızlandırmak toplamı neredeyse hiç değiştirmez`],
note:`Darboğaz sadece teknik değildir; süreçte de olur: tek bir kişinin onayını bekleyen işler ya da tek bir test ortamını paylaşan beş ekip gibi. İyileştirme çabası önce darboğaza harcanmalıdır.`,
qs:[
{t:`Bottleneck nedir?`,o:[`Sistemin tamamının hızını sınırlayan en yavaş nokta`,`Sistemin en hızlı bileşeni`,`Bir veritabanı yedeği`,`Bir tasarım hatası`],e:`Şişe boğazı gibi: akış ondan hızlı olamaz.`},
{t:`Yukarıdaki örnekte toplam süreyi en çok düşürecek iyileştirme hangisidir?`,o:[`CRM sorgusunu hızlandırmak`,`Gateway'i hızlandırmak`,`Frontend'i hızlandırmak`,`Backend'i hızlandırmak`],e:`Toplam 2800 ms'nin 2400 ms'i tek bir adımda harcanıyor.`},
{t:`Şişe benzetmesinde "gövdeyi büyütmek" neden işe yaramaz?`,o:[`Akış hızını boğaz belirlediği için`,`Gövde camdan olduğu için`,`Su miktarı azaldığı için`,`Şişe kırılacağı için`],e:`Darboğaz dışındaki iyileştirmeler toplam hızı değiştirmez.`}
]},
{no:166,tr:`Hardcode`,en:`Hardcoding`,
def:`Hardcode, değişebilecek bir değeri (adres, şifre, oran, ID) ayar ya da parametre olarak almak yerine doğrudan kodun içine sabit olarak yazmaktır.`,
an:`Duvara yapıştırılmış takvim: bu yıl için doğru, ama yıl değişince duvarı kazımadan değiştiremezsin. Asılı takvim (config) ise sökülür, yenisi takılır.`,
fi:`Hardcode ve doğrusu:`,
code:[`// Hardcode: ortam değişince kod da değişmek zorunda`,
`SET crm_url = "http://10.20.30.40:8080/crm"`,
`SET kdv = 0.20`,
`SET şifre = "Crm2026!"                          // güvenlik açığı`,
``,
`// Doğrusu: dışarıdan al`,
`SET crm_url = CALL config("CRM_URL")`,
`SET kdv = CALL config("KDV_ORANI")`,
`SET şifre = CALL secret_kasası("CRM_PASSWORD")`],
note:`Hardcode edilmiş bir test ortamı adresi canlıya çıktığında ya da hardcode edilmiş bir oran değiştiğinde hata kaçınılmazdır. Otomasyon testlerinde de hardcode test verisi, veri değişince testlerin toplu kırılmasına yol açar.`,
qs:[
{t:`Hardcode nedir?`,o:[`Değişebilecek bir değeri doğrudan kodun içine sabit yazmak`,`Kodu şifrelemek`,`Kodu silmek`,`Kodu test etmek`],e:`Duvara yapıştırılmış takvim gibi: değiştirmek için duvarı kazımak gerekir.`},
{t:`Koda gömülü bir şifre neden ciddi bir sorundur?`,o:[`Kodu görebilen herkes şifreyi görür ve değiştirmek kod değişikliği gerektirir`,`Kodu yavaşlattığı için`,`Derlemeyi engellediği için`,`Renkleri bozduğu için`],e:`Hem güvenlik açığıdır hem de esnekliği yok eder.`},
{t:`Takvim benzetmesinde "asılı takvim" neye karşılık gelir?`,o:[`Config ya da ortam değişkeni`,`Hardcode`,`Veritabanı`,`Commit`],e:`Değeri koda dokunmadan değiştirebildiğin yerdir.`}
]},
{no:167,tr:`Breaking Change`,en:`Breaking Change`,
def:`Breaking change, bir API'de ya da sistemde yapılan ve onu kullanan diğer sistemlerin değişiklik yapmadan çalışmaya devam edememesine yol açan değişikliktir.`,
an:`Bir binanın tüm prizlerini yeni tip prize çevirmek: eski fişli bütün cihazlar bir anda çalışmaz hale gelir. Elektrik hâlâ var ama kimse kullanamaz.`,
fi:`Breaking olan ve olmayan değişiklikler:`,
code:[`// Eski cevap`,
`{ "musteriNo": 1002345, "tutar": 249.90 }`,
``,
`// Breaking değil: yeni alan eklemek`,
`{ "musteriNo": 1002345, "tutar": 249.90, "paraBirimi": "TRY" }`,
``,
`// Breaking: alan adını ya da tipini değiştirmek, alan silmek`,
`{ "customerId": "1002345", "amount": "249.90" }     // istemciler kırılır`],
note:`Breaking change gerekiyorsa genelde yeni versiyon (v2) açılır ve eski versiyon bir süre deprecated olarak yaşatılır. Kontrat (contract) testleri bu tür değişiklikleri canlıya çıkmadan yakalamayı sağlar.`,
qs:[
{t:`Breaking change nedir?`,o:[`Kullanan sistemlerin değişiklik yapmadan çalışamaz hale geldiği değişiklik`,`Sadece yeni alan eklenmesi`,`Kodun yorum satırlarının değişmesi`,`Bir bug düzeltmesi`],e:`Priz değişti; eski fişler artık takılamıyor.`},
{t:`Hangisi breaking change'dir?`,o:[`musteriNo alanının adını customerId yapmak`,`Cevaba yeni bir alan eklemek`,`Log mesajını değiştirmek`,`Cevap süresini kısaltmak`],e:`Eski istemci musteriNo arıyor; bulamayınca kırılır.`},
{t:`Breaking change gerektiğinde genelde ne yapılır?`,o:[`Yeni versiyon (v2) açılır, eskisi bir süre deprecated olarak yaşatılır`,`Eski versiyon aynı gün silinir`,`Kullanan sistemlere haber verilmez`,`Değişiklik gizlenir`],e:`Yeni prizler takılırken bir süre adaptörlü eski prizler de bırakılır.`}
]},
{no:168,tr:`Backward Compatibility`,en:`Backward Compatibility · Geriye Dönük Uyumluluk`,
def:`Backward compatibility, bir sistemin yeni sürümünün, eski sürüme göre yazılmış istemcileri, verileri ve entegrasyonları değişiklik gerektirmeden desteklemeye devam etmesidir.`,
an:`Yeni telefonun eski şarj kablonla da şarj olması: yeni gelir ama eskiyi dışarıda bırakmaz.`,
fi:`Uyumlu bir değişiklik:`,
code:[`// v1.5: yeni alan eklendi, eski alanlar aynen duruyor`,
`RETURN {`,
`    "musteriNo": 1002345,      // eski istemciler kullanmaya devam eder`,
`    "tutar": 249.90,`,
`    "paraBirimi": "TRY"        // yeni istemciler isterse kullanır`,
`}`,
`// Eski mobil uygulama sürümü: değişiklik yapmadan çalışır`],
note:`Kullanıcılar mobil uygulamayı hemen güncellemediği için backend'in eski uygulama sürümlerini bir süre desteklemesi gerekir. Yeni sürümü eski istemcilerle de denemek, uyumluluğun kanıtıdır.`,
qs:[
{t:`Backward compatibility nedir?`,o:[`Yeni sürümün eski istemcileri değişiklik gerektirmeden desteklemesi`,`Eski sürümün silinmesi`,`Sadece yeni istemcilerin çalışması`,`Kodun geriye doğru çalıştırılması`],e:`Eski kablo, yeni telefonda da çalışır.`},
{t:`Bir API'ye yeni bir alan eklemek genelde geriye uyumlu mudur?`,o:[`Evet, eski istemciler yeni alanı görmezden gelip çalışmaya devam eder`,`Hayır, her yeni alan breaking change'dir`,`Hayır, yeni alan eski alanları siler`,`Evet, ama sadece XML'de`],e:`Eski istemci tanımadığı alanı okumaz; bildiği alanlar yerinde durur.`},
{t:`Mobil uygulamalarda backward compatibility neden özellikle önemlidir?`,o:[`Kullanıcılar hemen güncellemediği için eski sürümler bir süre daha backend'e istek atar`,`Mobil uygulamalar hiç güncellenmediği için`,`Backend her gün silindiği için`,`Mobil uygulamalar internet kullanmadığı için`],e:`Aynı anda birçok uygulama sürümü canlıda yaşar; hepsi çalışmalıdır.`}
]}
]);
